-- =============================================================================
-- Realty OS - 0001_init.sql : authoritative Phase 1 schema
-- PostgreSQL 16. Plain SQL, forward-only. The migration runner executes each
-- file in ONE transaction (for manual runs: psql --single-transaction).
--
-- Conventions (see docs/DATA_MODEL.md for the full contract):
--   * ids are UUIDv7 generated by packages/core (injected id generator); no DB defaults.
--   * every tenant-scoped table has tenant_id NOT NULL, PRIMARY KEY (tenant_id, ...),
--     and every reference to a tenant row is a composite FK (tenant_id, x_id), so a
--     cross-tenant reference cannot be represented.
--   * references to users inside a tenant point at memberships(tenant_id, user_id).
--   * enums are text + CHECK everywhere (never CREATE TYPE ... AS ENUM).
--   * RLS: layer 1 = one RESTRICTIVE tenant_isolation policy per tenant table
--     (tenant_id = app.tenant_id() AND principal_type = 'staff'); layer 2 =
--     PERMISSIVE role/visibility policies. ENABLE + FORCE on every table.
--   * append-only tables reject UPDATE/DELETE/TRUNCATE by trigger; the only DELETE
--     path is retention functions owned by app_retention.
--   * request context (SET LOCAL via set_config(..., true) inside the request tx):
--       app.tenant_id, app.user_id, app.actor_kind ('user'|'system'|'support'),
--       app.principal_type ('staff'), app.ownership_command (uuid, ownership tx only)
--     Unset/'' => NULL => zero rows (fail closed).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 0. Extensions, roles, schemas
-- -----------------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS citext;

-- Cluster roles. In production these are provisioned by ops before migrating
-- (creating a BYPASSRLS role needs superuser); in dev app_owner (superuser) creates them.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_user') THEN
    -- NOLOGIN placeholder; real environments: ALTER ROLE app_user LOGIN PASSWORD '...'
    CREATE ROLE app_user NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOINHERIT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_definer') THEN
    -- owns ONLY the reviewed SECURITY DEFINER helpers; nothing logs in as it
    CREATE ROLE app_definer NOLOGIN NOSUPERUSER BYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_retention') THEN
    -- owns ONLY retention/erasure functions; the one role append-only triggers let DELETE
    CREATE ROLE app_retention NOLOGIN NOSUPERUSER BYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
END $$;

-- Fail the migration if pre-provisioned roles are unsafe.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_user' AND (rolsuper OR rolbypassrls)) THEN
    RAISE EXCEPTION 'app_user must be NOSUPERUSER NOBYPASSRLS';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname IN ('app_definer','app_retention') AND (rolcanlogin OR rolsuper OR NOT rolbypassrls)) THEN
    RAISE EXCEPTION 'app_definer/app_retention must be NOLOGIN NOSUPERUSER BYPASSRLS';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_auth_members am
               JOIN pg_roles g ON g.oid = am.roleid
               JOIN pg_roles m ON m.oid = am.member
              WHERE m.rolname = 'app_user') THEN
    RAISE EXCEPTION 'app_user must not be a member of any role (it could SET ROLE to escape RLS)';
  END IF;
END $$;

CREATE SCHEMA app;    -- request context, visibility helpers, guards, job/definer functions
CREATE SCHEMA auth;   -- pre-authentication SECURITY DEFINER functions
REVOKE ALL ON SCHEMA app, auth FROM PUBLIC;
GRANT USAGE ON SCHEMA public, app, auth TO app_user, app_definer, app_retention;

-- -----------------------------------------------------------------------------
-- 1. Request context helpers (fail closed) and generic triggers
-- -----------------------------------------------------------------------------
CREATE FUNCTION app.tenant_id() RETURNS uuid LANGUAGE sql STABLE PARALLEL SAFE AS
$$ SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid $$;

CREATE FUNCTION app.user_id() RETURNS uuid LANGUAGE sql STABLE PARALLEL SAFE AS
$$ SELECT NULLIF(current_setting('app.user_id', true), '')::uuid $$;

CREATE FUNCTION app.actor_kind() RETURNS text LANGUAGE sql STABLE PARALLEL SAFE AS
$$ SELECT CASE NULLIF(current_setting('app.actor_kind', true), '')
            WHEN 'user' THEN 'user' WHEN 'system' THEN 'system' WHEN 'support' THEN 'support'
            ELSE 'none' END $$;

CREATE FUNCTION app.principal_type() RETURNS text LANGUAGE sql STABLE PARALLEL SAFE AS
$$ SELECT NULLIF(current_setting('app.principal_type', true), '') $$;

CREATE FUNCTION app.ownership_command() RETURNS uuid LANGUAGE sql STABLE PARALLEL SAFE AS
$$ SELECT NULLIF(current_setting('app.ownership_command', true), '')::uuid $$;

-- Per-contact serialization (inbound ingestion, opt-out, dispatch claim, enrollment changes).
CREATE FUNCTION app.lock_contact(p_contact_id uuid) RETURNS void LANGUAGE sql VOLATILE AS
$$ SELECT pg_advisory_xact_lock(hashtextextended(app.tenant_id()::text || ':contact:' || p_contact_id::text, 0)) $$;
-- Per-address serialization (dedup on intake, consent projection).
CREATE FUNCTION app.lock_address(p_address_hmac bytea) RETURNS void LANGUAGE sql VOLATILE AS
$$ SELECT pg_advisory_xact_lock(hashtextextended(app.tenant_id()::text || ':addr:' || encode(p_address_hmac, 'hex'), 0)) $$;

CREATE FUNCTION app.reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_user = 'app_retention' THEN
    RETURN OLD;   -- retention/erasure functions only
  END IF;
  RAISE EXCEPTION 'APPEND_ONLY: % on % rejected', TG_OP, TG_TABLE_NAME
    USING ERRCODE = 'insufficient_privilege';
END $$;

CREATE FUNCTION app.touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- -----------------------------------------------------------------------------
-- 2. Global (not tenant-scoped) tables
-- -----------------------------------------------------------------------------
CREATE TABLE tenants (
  id                    uuid PRIMARY KEY,
  slug                  citext NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,40}$'),
  name                  text NOT NULL CHECK (length(btrim(name)) > 0),
  status                text NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active','suspended','pending_deletion')),
  deletion_requested_at timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CHECK ((status = 'pending_deletion') = (deletion_requested_at IS NOT NULL))
);

CREATE TABLE users (
  id                  uuid PRIMARY KEY,
  email               citext NOT NULL UNIQUE CHECK (position('@' in email) > 1),
  email_verified_at   timestamptz,
  display_name        text NOT NULL CHECK (length(btrim(display_name)) > 0),
  password_hash       text CHECK (password_hash IS NULL OR password_hash LIKE '$argon2id$%'),
  password_changed_at timestamptz,
  mfa_totp_secret_enc bytea,            -- AES-256-GCM, platform key, AAD = users|mfa|id
  mfa_enabled_at      timestamptz,
  failed_login_count  integer NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0),
  locked_until        timestamptz,
  disabled_at         timestamptz,      -- platform kill switch
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  CHECK (mfa_enabled_at IS NULL OR mfa_totp_secret_enc IS NOT NULL)
);

CREATE TABLE sessions (
  id                  uuid PRIMARY KEY,
  token_hash          bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),   -- sha256(token)
  user_id             uuid NOT NULL REFERENCES users(id),
  active_tenant_id    uuid REFERENCES tenants(id),
  created_at          timestamptz NOT NULL,
  last_seen_at        timestamptz NOT NULL,
  idle_expires_at     timestamptz NOT NULL,
  absolute_expires_at timestamptz NOT NULL,
  mfa_verified_at     timestamptz,
  reauthenticated_at  timestamptz,
  revoked_at          timestamptz,
  revoked_reason      text CHECK (revoked_reason IN
                      ('logout','password_change','admin_revoke','membership_removed','rotation','suspicious','tenant_switch')),
  ip                  inet,
  user_agent          text,
  CHECK (idle_expires_at <= absolute_expires_at),
  CHECK ((revoked_at IS NULL) = (revoked_reason IS NULL))
);
CREATE INDEX sessions_user_live_idx ON sessions (user_id) WHERE revoked_at IS NULL;

CREATE TABLE auth_tokens (           -- password reset / email verification; definer-only
  token_hash    bytea PRIMARY KEY CHECK (octet_length(token_hash) = 32),
  purpose       text NOT NULL CHECK (purpose IN ('password_reset','email_verify')),
  user_id       uuid NOT NULL REFERENCES users(id),
  created_at    timestamptz NOT NULL,
  expires_at    timestamptz NOT NULL,
  used_at       timestamptz,
  superseded_at timestamptz,
  CHECK (expires_at > created_at)
);
CREATE INDEX auth_tokens_user_idx ON auth_tokens (user_id, purpose) WHERE used_at IS NULL AND superseded_at IS NULL;

CREATE TABLE auth_events (           -- append-only; global because failed logins have no tenant
  id              uuid PRIMARY KEY,
  occurred_at     timestamptz NOT NULL,
  event           text NOT NULL CHECK (event IN ('login_ok','login_failed','locked','logout','mfa_ok',
                  'mfa_failed','password_reset_requested','password_changed','session_revoked',
                  'tenant_switched','reauth_ok','invite_accepted')),
  user_id         uuid REFERENCES users(id),
  email_attempted_hash text,          -- sha256 hex of normalized email; never plaintext
  tenant_id       uuid REFERENCES tenants(id),
  ip              inet,
  user_agent      text
);
CREATE INDEX auth_events_user_idx ON auth_events (user_id, occurred_at DESC);

CREATE TABLE auth_attempts (         -- rate-limit counters; keys are hashed; definer-only
  key          text NOT NULL CHECK (key ~ '^[a-z_]+:[0-9a-f]{64}$'),
  window_start timestamptz NOT NULL,
  count        integer NOT NULL CHECK (count >= 0),
  PRIMARY KEY (key, window_start)
);

CREATE TABLE mfa_recovery_codes (
  user_id    uuid NOT NULL REFERENCES users(id),
  code_hash  bytea NOT NULL CHECK (octet_length(code_hash) = 32),
  created_at timestamptz NOT NULL DEFAULT now(),
  used_at    timestamptz,
  PRIMARY KEY (user_id, code_hash)
);

-- Platform-maintained, counsel-reviewed jurisdiction rule packs (data, never code).
CREATE TABLE jurisdiction_packs (
  key                    text NOT NULL CHECK (key ~ '^[A-Z]{2}(-[A-Z]{2})?$'),   -- 'US', 'US-SC'
  version                text NOT NULL,
  status                 text NOT NULL CHECK (status IN ('draft','published','retired')),
  rules                  jsonb NOT NULL CHECK (jsonb_typeof(rules) = 'object'),
  reviewed_by_counsel_at timestamptz,   -- NULL => UI must say "not yet reviewed by counsel"
  notes                  text,
  created_at             timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (key, version)
);
CREATE UNIQUE INDEX jurisdiction_packs_one_published ON jurisdiction_packs (key) WHERE status = 'published';

-- Provider webhook idempotency + unrouted log. Definer-only (pre-tenant).
CREATE TABLE webhook_events (
  id                uuid PRIMARY KEY,
  provider          text NOT NULL,
  provider_event_id text NOT NULL,
  tenant_id         uuid REFERENCES tenants(id),           -- NULL => unrouted
  received_at       timestamptz NOT NULL,
  signature_valid   boolean NOT NULL,
  status            text NOT NULL CHECK (status IN ('received','processed','unrouted','rejected','failed')),
  payload_enc       bytea,                                 -- platform key; purged after 30 days
  processed_at      timestamptz,
  error_code        text,
  UNIQUE (provider, provider_event_id),
  CHECK (signature_valid OR status = 'rejected')
);

-- -----------------------------------------------------------------------------
-- 3. Tenant organization, keys, policy, settings
-- -----------------------------------------------------------------------------
CREATE TABLE memberships (
  tenant_id               uuid NOT NULL REFERENCES tenants(id),
  user_id                 uuid NOT NULL REFERENCES users(id),
  role                    text NOT NULL CHECK (role IN ('owner','admin','team_lead','agent','isa','tc')),
  status                  text NOT NULL DEFAULT 'invited'
                          CHECK (status IN ('invited','active','suspended','deactivating','removed')),
  accepting_leads         boolean NOT NULL DEFAULT true,
  consecutive_missed_offers integer NOT NULL DEFAULT 0 CHECK (consecutive_missed_offers >= 0),
  auto_paused_at          timestamptz,
  alert_phone_e164        text CHECK (alert_phone_e164 ~ '^\+[1-9][0-9]{6,14}$'),
  alert_phone_verified_at timestamptz,
  home_jurisdiction       text,
  recording_notice_ack_at timestamptz,          -- agent's own acknowledgement of call recording
  invited_by_user_id      uuid,
  joined_at               timestamptz,
  removed_at              timestamptz,
  version                 integer NOT NULL DEFAULT 1,
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, user_id),
  FOREIGN KEY (tenant_id, invited_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK ((status = 'removed') = (removed_at IS NOT NULL)),
  CHECK (alert_phone_verified_at IS NULL OR alert_phone_e164 IS NOT NULL),
  CHECK (role <> 'tc' OR NOT accepting_leads)               -- TCs never own leads
);
CREATE INDEX memberships_user_idx ON memberships (user_id) WHERE status = 'active';

CREATE TABLE tenant_keys (           -- envelope keys wrapped by the platform KEK (KMS in prod)
  tenant_id    uuid NOT NULL REFERENCES tenants(id),
  purpose      text NOT NULL CHECK (purpose IN ('field','object','hmac')),
  key_version  integer NOT NULL CHECK (key_version >= 1),
  wrapped_key  bytea,
  kek_ref      text NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  retired_at   timestamptz,
  destroyed_at timestamptz,                                -- crypto-shred
  PRIMARY KEY (tenant_id, purpose, key_version),
  CHECK ((destroyed_at IS NULL) = (wrapped_key IS NOT NULL)),
  CHECK (purpose <> 'hmac' OR key_version = 1)            -- HMAC key never rotates (suppression matching)
);

CREATE TABLE invites (
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  id                 uuid NOT NULL,
  email              citext NOT NULL CHECK (position('@' in email) > 1),
  role               text NOT NULL CHECK (role IN ('owner','admin','team_lead','agent','isa','tc')),
  token_hash         bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  invited_by_user_id uuid NOT NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  expires_at         timestamptz NOT NULL,
  accepted_at        timestamptz,
  revoked_at         timestamptz,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, invited_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (expires_at <= created_at + interval '7 days')
);
CREATE UNIQUE INDEX invites_one_pending ON invites (tenant_id, email) WHERE accepted_at IS NULL AND revoked_at IS NULL;

CREATE TABLE teams (
  tenant_id  uuid NOT NULL REFERENCES tenants(id),
  id         uuid NOT NULL,
  name       text NOT NULL,
  is_default boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id)
);
CREATE UNIQUE INDEX teams_one_default ON teams (tenant_id) WHERE is_default;

CREATE TABLE team_members (
  tenant_id uuid NOT NULL,
  team_id   uuid NOT NULL,
  user_id   uuid NOT NULL,
  is_lead   boolean NOT NULL DEFAULT false,
  PRIMARY KEY (tenant_id, team_id, user_id),
  FOREIGN KEY (tenant_id, team_id) REFERENCES teams (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, user_id) REFERENCES memberships (tenant_id, user_id)
);
CREATE INDEX team_members_user_idx ON team_members (tenant_id, user_id);

CREATE TABLE support_access_grants (
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  id                 uuid NOT NULL,
  support_user_id    uuid NOT NULL REFERENCES users(id),
  granted_by_user_id uuid NOT NULL,
  reason             text NOT NULL CHECK (length(btrim(reason)) > 0),
  created_at         timestamptz NOT NULL DEFAULT now(),
  expires_at         timestamptz NOT NULL,
  revoked_at         timestamptz,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, granted_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (expires_at > created_at AND expires_at <= created_at + interval '72 hours')
);

-- Versioned, immutable compliance policy. Tenant values can only be EQUAL OR STRICTER than
-- the shipped defaults, except the contact window, which an Owner may widen up to the
-- platform floor (08:00-21:00) with a recorded attestation. Gate decisions cite the version.
CREATE TABLE compliance_policy_versions (
  tenant_id                  uuid NOT NULL REFERENCES tenants(id),
  id                         uuid NOT NULL,
  version_no                 integer NOT NULL CHECK (version_no >= 1),
  contact_window_start       time NOT NULL DEFAULT '09:00',   -- recipient-local, SMS + voice, all initiators
  contact_window_end         time NOT NULL DEFAULT '20:00',
  human_reply_window_minutes integer NOT NULL DEFAULT 30 CHECK (human_reply_window_minutes BETWEEN 0 AND 30),
  email_quiet_hours          boolean NOT NULL DEFAULT false,
  auto_sms_per_24h           smallint NOT NULL DEFAULT 1 CHECK (auto_sms_per_24h BETWEEN 0 AND 1),
  auto_sms_per_7d            smallint NOT NULL DEFAULT 3 CHECK (auto_sms_per_7d BETWEEN 0 AND 3),
  auto_email_per_24h         smallint NOT NULL DEFAULT 1 CHECK (auto_email_per_24h BETWEEN 0 AND 1),
  auto_email_per_7d          smallint NOT NULL DEFAULT 3 CHECK (auto_email_per_7d BETWEEN 0 AND 3),
  auto_cross_channel_per_24h smallint NOT NULL DEFAULT 2 CHECK (auto_cross_channel_per_24h BETWEEN 0 AND 2),
  manual_sms_confirm_after_24h smallint NOT NULL DEFAULT 3 CHECK (manual_sms_confirm_after_24h BETWEEN 1 AND 3),
  call_attempts_per_24h      smallint NOT NULL DEFAULT 3 CHECK (call_attempts_per_24h BETWEEN 1 AND 3),
  max_deferrals              smallint NOT NULL DEFAULT 3 CHECK (max_deferrals BETWEEN 1 AND 5),
  autonomous_categories      text[] NOT NULL
                             DEFAULT '{speed_to_lead_reply,reminder,booking_confirmation,nurture_step,search_alert}',
  opt_out_confirmation_sender text NOT NULL DEFAULT 'provider'
                             CHECK (opt_out_confirmation_sender IN ('provider','platform')),
  recording_enabled          boolean NOT NULL DEFAULT true,
  recording_mode             text NOT NULL DEFAULT 'announce_all'
                             CHECK (recording_mode IN ('announce_all','one_party_where_permitted')),
  loosening_attestation      text,           -- exact sentence the Owner confirmed
  created_by_user_id         uuid,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, version_no),
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (contact_window_start < contact_window_end),
  CHECK (contact_window_start >= time '08:00' AND contact_window_end <= time '21:00'),    -- platform floor
  CHECK (autonomous_categories <@ ARRAY['speed_to_lead_reply','reminder','booking_confirmation',
                                        'document_chase','nurture_step','search_alert']::text[]),
  CHECK ((contact_window_start >= time '09:00' AND contact_window_end <= time '20:00'
          AND recording_mode = 'announce_all')
         OR loosening_attestation IS NOT NULL)
);

CREATE TABLE tenant_settings (
  tenant_id                     uuid PRIMARY KEY REFERENCES tenants(id),
  brokerage_legal_name          text NOT NULL CHECK (length(btrim(brokerage_legal_name)) > 0),
  team_name                     text,
  brokerage_license_number      text,
  brokerage_postal_address      text,           -- required before any marketing email
  default_timezone              text NOT NULL,  -- IANA; validated by trigger
  operating_jurisdictions       text[] NOT NULL DEFAULT '{US}' CHECK (cardinality(operating_jurisdictions) >= 1),
  active_policy_id              uuid NOT NULL,
  routing_hours_start           time NOT NULL DEFAULT '08:00',
  routing_hours_end             time NOT NULL DEFAULT '21:00',
  offer_window_seconds          integer NOT NULL DEFAULT 300 CHECK (offer_window_seconds BETWEEN 30 AND 86400),
  max_offers                    integer NOT NULL DEFAULT 3 CHECK (max_offers BETWEEN 1 AND 10),
  first_touch_sla_seconds       integer NOT NULL DEFAULT 900 CHECK (first_touch_sla_seconds BETWEEN 60 AND 86400),
  first_touch_release_seconds   integer DEFAULT 1800
                                CHECK (first_touch_release_seconds IS NULL OR first_touch_release_seconds > first_touch_sla_seconds),
  reinquiry_sla_after_days      integer NOT NULL DEFAULT 7 CHECK (reinquiry_sla_after_days BETWEEN 1 AND 90),
  inactivity_release_days       integer DEFAULT 30 CHECK (inactivity_release_days IS NULL OR inactivity_release_days BETWEEN 7 AND 365),
  inactivity_warning_hours      integer NOT NULL DEFAULT 72 CHECK (inactivity_warning_hours BETWEEN 1 AND 336),
  auto_pause_after_misses       integer NOT NULL DEFAULT 3 CHECK (auto_pause_after_misses BETWEEN 1 AND 10),
  uncontacted_capacity_cap      integer NOT NULL DEFAULT 5 CHECK (uncontacted_capacity_cap BETWEEN 1 AND 50),
  isa_access_after_handoff_days integer NOT NULL DEFAULT 7 CHECK (isa_access_after_handoff_days BETWEEN 0 AND 90),
  recording_retention_days      integer NOT NULL DEFAULT 730 CHECK (recording_retention_days BETWEEN 30 AND 3650),
  team_lead_recording_access    boolean NOT NULL DEFAULT true,
  tc_recording_access           boolean NOT NULL DEFAULT false,
  transcribe_imported_recordings boolean NOT NULL DEFAULT false,
  agent_consent_entry_allowed   boolean NOT NULL DEFAULT true,
  soft_delete_purge_days        integer NOT NULL DEFAULT 30 CHECK (soft_delete_purge_days BETWEEN 7 AND 90),
  mfa_required_roles            text[] NOT NULL DEFAULT '{owner,admin}' CHECK (mfa_required_roles @> ARRAY['owner','admin']),
  session_idle_hours            integer NOT NULL DEFAULT 168 CHECK (session_idle_hours BETWEEN 1 AND 720),
  session_absolute_days         integer NOT NULL DEFAULT 30 CHECK (session_absolute_days BETWEEN 1 AND 90),
  notification_detail           text NOT NULL DEFAULT 'first_name_initial'
                                CHECK (notification_detail IN ('none','first_name_initial')),
  ai_enabled                    boolean NOT NULL DEFAULT true,
  version                       integer NOT NULL DEFAULT 1,
  updated_at                    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, active_policy_id) REFERENCES compliance_policy_versions (tenant_id, id),
  CHECK (routing_hours_start < routing_hours_end)
);

CREATE TABLE provider_credentials (
  tenant_id            uuid NOT NULL REFERENCES tenants(id),
  id                   uuid NOT NULL,
  provider             text NOT NULL CHECK (provider IN ('telephony','email','fub','mls','avm','dnc')),
  secret_enc           bytea,                   -- AES-256-GCM, tenant field key, AAD bound to row
  key_version          integer NOT NULL,
  external_account_ref text,                    -- e.g. per-tenant telephony subaccount id
  status               text NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked','purged')),
  created_by_user_id   uuid,
  created_at           timestamptz NOT NULL DEFAULT now(),
  purge_after          timestamptz,
  purged_at            timestamptz,
  updated_at           timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK ((status = 'purged') = (secret_enc IS NULL)),
  CHECK ((status = 'purged') = (purged_at IS NOT NULL))
);

CREATE TABLE stored_objects (        -- registry for every blob; per-object DEK
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  id                 uuid NOT NULL,
  purpose            text NOT NULL CHECK (purpose IN ('recording','mms','import_file','consent_evidence')),
  storage_key        text NOT NULL UNIQUE,
  content_type       text NOT NULL,
  byte_size          bigint NOT NULL CHECK (byte_size >= 0),
  sha256             bytea NOT NULL CHECK (octet_length(sha256) = 32),
  dek_wrapped        bytea,                     -- NULL once shredded
  key_version        integer NOT NULL,
  retention_until    timestamptz,
  legal_hold         boolean NOT NULL DEFAULT false,
  created_by_user_id uuid,
  created_at         timestamptz NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  blob_deleted_at    timestamptz,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (storage_key LIKE 'tenants/' || tenant_id::text || '/%'),     -- tenant-prefixed keys
  CHECK (deleted_at IS NOT NULL OR dek_wrapped IS NOT NULL),
  CHECK (blob_deleted_at IS NULL OR deleted_at IS NOT NULL)
);
CREATE INDEX stored_objects_pending_blob_delete ON stored_objects (deleted_at) WHERE deleted_at IS NOT NULL AND blob_deleted_at IS NULL;

-- -----------------------------------------------------------------------------
-- 4. Lead sources, ponds, routing, imports (referenced by contacts)
-- -----------------------------------------------------------------------------
CREATE TABLE lead_sources (
  tenant_id             uuid NOT NULL REFERENCES tenants(id),
  id                    uuid NOT NULL,
  name                  text NOT NULL,
  kind                  text NOT NULL CHECK (kind IN ('portal','website','referral','sphere','open_house','ads',
                        'sign_call','inbound_sms','inbound_call','manual','import','other')),
  ingest_token_hash     bytea UNIQUE CHECK (ingest_token_hash IS NULL OR octet_length(ingest_token_hash) = 32),
  consent_disclosure_id uuid,                 -- provider-attested consent language (FK added below)
  active                boolean NOT NULL DEFAULT true,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, name)
);

CREATE TABLE ponds (
  tenant_id            uuid NOT NULL REFERENCES tenants(id),
  id                   uuid NOT NULL,
  name                 text NOT NULL,
  is_default           boolean NOT NULL DEFAULT false,
  open_to_all          boolean NOT NULL DEFAULT true,
  eligible_roles       text[] NOT NULL DEFAULT '{agent,team_lead,isa}'
                       CHECK (eligible_roles <@ ARRAY['agent','team_lead','isa']::text[] AND cardinality(eligible_roles) >= 1),
  claims_per_day       integer NOT NULL DEFAULT 5 CHECK (claims_per_day BETWEEN 0 AND 50),
  claim_cooldown_hours integer NOT NULL DEFAULT 72 CHECK (claim_cooldown_hours BETWEEN 0 AND 720),
  reinquiry            text NOT NULL DEFAULT 'reroute' CHECK (reinquiry IN ('reroute','stay')),
  archived_at          timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  CHECK (NOT (is_default AND archived_at IS NOT NULL))
);
CREATE UNIQUE INDEX ponds_one_default ON ponds (tenant_id) WHERE is_default;

CREATE TABLE pond_members (
  tenant_id uuid NOT NULL,
  pond_id   uuid NOT NULL,
  user_id   uuid NOT NULL,
  PRIMARY KEY (tenant_id, pond_id, user_id),
  FOREIGN KEY (tenant_id, pond_id) REFERENCES ponds (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, user_id) REFERENCES memberships (tenant_id, user_id)
);

CREATE TABLE routing_rules (
  tenant_id            uuid NOT NULL REFERENCES tenants(id),
  id                   uuid NOT NULL,
  position             integer NOT NULL,
  name                 text NOT NULL,
  match                jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(match) = 'object'),
                       -- {sources:[uuid], lead_types:[...], zips:[...], price_min, price_max}; Zod in core
  strategy             text NOT NULL CHECK (strategy IN ('round_robin','weighted','direct','pond')),
  direct_user_id       uuid,
  target_pond_id       uuid,
  fallback_pond_id     uuid,
  offer_window_seconds integer CHECK (offer_window_seconds IS NULL OR offer_window_seconds BETWEEN 30 AND 86400),
  max_offers           integer CHECK (max_offers IS NULL OR max_offers BETWEEN 1 AND 10),
  enabled              boolean NOT NULL DEFAULT true,
  version              integer NOT NULL DEFAULT 1,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, position) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY (tenant_id, direct_user_id)   REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, target_pond_id)   REFERENCES ponds (tenant_id, id),
  FOREIGN KEY (tenant_id, fallback_pond_id) REFERENCES ponds (tenant_id, id),
  CHECK ((strategy = 'direct') = (direct_user_id IS NOT NULL)),
  CHECK ((strategy = 'pond') = (target_pond_id IS NOT NULL))
);

CREATE TABLE routing_rule_members (
  tenant_id uuid NOT NULL,
  rule_id   uuid NOT NULL,
  user_id   uuid NOT NULL,
  weight    integer NOT NULL DEFAULT 1 CHECK (weight BETWEEN 1 AND 100),
  PRIMARY KEY (tenant_id, rule_id, user_id),
  FOREIGN KEY (tenant_id, rule_id) REFERENCES routing_rules (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, user_id) REFERENCES memberships (tenant_id, user_id)
);

CREATE TABLE routing_rotation_state (   -- locked FOR UPDATE while choosing the next agent
  tenant_id  uuid NOT NULL,
  rule_id    uuid NOT NULL,
  cursor     jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(cursor) = 'object'),
  version    bigint NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, rule_id),
  FOREIGN KEY (tenant_id, rule_id) REFERENCES routing_rules (tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE import_batches (
  tenant_id              uuid NOT NULL REFERENCES tenants(id),
  id                     uuid NOT NULL,
  source                 text NOT NULL CHECK (source IN ('csv','fub_api','fub_export')),
  status                 text NOT NULL CHECK (status IN ('connection_test','snapshotting','dry_run','committing',
                         'committed','partially_committed','reverting','reverted','abandoned')),
  source_counts          jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(source_counts) = 'object'),
  source_snapshot_sha256 text CHECK (source_snapshot_sha256 IS NULL OR source_snapshot_sha256 ~ '^[0-9a-f]{64}$'),
  source_snapshot_at     timestamptz,
  credential_id          uuid,
  file_object_id         uuid,
  created_by_user_id     uuid NOT NULL,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  reverted_at            timestamptz,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, credential_id)      REFERENCES provider_credentials (tenant_id, id),
  FOREIGN KEY (tenant_id, file_object_id)     REFERENCES stored_objects (tenant_id, id),
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (status IN ('connection_test','snapshotting','abandoned') OR source_snapshot_sha256 IS NOT NULL),
  CHECK ((status = 'reverted') = (reverted_at IS NOT NULL))
);

CREATE TABLE import_stages (
  tenant_id            uuid NOT NULL,
  id                   uuid NOT NULL,
  batch_id             uuid NOT NULL,
  category             text NOT NULL CHECK (category IN ('contacts','ownership','notes','messages','call_recordings','consent')),
  seq                  smallint NOT NULL,
  status               text NOT NULL CHECK (status IN ('pending','dry_run_running','dry_run_ready','approved',
                       'committing','committed','verified','skipped','reverting','reverted','failed')),
  count_source         integer CHECK (count_source >= 0),
  count_will_import    integer CHECK (count_will_import >= 0),
  count_imported       integer CHECK (count_imported >= 0),
  count_needs_review   integer CHECK (count_needs_review >= 0),
  count_rejected       integer CHECK (count_rejected >= 0),
  count_duplicate      integer CHECK (count_duplicate >= 0),
  dry_run_completed_at timestamptz,
  approved_by_user_id  uuid,
  approved_at          timestamptz,
  committed_at         timestamptz,
  verified_by_user_id  uuid,
  verified_at          timestamptz,
  verification         jsonb,                    -- post-commit recount: source vs db, spot checks
  updated_at           timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, batch_id, category),
  FOREIGN KEY (tenant_id, batch_id)            REFERENCES import_batches (tenant_id, id),
  FOREIGN KEY (tenant_id, approved_by_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, verified_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (seq = CASE category WHEN 'contacts' THEN 1 WHEN 'ownership' THEN 2 WHEN 'notes' THEN 3
                             WHEN 'messages' THEN 4 WHEN 'call_recordings' THEN 5 WHEN 'consent' THEN 6 END),
  -- R-IMPORT-2: nothing commits without a completed dry run AND an approval
  CHECK (status NOT IN ('approved','committing','committed','verified')
         OR (dry_run_completed_at IS NOT NULL AND approved_at IS NOT NULL AND approved_by_user_id IS NOT NULL)),
  CHECK (status <> 'verified' OR (verified_at IS NOT NULL AND verified_by_user_id IS NOT NULL AND verification IS NOT NULL)),
  CHECK (status NOT IN ('committed','verified') OR committed_at IS NOT NULL)
);

CREATE TABLE import_records (
  tenant_id           uuid NOT NULL,
  id                  uuid NOT NULL,
  stage_id            uuid NOT NULL,
  source_ref          text NOT NULL,             -- FUB id or 'file.csv#row=42'
  raw_enc             bytea,                     -- original record, encrypted; purged after 30 days
  raw_purged_at       timestamptz,
  normalized          jsonb,
  outcome             text NOT NULL CHECK (outcome IN ('will_import','imported','needs_review','rejected',
                      'duplicate','merged','reverted','skipped')),
  issues              jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(issues) = 'array'),
  match_contact_id    uuid,
  target_table        text,
  target_id           uuid,
  reviewed_by_user_id uuid,
  review_decision     text CHECK (review_decision IN ('import','merge','reject')),
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, stage_id, source_ref),
  FOREIGN KEY (tenant_id, stage_id)            REFERENCES import_stages (tenant_id, id),
  FOREIGN KEY (tenant_id, reviewed_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK ((raw_enc IS NULL) = (raw_purged_at IS NOT NULL)),
  CHECK (review_decision IS NULL OR reviewed_by_user_id IS NOT NULL),
  CHECK (outcome <> 'imported' OR target_id IS NOT NULL)
);
CREATE INDEX import_records_review ON import_records (tenant_id, stage_id, outcome);

CREATE TABLE import_user_mappings (
  tenant_id         uuid NOT NULL,
  batch_id          uuid NOT NULL,
  source_user_ref   text NOT NULL,
  source_user_label text NOT NULL,
  target_kind       text NOT NULL CHECK (target_kind IN ('user','pond','unassigned')),
  target_user_id    uuid,
  target_pond_id    uuid,
  PRIMARY KEY (tenant_id, batch_id, source_user_ref),
  FOREIGN KEY (tenant_id, batch_id)       REFERENCES import_batches (tenant_id, id),
  FOREIGN KEY (tenant_id, target_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, target_pond_id) REFERENCES ponds (tenant_id, id),
  CHECK ((target_kind = 'user') = (target_user_id IS NOT NULL)),
  CHECK ((target_kind = 'pond') = (target_pond_id IS NOT NULL))
);

CREATE TABLE external_refs (          -- idempotent re-import: one local entity per external id
  tenant_id      uuid NOT NULL,
  system         text NOT NULL CHECK (system IN ('fub','csv')),
  entity_type    text NOT NULL CHECK (entity_type IN ('contact','note','message','call','recording','user','deal')),
  external_id    text NOT NULL,
  entity_id      uuid NOT NULL,
  import_batch_id uuid NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, system, entity_type, external_id),
  FOREIGN KEY (tenant_id, import_batch_id) REFERENCES import_batches (tenant_id, id)
);
CREATE INDEX external_refs_entity ON external_refs (tenant_id, entity_type, entity_id);

-- -----------------------------------------------------------------------------
-- 5. Contacts + ownership projection + ownership ledger
-- -----------------------------------------------------------------------------
CREATE TABLE contacts (
  tenant_id               uuid NOT NULL REFERENCES tenants(id),
  id                      uuid NOT NULL,
  first_name              text,
  last_name               text,
  display_name            text NOT NULL CHECK (length(btrim(display_name)) > 0),
  contact_type            text NOT NULL DEFAULT 'lead'
                          CHECK (contact_type IN ('lead','sphere','past_client','vendor','other')),
  intent                  text CHECK (intent IN ('buyer','seller','buyer_seller','renter','landlord','investor')),
  stage                   text NOT NULL DEFAULT 'new'
                          CHECK (stage IN ('new','attempting','connected','nurture','active','under_contract','closed','lost')),
  timezone                text,
  timezone_source         text CHECK (timezone_source IN ('explicit','address','area_code','tenant_default')),
  -- ownership projection (single writer: the ownership command path; see lead_ownership_events)
  ownership_state         text NOT NULL CHECK (ownership_state IN ('unassigned','offered','owned','in_pond','closed')),
  owner_user_id           uuid,
  pond_id                 uuid,
  offer_id                uuid,            -- fencing token of the current offer
  offered_to_user_id      uuid,
  offer_expires_at        timestamptz,
  offer_round             smallint NOT NULL DEFAULT 0 CHECK (offer_round >= 0),
  routing_rule_id         uuid,
  owned_at                timestamptz,
  first_touch_due_at      timestamptz,
  first_touch_at          timestamptz,
  first_touch_breached_at timestamptz,
  release_due_at          timestamptz,     -- auto-release if still untouched
  ownership_period_seq    bigint,          -- seq of the event that started the current ownership period (owned only);
                                           -- fences SLA timers, binds drafts, keys untouched_lead exceptions
  route_due_at            timestamptz,     -- unassigned and awaiting system routing (after a decline); sweeper backstop
  closed_reason           text CHECK (closed_reason IN ('spam','merged','do_not_contact','not_a_lead','deleted')),
  ownership_seq           bigint NOT NULL CHECK (ownership_seq >= 1),   -- ledger head: seq of the LAST ledger event
  ownership_command_id    uuid NOT NULL,   -- command that produced the projection
  ownership_actor_user_id uuid,            -- user actor of that command (NULL for system)
  -- non-guarded activity
  last_human_touch_at     timestamptz,
  last_inbound_at         timestamptz,
  inactivity_warn_at      timestamptz,     -- stored inactivity deadlines (R-OWN-23): computed by core with the settings
  inactivity_release_at   timestamptz,     -- in force at ownership start / last human touch; never derived from live settings
  pond_summary            text CHECK (pond_summary IS NULL OR length(pond_summary) <= 200),
  -- first-touch attribution (immutable once set; copied onto deals)
  original_lead_source_id uuid,
  original_campaign_ref   text,
  original_ad_ref         text,
  original_source_detail  jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(original_source_detail) = 'object'),
  tags                    text[] NOT NULL DEFAULT '{}',
  imported_fields         jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(imported_fields) = 'object'),   -- display-only
  merged_into_contact_id  uuid,
  import_batch_id         uuid,
  created_by_user_id      uuid,
  row_version             integer NOT NULL DEFAULT 1,
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),
  deleted_at              timestamptz,
  deleted_by_user_id      uuid,
  purge_after             timestamptz,
  search_tsv              tsvector GENERATED ALWAYS AS (
                            to_tsvector('simple'::regconfig,
                              coalesce(display_name, '') || ' ' || coalesce(first_name, '') || ' ' || coalesce(last_name, ''))
                          ) STORED,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, owner_user_id)           REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, offered_to_user_id)      REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, ownership_actor_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, created_by_user_id)      REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, deleted_by_user_id)      REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, pond_id)                 REFERENCES ponds (tenant_id, id),
  FOREIGN KEY (tenant_id, routing_rule_id)         REFERENCES routing_rules (tenant_id, id),
  FOREIGN KEY (tenant_id, original_lead_source_id) REFERENCES lead_sources (tenant_id, id),
  FOREIGN KEY (tenant_id, import_batch_id)         REFERENCES import_batches (tenant_id, id),
  FOREIGN KEY (tenant_id, merged_into_contact_id)  REFERENCES contacts (tenant_id, id) ON DELETE SET NULL (merged_into_contact_id),
  CONSTRAINT contacts_ownership_shape CHECK (
    CASE ownership_state
      WHEN 'unassigned' THEN owner_user_id IS NULL AND pond_id IS NULL AND offer_id IS NULL
                             AND offered_to_user_id IS NULL AND offer_expires_at IS NULL
      WHEN 'offered'    THEN owner_user_id IS NULL AND pond_id IS NULL AND offer_id IS NOT NULL
                             AND offered_to_user_id IS NOT NULL AND offer_expires_at IS NOT NULL
      WHEN 'owned'      THEN owner_user_id IS NOT NULL AND pond_id IS NULL AND offer_id IS NULL
                             AND offered_to_user_id IS NULL AND offer_expires_at IS NULL AND owned_at IS NOT NULL
      WHEN 'in_pond'    THEN owner_user_id IS NULL AND pond_id IS NOT NULL AND offer_id IS NULL
                             AND offered_to_user_id IS NULL AND offer_expires_at IS NULL
      WHEN 'closed'     THEN owner_user_id IS NULL AND pond_id IS NULL AND offer_id IS NULL
                             AND offered_to_user_id IS NULL AND offer_expires_at IS NULL
    END),
  CONSTRAINT contacts_owned_period CHECK (ownership_state = 'owned' OR
    (owned_at IS NULL AND first_touch_due_at IS NULL AND first_touch_at IS NULL
     AND first_touch_breached_at IS NULL AND release_due_at IS NULL
     AND inactivity_warn_at IS NULL AND inactivity_release_at IS NULL)),
  CONSTRAINT contacts_period_seq CHECK ((ownership_state = 'owned') = (ownership_period_seq IS NOT NULL)
    AND (ownership_period_seq IS NULL OR ownership_period_seq <= ownership_seq)),
  CHECK (route_due_at IS NULL OR ownership_state = 'unassigned'),
  CHECK ((ownership_state = 'closed') = (closed_reason IS NOT NULL)),
  CHECK (closed_reason IS DISTINCT FROM 'merged' OR merged_into_contact_id IS NOT NULL),
  CHECK (merged_into_contact_id IS NULL OR merged_into_contact_id <> id),
  CHECK ((deleted_at IS NULL) = (purge_after IS NULL)),
  CHECK (deleted_at IS NULL OR (ownership_state = 'closed' AND closed_reason = 'deleted'))
);
CREATE INDEX contacts_owner_idx      ON contacts (tenant_id, owner_user_id) WHERE deleted_at IS NULL;
CREATE INDEX contacts_offeree_idx    ON contacts (tenant_id, offered_to_user_id) WHERE ownership_state = 'offered';
CREATE INDEX contacts_pond_idx       ON contacts (tenant_id, pond_id) WHERE ownership_state = 'in_pond';
CREATE INDEX contacts_offer_due_idx  ON contacts (offer_expires_at) WHERE ownership_state = 'offered';
CREATE INDEX contacts_touch_due_idx  ON contacts (first_touch_due_at)
  WHERE ownership_state = 'owned' AND first_touch_at IS NULL AND first_touch_breached_at IS NULL;
CREATE INDEX contacts_release_due_idx ON contacts (release_due_at) WHERE ownership_state = 'owned' AND first_touch_at IS NULL;
CREATE INDEX contacts_inactivity_warn_idx ON contacts (inactivity_warn_at)
  WHERE ownership_state = 'owned' AND inactivity_warn_at IS NOT NULL;
CREATE INDEX contacts_inactivity_release_idx ON contacts (inactivity_release_at)
  WHERE ownership_state = 'owned' AND inactivity_release_at IS NOT NULL;
CREATE INDEX contacts_route_due_idx ON contacts (route_due_at) WHERE route_due_at IS NOT NULL;
CREATE INDEX contacts_search_idx     ON contacts USING gin (search_tsv);
CREATE INDEX contacts_name_trgm      ON contacts USING gin (display_name gin_trgm_ops);
CREATE INDEX contacts_tags_idx       ON contacts USING gin (tags);
CREATE INDEX contacts_purge_idx      ON contacts (purge_after) WHERE deleted_at IS NOT NULL;

-- Ownership ledger: append-only, gapless per contact, source of truth for the projection.
-- Deliberately NO FK to contacts so history survives purge/erasure (it holds no PII).
CREATE TABLE lead_ownership_events (
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  contact_id         uuid NOT NULL,
  seq                bigint NOT NULL CHECK (seq >= 1),
  event_id           uuid NOT NULL,
  type               text NOT NULL CHECK (type IN (
                       'created','imported','offered','offer_accepted','offer_declined','offer_expired',
                       'offer_rescinded','claimed','assigned','reassigned','released','sent_to_pond',
                       'auto_released','reinquiry','first_touch_recorded','first_touch_breached','sla_waived',
                       'inactivity_warned','inactivity_released','closed','reopened','merged_away','merged_in')),
  from_state         text CHECK (from_state IN ('unassigned','offered','owned','in_pond','closed')),
  to_state           text NOT NULL CHECK (to_state IN ('unassigned','offered','owned','in_pond','closed')),
  owner_user_id      uuid,               -- owner AFTER the event
  prev_owner_user_id uuid,
  pond_id            uuid,
  offer_id           uuid,
  offered_to_user_id uuid,
  routing_rule_id    uuid,
  deadline_at        timestamptz,        -- offered: offer expiry; owned: first-touch due
  actor_kind         text NOT NULL CHECK (actor_kind IN ('user','system','timer','import','provider')),
  actor_user_id      uuid,
  reason_code        text NOT NULL CHECK (reason_code ~ '^[A-Z][A-Z0-9_]*$'),
  note               text CHECK (note IS NULL OR length(note) <= 500),
  command_id         uuid NOT NULL,      -- idempotency: one command => one event set
  payload            jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(payload) = 'object'),  -- ids/codes only
  occurred_at        timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, contact_id, seq),
  UNIQUE (tenant_id, event_id),
  CHECK (actor_kind <> 'user' OR actor_user_id IS NOT NULL),
  CHECK ((to_state = 'owned') = (owner_user_id IS NOT NULL))
);
CREATE INDEX loe_command_idx    ON lead_ownership_events (tenant_id, command_id);
CREATE INDEX loe_owner_time_idx ON lead_ownership_events (tenant_id, owner_user_id, occurred_at DESC);
CREATE INDEX loe_actor_type_idx ON lead_ownership_events (tenant_id, actor_user_id, type, occurred_at DESC);
CREATE INDEX loe_prev_owner_idx ON lead_ownership_events (tenant_id, contact_id, prev_owner_user_id, occurred_at DESC);
CREATE INDEX loe_type_time_idx  ON lead_ownership_events (tenant_id, type, occurred_at DESC);

-- Rejected ownership commands (lost claim race, late accept, stale UI, limits). Append-only and kept
-- OUT of the gapless per-contact ledger so the projection seq always equals the ledger head (F3).
-- The loser of a race usually cannot see the contact any more, so this table needs no contact visibility.
CREATE TABLE ownership_command_rejections (
  tenant_id     uuid NOT NULL REFERENCES tenants(id),
  id            uuid NOT NULL,
  contact_id    uuid,                  -- no FK (like the ledger); NULL for create-time rejections
  command_id    uuid NOT NULL,
  command_kind  text NOT NULL CHECK (command_kind ~ '^[a-z_]+$'),
  code          text NOT NULL CHECK (code ~ '^[A-Z][A-Z0-9_]*$'),
  observed_seq  bigint CHECK (observed_seq IS NULL OR observed_seq >= 1),   -- ledger head seen under the lock
  actor_kind    text NOT NULL CHECK (actor_kind IN ('user','system','timer','import','provider')),
  actor_user_id uuid,
  payload       jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(payload) = 'object'),   -- ids/codes only
  occurred_at   timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, command_id),       -- one command => at most one rejection (idempotent replay)
  CHECK (actor_kind <> 'user' OR actor_user_id IS NOT NULL)
);
CREATE INDEX ocr_contact_idx ON ownership_command_rejections (tenant_id, contact_id, occurred_at DESC);
CREATE INDEX ocr_actor_idx   ON ownership_command_rejections (tenant_id, actor_user_id, occurred_at DESC);

CREATE TABLE contact_points (
  tenant_id       uuid NOT NULL,
  id              uuid NOT NULL,
  contact_id      uuid NOT NULL,
  kind            text NOT NULL CHECK (kind IN ('phone','email')),
  address         text NOT NULL,              -- E.164 / lower-case email (normalized in core)
  address_hmac    bytea NOT NULL CHECK (octet_length(address_hmac) = 32),  -- joins consent/suppression keys
  label           text NOT NULL DEFAULT 'other' CHECK (label IN ('mobile','home','work','other')),
  line_type       text NOT NULL DEFAULT 'unknown' CHECK (line_type IN ('mobile','landline','voip','toll_free','unknown')),
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active','invalid','wrong_number','bouncing','removed')),
  is_primary      boolean NOT NULL DEFAULT false,
  timezone        text,                       -- explicit, overrides inference
  import_batch_id uuid,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  removed_at      timestamptz,
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, contact_id, kind, address),
  FOREIGN KEY (tenant_id, contact_id)      REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, import_batch_id) REFERENCES import_batches (tenant_id, id),
  CHECK (kind <> 'phone' OR address ~ '^\+[1-9][0-9]{6,14}$'),
  CHECK (kind <> 'email' OR (address = lower(address) AND position('@' in address) > 1)),
  CHECK ((status = 'removed') = (removed_at IS NOT NULL))
);
CREATE INDEX contact_points_address_idx ON contact_points (tenant_id, kind, address) WHERE removed_at IS NULL;
CREATE INDEX contact_points_hmac_idx    ON contact_points (tenant_id, address_hmac);
CREATE INDEX contact_points_contact_idx ON contact_points (tenant_id, contact_id);
CREATE INDEX contact_points_trgm        ON contact_points USING gin (address gin_trgm_ops);
CREATE UNIQUE INDEX contact_points_one_primary ON contact_points (tenant_id, contact_id, kind)
  WHERE is_primary AND removed_at IS NULL;

CREATE TABLE contact_addresses (
  tenant_id    uuid NOT NULL,
  id           uuid NOT NULL,
  contact_id   uuid NOT NULL,
  kind         text NOT NULL CHECK (kind IN ('home','mailing','property','interest')),
  line1        text,
  line2        text,
  city         text,
  region       text,                    -- state / province
  postal_code  text,
  country      text NOT NULL DEFAULT 'US' CHECK (country ~ '^[A-Z]{2}$'),
  jurisdiction text CHECK (jurisdiction IS NULL OR jurisdiction ~ '^[A-Z]{2}(-[A-Z]{2})?$'),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, contact_id) REFERENCES contacts (tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX contact_addresses_contact_idx ON contact_addresses (tenant_id, contact_id);
CREATE INDEX contact_addresses_postal_idx  ON contact_addresses (tenant_id, postal_code);

CREATE TABLE contact_collaborators (   -- ISA after handoff, TC, co-agent: access without ownership
  tenant_id        uuid NOT NULL,
  contact_id       uuid NOT NULL,
  user_id          uuid NOT NULL,
  role             text NOT NULL CHECK (role IN ('isa','tc','co_agent')),
  added_by_user_id uuid,
  created_at       timestamptz NOT NULL DEFAULT now(),
  expires_at       timestamptz,
  removed_at       timestamptz,
  PRIMARY KEY (tenant_id, contact_id, user_id),
  FOREIGN KEY (tenant_id, contact_id)       REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, user_id)          REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, added_by_user_id) REFERENCES memberships (tenant_id, user_id)
);
CREATE INDEX contact_collaborators_user_idx ON contact_collaborators (tenant_id, user_id) WHERE removed_at IS NULL;

CREATE TABLE contact_attributes (     -- includes fair-housing protected proxies (VA, PCS ...)
  tenant_id         uuid NOT NULL,
  id                uuid NOT NULL,
  contact_id        uuid NOT NULL,
  key               text NOT NULL CHECK (key ~ '^[a-z][a-z0-9_]{1,63}$'),
  value             jsonb NOT NULL,
  sensitivity       text NOT NULL DEFAULT 'normal' CHECK (sensitivity IN ('normal','protected_proxy')),
  self_reported     boolean NOT NULL DEFAULT false,
  evidence_claim_id uuid,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, contact_id, key),
  FOREIGN KEY (tenant_id, contact_id) REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  -- R-AST-12: known protected-proxy keys are always classified as such, and only self-reported
  CHECK (key NOT IN ('military_status','va_loan_interest','pcs_orders','pcs_timeline','source_of_income',
                     'familial_status','disability','religion','national_origin')
         OR sensitivity = 'protected_proxy'),
  CHECK (sensitivity <> 'protected_proxy' OR self_reported)
);

CREATE TABLE lead_inquiries (
  tenant_id             uuid NOT NULL,
  id                    uuid NOT NULL,
  contact_id            uuid NOT NULL,
  lead_source_id        uuid NOT NULL,
  external_id           text,
  received_at           timestamptz NOT NULL,
  inquiry_type          text NOT NULL CHECK (inquiry_type IN ('buy','sell','rent','value','general')),
  message               text,
  listing_id            uuid,
  property_text         text,
  postal_code           text,
  price_min_cents       bigint CHECK (price_min_cents >= 0),
  price_max_cents       bigint CHECK (price_max_cents >= 0),
  campaign_ref          text,
  ad_ref                text,
  source_detail         jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(source_detail) = 'object'),  -- utm etc.
  consent_disclosure_id uuid,
  raw_payload_enc       bytea,                  -- purged after 90 days
  fingerprint           text NOT NULL,          -- sha256(source + normalized identifiers + type)
  outcome               text NOT NULL CHECK (outcome IN ('new_contact','attached','reinquiry','duplicate_ignored')),
  created_at            timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, contact_id)     REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, lead_source_id) REFERENCES lead_sources (tenant_id, id),
  CHECK (price_min_cents IS NULL OR price_max_cents IS NULL OR price_min_cents <= price_max_cents)
);
CREATE UNIQUE INDEX lead_inquiries_external_uq ON lead_inquiries (tenant_id, lead_source_id, external_id) WHERE external_id IS NOT NULL;
CREATE INDEX lead_inquiries_fingerprint_idx ON lead_inquiries (tenant_id, fingerprint, received_at DESC);
CREATE INDEX lead_inquiries_contact_idx ON lead_inquiries (tenant_id, contact_id, received_at DESC);

CREATE TABLE contact_duplicate_candidates (
  tenant_id           uuid NOT NULL,
  id                  uuid NOT NULL,
  contact_a_id        uuid NOT NULL,
  contact_b_id        uuid NOT NULL,
  match_reason        text NOT NULL CHECK (match_reason IN ('shared_phone','shared_email','phone_email_split',
                      'name_postal','trigram_name','import')),
  status              text NOT NULL DEFAULT 'open' CHECK (status IN ('open','merged','dismissed')),
  decided_by_user_id  uuid,
  decided_at          timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, contact_a_id, contact_b_id),
  FOREIGN KEY (tenant_id, contact_a_id) REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, contact_b_id) REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, decided_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (contact_a_id < contact_b_id),
  CHECK ((status = 'open') = (decided_at IS NULL))
);

CREATE TABLE behavior_events (       -- append-only per-contact behavior stream (A7c)
  tenant_id   uuid NOT NULL,
  id          uuid NOT NULL,
  contact_id  uuid NOT NULL,
  event_type  text NOT NULL CHECK (event_type IN ('listing_saved','listing_viewed','website_visit','email_opened',
              'email_clicked','search_alert_opened','search_alert_clicked','form_submitted')),
  reliability text NOT NULL CHECK (reliability IN ('fact','signal')),
  listing_id  uuid,
  source      text NOT NULL,
  occurred_at timestamptz NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now(),
  dedupe_key  text NOT NULL,
  payload     jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(payload) = 'object'),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, dedupe_key),
  FOREIGN KEY (tenant_id, contact_id) REFERENCES contacts (tenant_id, id),   -- NO cascade: purge deletes explicitly
  -- Apple MPP: opens are signals, never facts
  CHECK (event_type NOT IN ('email_opened','search_alert_opened') OR reliability = 'signal')
);
CREATE INDEX behavior_events_contact_idx ON behavior_events (tenant_id, contact_id, occurred_at DESC);
CREATE INDEX behavior_events_time_brin ON behavior_events USING brin (occurred_at);

-- -----------------------------------------------------------------------------
-- 6. Consent, suppressions, DNC, gate decisions (keyed by address HMAC, no plaintext)
-- -----------------------------------------------------------------------------
CREATE TABLE consent_disclosures (    -- exact consent language a person saw; append-only
  tenant_id     uuid NOT NULL REFERENCES tenants(id),
  id            uuid NOT NULL,
  channel_scope text[] NOT NULL CHECK (channel_scope <@ ARRAY['sms','voice','email']::text[] AND cardinality(channel_scope) >= 1),
  purpose_scope text[] NOT NULL CHECK (purpose_scope <@ ARRAY['marketing','informational']::text[] AND cardinality(purpose_scope) >= 1),
  body          text NOT NULL CHECK (length(body) > 0),
  body_sha256   text NOT NULL,
  names_seller  text NOT NULL,          -- the entity the text actually names
  source_kind   text NOT NULL CHECK (source_kind IN ('own_form','lead_provider','signed_document_template')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, body_sha256),
  CHECK (body_sha256 = encode(digest(body, 'sha256'), 'hex'))
);

ALTER TABLE lead_sources ADD FOREIGN KEY (tenant_id, consent_disclosure_id) REFERENCES consent_disclosures (tenant_id, id);
ALTER TABLE lead_inquiries ADD FOREIGN KEY (tenant_id, consent_disclosure_id) REFERENCES consent_disclosures (tenant_id, id);

CREATE TABLE consent_events (         -- append-only consent ledger; projection in consent_state
  tenant_id               uuid NOT NULL REFERENCES tenants(id),
  id                      uuid NOT NULL,
  address_kind            text NOT NULL CHECK (address_kind IN ('phone','email')),
  address_hmac            bytea NOT NULL CHECK (octet_length(address_hmac) = 32),
  address_hint            text NOT NULL CHECK (length(address_hint) <= 40),    -- '•••-•••-4821'
  channel                 text NOT NULL CHECK (channel IN ('sms','voice','email')),
  purpose                 text NOT NULL CHECK (purpose IN ('marketing','informational','all')),
  event_type              text NOT NULL CHECK (event_type IN ('grant','revoke','resubscribe','expire','import_revert')),
  consent_level           text NOT NULL CHECK (consent_level IN ('none','imported_unverified','inquiry','express','express_written')),
  source                  text NOT NULL CHECK (source IN ('web_form','lead_provider','inbound_first_contact',
                          'inbound_keyword','inbound_language','verbal_on_call','agent_entry','signed_document',
                          'provider_report','wrong_number','agent_revoke','import_fub','import_csv','system_expiry')),
  occurred_at             timestamptz NOT NULL,       -- when the person acted
  recorded_at             timestamptz NOT NULL DEFAULT now(),
  contact_id              uuid,                       -- context only; the key is the address
  actor_kind              text NOT NULL CHECK (actor_kind IN ('user','system')),
  actor_user_id           uuid,
  disclosure_id           uuid,
  evidence_object_id      uuid,
  evidence_message_id     uuid,                       -- no FK: consent outlives purged messages
  evidence_call_id        uuid,
  evidence_call_offset_ms integer CHECK (evidence_call_offset_ms >= 0),
  evidence                jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(evidence) = 'object'),
  imported                boolean NOT NULL DEFAULT false,
  import_record_id        uuid,
  original_provenance     jsonb,                      -- verbatim source fields for imported rows
  reverts_event_id        uuid,                       -- import_revert: the imported grant it voids
  expires_at              timestamptz,
  needs_review            boolean NOT NULL DEFAULT false,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, disclosure_id)      REFERENCES consent_disclosures (tenant_id, id),
  FOREIGN KEY (tenant_id, evidence_object_id) REFERENCES stored_objects (tenant_id, id),
  FOREIGN KEY (tenant_id, import_record_id)   REFERENCES import_records (tenant_id, id),
  FOREIGN KEY (tenant_id, reverts_event_id)   REFERENCES consent_events (tenant_id, id),
  CHECK (actor_kind <> 'user' OR actor_user_id IS NOT NULL),
  CHECK (address_kind <> 'phone' OR channel IN ('sms','voice')),
  CHECK (address_kind <> 'email' OR channel = 'email'),
  CHECK (imported = (source IN ('import_fub','import_csv'))),
  CHECK (NOT imported OR (import_record_id IS NOT NULL AND original_provenance IS NOT NULL)),
  -- R-CONSENT-3: imports never manufacture consent above imported_unverified
  CHECK (NOT imported OR event_type <> 'grant' OR consent_level = 'imported_unverified'),
  CHECK (imported OR consent_level <> 'imported_unverified'),
  -- R-CONSENT-4: express written consent cites the disclosure text or a signed document
  CHECK (consent_level <> 'express_written' OR disclosure_id IS NOT NULL OR evidence_object_id IS NOT NULL),
  CHECK (source <> 'verbal_on_call' OR evidence_call_id IS NOT NULL),
  CHECK (source <> 'agent_entry' OR consent_level IN ('none','express')),
  CHECK (source <> 'inbound_first_contact' OR (consent_level = 'express' AND purpose = 'informational')),
  CHECK (source <> 'signed_document' OR evidence_object_id IS NOT NULL),
  CHECK (event_type NOT IN ('revoke','expire','import_revert') OR consent_level = 'none'),
  CHECK (event_type <> 'grant' OR consent_level <> 'none'),
  CHECK (event_type <> 'resubscribe' OR (channel = 'sms' AND source = 'inbound_keyword')),
  CHECK ((event_type = 'import_revert') = (reverts_event_id IS NOT NULL)),
  CHECK (consent_level <> 'inquiry' OR expires_at IS NOT NULL)
);
CREATE INDEX consent_events_key_idx ON consent_events (tenant_id, channel, address_hmac, occurred_at, id);

CREATE TABLE consent_state (          -- projection; rebuilt by core.projectConsent(events)
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  channel            text NOT NULL CHECK (channel IN ('sms','voice','email')),
  purpose            text NOT NULL CHECK (purpose IN ('marketing','informational')),
  address_hmac       bytea NOT NULL CHECK (octet_length(address_hmac) = 32),
  status             text NOT NULL CHECK (status IN ('granted','revoked','none')),
  consent_level      text NOT NULL CHECK (consent_level IN ('none','imported_unverified','inquiry','express','express_written')),
  basis_event_id     uuid,
  expires_at         timestamptz,
  ledger_event_count integer NOT NULL CHECK (ledger_event_count >= 1),
  computed_at        timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, channel, purpose, address_hmac),
  FOREIGN KEY (tenant_id, basis_event_id) REFERENCES consent_events (tenant_id, id),
  CHECK (status <> 'granted' OR consent_level <> 'none'),
  CHECK (status = 'granted' OR consent_level = 'none')
);

CREATE TABLE suppressions (           -- "what the world/system says" (not consent)
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  id                 uuid NOT NULL,
  address_kind       text NOT NULL CHECK (address_kind IN ('phone','email')),
  address_hmac       bytea NOT NULL CHECK (octet_length(address_hmac) = 32),
  address_hint       text NOT NULL CHECK (length(address_hint) <= 40),
  channel            text NOT NULL CHECK (channel IN ('sms','voice','email','all')),
  reason             text NOT NULL CHECK (reason IN ('hard_bounce','spam_complaint','undeliverable','landline_no_sms',
                     'internal_dnc','admin_block','wrong_number','provider_opt_out','import_dnc')),
  source_ref         jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(source_ref) = 'object'),
  imported           boolean NOT NULL DEFAULT false,
  import_record_id   uuid,
  created_by_user_id uuid,
  created_at         timestamptz NOT NULL DEFAULT now(),
  lifted_at          timestamptz,
  lifted_by_user_id  uuid,
  lift_reason        text,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, import_record_id) REFERENCES import_records (tenant_id, id),
  CHECK ((lifted_at IS NULL) = (lift_reason IS NULL)),
  CHECK ((lifted_at IS NULL) = (lifted_by_user_id IS NULL)),
  CHECK (reason <> 'spam_complaint' OR lifted_at IS NULL),            -- only a fresh opt-in action can follow
  CHECK (imported = (reason = 'import_dnc')),
  CHECK (NOT imported OR import_record_id IS NOT NULL)
);
CREATE UNIQUE INDEX suppressions_active_uq ON suppressions (tenant_id, address_hmac, channel, reason) WHERE lifted_at IS NULL;

CREATE TABLE dnc_checks (             -- registry scrub results; append-only
  tenant_id           uuid NOT NULL REFERENCES tenants(id),
  id                  uuid NOT NULL,
  phone_hmac          bytea NOT NULL CHECK (octet_length(phone_hmac) = 32),
  registry            text NOT NULL CHECK (registry ~ '^(us_national|us_state:[A-Z]{2})$'),
  listed              boolean NOT NULL,
  checked_at          timestamptz NOT NULL,
  valid_until         timestamptz NOT NULL,
  provider            text NOT NULL CHECK (provider IN ('fake','manual_upload','vendor')),
  uploaded_by_user_id uuid,
  created_at          timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  CHECK (valid_until > checked_at)
);
CREATE INDEX dnc_checks_latest_idx ON dnc_checks (tenant_id, phone_hmac, registry, checked_at DESC);

CREATE TABLE gate_decisions (         -- every canContact() evaluation that matters; append-only
  tenant_id            uuid NOT NULL REFERENCES tenants(id),
  id                   uuid NOT NULL,
  contact_id           uuid,                         -- context only
  recipient_kind       text NOT NULL DEFAULT 'contact' CHECK (recipient_kind IN ('contact','user')),
  recipient_user_id    uuid,
  address_hmac         bytea NOT NULL CHECK (octet_length(address_hmac) = 32),
  channel              text NOT NULL CHECK (channel IN ('sms','voice','email')),
  purpose              text NOT NULL CHECK (purpose IN ('marketing','informational')),
  initiator            text NOT NULL CHECK (initiator IN ('human','assistant','system')),
  action_category      text NOT NULL CHECK (action_category IN ('none','speed_to_lead_reply','reminder',
                       'booking_confirmation','document_chase','nurture_step','search_alert','opt_out_confirmation',
                       'help_reply','agent_alert','money','contract','novel_message','seller_update')),
  phase                text NOT NULL CHECK (phase IN ('preview','send','confirm')),
  outcome              text NOT NULL CHECK (outcome IN ('allow','deny','defer','needs_confirmation')),
  reason_codes         text[] NOT NULL DEFAULT '{}',
  defer_until          timestamptz,
  explanation          text NOT NULL,
  actor_user_id        uuid,
  confirmed_by_user_id uuid,
  confirms_decision_id uuid,
  policy_version_id    uuid NOT NULL,
  core_rules_version   text NOT NULL,
  inputs               jsonb NOT NULL CHECK (jsonb_typeof(inputs) = 'object'),  -- facts used; never plaintext addresses
  inputs_sha256        text NOT NULL CHECK (inputs_sha256 ~ '^[0-9a-f]{64}$'),
  message_id           uuid,
  call_id              uuid,
  evaluated_at         timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, policy_version_id)    REFERENCES compliance_policy_versions (tenant_id, id),
  FOREIGN KEY (tenant_id, confirms_decision_id) REFERENCES gate_decisions (tenant_id, id),
  CHECK (outcome <> 'defer' OR defer_until IS NOT NULL),
  CHECK (outcome = 'allow' OR cardinality(reason_codes) > 0),
  CHECK (phase <> 'confirm' OR (outcome = 'allow' AND confirmed_by_user_id IS NOT NULL AND confirms_decision_id IS NOT NULL)),
  CHECK (initiator <> 'assistant' OR outcome <> 'needs_confirmation'),
  CHECK ((recipient_kind = 'user') = (recipient_user_id IS NOT NULL))
);
CREATE INDEX gate_decisions_contact_idx ON gate_decisions (tenant_id, contact_id, evaluated_at DESC);

-- -----------------------------------------------------------------------------
-- 7. Numbers, email identity, conversations, messages, calls, recordings
-- -----------------------------------------------------------------------------
CREATE TABLE sender_registrations (
  tenant_id             uuid NOT NULL REFERENCES tenants(id),
  id                    uuid NOT NULL,
  kind                  text NOT NULL CHECK (kind IN ('a2p_campaign','toll_free_verification')),
  provider              text NOT NULL,
  provider_brand_ref    text,
  provider_campaign_ref text,
  use_case              text NOT NULL,
  sample_messages       jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(sample_messages) = 'array'),
  opt_in_description    text NOT NULL,
  status                text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','approved','rejected','suspended')),
  status_detail         text,
  status_changed_at     timestamptz NOT NULL DEFAULT now(),
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id)
);

CREATE TABLE phone_numbers (
  tenant_id        uuid NOT NULL REFERENCES tenants(id),
  id               uuid NOT NULL,
  e164             text NOT NULL CHECK (e164 ~ '^\+[1-9][0-9]{6,14}$'),
  provider         text NOT NULL,
  provider_ref     text NOT NULL,
  number_type      text NOT NULL CHECK (number_type IN ('local','toll_free')),
  purpose          text NOT NULL CHECK (purpose IN ('team_main','agent_direct','pond','tracking')),
  assigned_user_id uuid,
  sms_capable      boolean NOT NULL,
  voice_capable    boolean NOT NULL,
  registration_id  uuid,
  inbound_route    text NOT NULL DEFAULT 'contact_owner' CHECK (inbound_route IN ('contact_owner','assigned_user','team_ring','pond')),
  acquired_at      timestamptz NOT NULL,
  released_at      timestamptz,
  quarantine_until timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, assigned_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, registration_id)  REFERENCES sender_registrations (tenant_id, id),
  CHECK (purpose <> 'agent_direct' OR assigned_user_id IS NOT NULL OR released_at IS NOT NULL),
  CHECK (released_at IS NULL OR quarantine_until >= released_at + interval '90 days')
);
-- GLOBAL uniqueness of live numbers: inbound routing must be unambiguous across tenants.
CREATE UNIQUE INDEX phone_numbers_live_e164 ON phone_numbers (e164) WHERE released_at IS NULL;

CREATE TABLE sending_domains (
  tenant_id       uuid NOT NULL REFERENCES tenants(id),
  id              uuid NOT NULL,
  domain          citext NOT NULL CHECK (domain ~ '^[a-z0-9.-]+\.[a-z]{2,}$'),
  spf_status      text NOT NULL DEFAULT 'unknown' CHECK (spf_status IN ('unknown','pass','fail')),
  dkim_status     text NOT NULL DEFAULT 'unknown' CHECK (dkim_status IN ('unknown','pass','fail')),
  dmarc_status    text NOT NULL DEFAULT 'unknown' CHECK (dmarc_status IN ('unknown','pass','fail')),
  dmarc_policy    text CHECK (dmarc_policy IN ('none','quarantine','reject')),
  last_checked_at timestamptz,
  verified_at     timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, domain),
  CHECK (verified_at IS NULL OR (spf_status = 'pass' AND dkim_status = 'pass' AND dmarc_status = 'pass'))
);

CREATE TABLE email_identities (
  tenant_id    uuid NOT NULL REFERENCES tenants(id),
  id           uuid NOT NULL,
  user_id      uuid,                    -- NULL = team identity
  domain_id    uuid,                    -- NULL = platform shared authenticated domain
  from_address citext NOT NULL CHECK (position('@' in from_address) > 1),
  display_name text NOT NULL,
  status       text NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, from_address),
  FOREIGN KEY (tenant_id, user_id)   REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, domain_id) REFERENCES sending_domains (tenant_id, id)
);

CREATE TABLE conversations (           -- one thread per person (unified across channels)
  tenant_id                       uuid NOT NULL,
  id                              uuid NOT NULL,
  contact_id                      uuid NOT NULL,
  sticky_phone_number_id          uuid,
  reply_token_hash                bytea UNIQUE CHECK (reply_token_hash IS NULL OR octet_length(reply_token_hash) = 32),
  last_inbound_at                 timestamptz,
  last_outbound_at                timestamptz,
  inbound_seq                     bigint NOT NULL DEFAULT 0 CHECK (inbound_seq >= 0),
  automation_paused_at            timestamptz,
  automation_pause_reason         text CHECK (automation_pause_reason IN
                                  ('client_reply','opt_out','owner_change','manual','approval_revoked','wrong_number')),
  automation_paused_by_message_id uuid,
  created_at                      timestamptz NOT NULL DEFAULT now(),
  updated_at                      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, contact_id),
  FOREIGN KEY (tenant_id, contact_id)             REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, sticky_phone_number_id) REFERENCES phone_numbers (tenant_id, id),
  CHECK ((automation_paused_at IS NULL) = (automation_pause_reason IS NULL))
);

CREATE TABLE messages (
  tenant_id            uuid NOT NULL,
  id                   uuid NOT NULL,
  conversation_id      uuid NOT NULL,
  contact_id           uuid NOT NULL,
  channel              text NOT NULL CHECK (channel IN ('sms','mms','email')),   -- widen by migration (channel abstraction)
  direction            text NOT NULL CHECK (direction IN ('inbound','outbound')),
  phone_number_id      uuid,
  email_identity_id    uuid,
  from_address         text NOT NULL,
  to_address           text NOT NULL,
  subject              text,
  body                 text NOT NULL CHECK (length(body) <= 20000),
  status               text NOT NULL CHECK (status IN ('received','scheduled','queued','dispatching','sent','delivered',
                       'failed','undelivered','bounced','blocked','canceled','dispatch_unknown')),
  status_reason        text,
  initiator            text NOT NULL CHECK (initiator IN ('human','assistant','system','client','import')),
  initiated_by_user_id uuid,
  purpose              text CHECK (purpose IN ('marketing','informational')),
  action_category      text NOT NULL DEFAULT 'none',
  assistant_action_id  uuid,
  playbook_step_run_id uuid,
  gate_decision_id     uuid,
  pinned_inbound_seq   bigint,
  idempotency_key      text,
  scheduled_for        timestamptz,
  dispatched_at        timestamptz,
  provider             text,
  provider_message_ref text,
  provider_error_code  text,
  is_auto_reply        boolean NOT NULL DEFAULT false,
  opt_out_keyword      text,
  imported             boolean NOT NULL DEFAULT false,
  import_record_id     uuid,
  occurred_at          timestamptz NOT NULL,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  search_tsv           tsvector GENERATED ALWAYS AS (
                         to_tsvector('simple'::regconfig, coalesce(subject, '') || ' ' || coalesce(body, ''))) STORED,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, conversation_id)      REFERENCES conversations (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, contact_id)           REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, phone_number_id)      REFERENCES phone_numbers (tenant_id, id),
  FOREIGN KEY (tenant_id, email_identity_id)    REFERENCES email_identities (tenant_id, id),
  FOREIGN KEY (tenant_id, initiated_by_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, gate_decision_id)     REFERENCES gate_decisions (tenant_id, id),
  FOREIGN KEY (tenant_id, import_record_id)     REFERENCES import_records (tenant_id, id),
  CHECK ((direction = 'inbound') = (initiator IN ('client') OR (initiator = 'import' AND status = 'received'))),
  CHECK (direction = 'outbound' OR status = 'received'),
  CHECK (direction = 'inbound' OR status <> 'received'),
  -- R-GATE-1: nothing leaves without a send-time gate decision
  CHECK (direction = 'inbound' OR imported OR status IN ('scheduled','queued','canceled') OR gate_decision_id IS NOT NULL),
  CHECK (direction = 'inbound' OR imported OR purpose IS NOT NULL),
  CHECK (imported = (initiator = 'import')),
  CHECK (NOT imported OR import_record_id IS NOT NULL),
  CHECK (initiator <> 'assistant' OR assistant_action_id IS NOT NULL),
  CHECK (initiator <> 'human' OR initiated_by_user_id IS NOT NULL),
  CHECK (status <> 'scheduled' OR scheduled_for IS NOT NULL),
  -- F2: TX1 stamps dispatched_at when it commits 'dispatching'; the sweeper finds stuck dispatches by it
  CHECK (direction = 'inbound' OR imported OR status NOT IN ('dispatching','dispatch_unknown','sent','delivered')
         OR dispatched_at IS NOT NULL),
  CHECK (channel <> 'email' OR direction = 'inbound' OR imported OR email_identity_id IS NOT NULL),
  CHECK (channel = 'email' OR direction = 'inbound' OR imported OR phone_number_id IS NOT NULL)
);
CREATE UNIQUE INDEX messages_provider_ref_uq ON messages (tenant_id, provider, provider_message_ref) WHERE provider_message_ref IS NOT NULL;
CREATE UNIQUE INDEX messages_idempotency_uq  ON messages (tenant_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX messages_thread_idx   ON messages (tenant_id, conversation_id, occurred_at DESC, id DESC);
CREATE INDEX messages_contact_idx  ON messages (tenant_id, contact_id, occurred_at DESC);
CREATE INDEX messages_due_idx      ON messages (scheduled_for) WHERE status IN ('scheduled','queued');
CREATE INDEX messages_unknown_idx  ON messages (dispatched_at) WHERE status IN ('dispatching','dispatch_unknown');
CREATE INDEX messages_failed_idx   ON messages (tenant_id, occurred_at DESC)
  WHERE status IN ('failed','undelivered','bounced','blocked','dispatch_unknown','dispatching');
CREATE INDEX messages_caps_idx     ON messages (tenant_id, contact_id, channel, dispatched_at)
  WHERE direction = 'outbound' AND initiator IN ('assistant','system');
CREATE INDEX messages_tsv_idx      ON messages USING gin (search_tsv);

CREATE TABLE message_media (          -- inbound MMS media (encrypted objects)
  tenant_id  uuid NOT NULL,
  message_id uuid NOT NULL,
  object_id  uuid NOT NULL,
  PRIMARY KEY (tenant_id, message_id, object_id),
  FOREIGN KEY (tenant_id, message_id) REFERENCES messages (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, object_id)  REFERENCES stored_objects (tenant_id, id)
);

CREATE TABLE message_status_events (  -- raw provider callbacks; append-only, out-of-order safe
  tenant_id          uuid NOT NULL,
  id                 uuid NOT NULL,
  message_id         uuid NOT NULL,
  provider_status    text NOT NULL,
  mapped_status      text NOT NULL CHECK (mapped_status IN ('sent','delivered','failed','undelivered','bounced','complained','opened','clicked')),
  error_code         text,
  provider_event_ref text NOT NULL,
  occurred_at        timestamptz NOT NULL,
  received_at        timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, provider_event_ref),
  FOREIGN KEY (tenant_id, message_id) REFERENCES messages (tenant_id, id)  -- NO cascade: purge deletes explicitly
);

CREATE TABLE calls (
  tenant_id                 uuid NOT NULL,
  id                        uuid NOT NULL,
  conversation_id           uuid NOT NULL,
  contact_id                uuid NOT NULL,
  direction                 text NOT NULL CHECK (direction IN ('inbound','outbound')),
  phone_number_id           uuid,
  agent_user_id             uuid,
  client_address            text NOT NULL,
  initiator                 text NOT NULL CHECK (initiator IN ('human','client','import')),   -- no AI voice (R-GATE-9)
  handled_by                text NOT NULL DEFAULT 'human' CHECK (handled_by IN ('human','voicemail')),
  status                    text NOT NULL CHECK (status IN ('initiated','ringing','in_progress','completed','no_answer',
                            'busy','failed','canceled','voicemail')),
  started_at                timestamptz NOT NULL,
  answered_at               timestamptz,
  ended_at                  timestamptz,
  duration_s                integer CHECK (duration_s >= 0),
  recording_mode            text NOT NULL CHECK (recording_mode IN ('off','announced_all_parties','one_party_no_announcement')),
  recording_announced_at    timestamptz,
  recording_decision        jsonb NOT NULL CHECK (jsonb_typeof(recording_decision) = 'object'),
  gate_decision_id          uuid,
  parent_call_id            uuid,
  outcome                   text CHECK (outcome IN ('connected','left_voicemail','no_answer','wrong_number','bad_number',
                            'do_not_call_request','callback_requested')),
  outcome_logged_by_user_id uuid,
  outcome_logged_at         timestamptz,
  provider_call_ref         text,
  imported                  boolean NOT NULL DEFAULT false,
  import_record_id          uuid,
  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, conversation_id)           REFERENCES conversations (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, contact_id)                REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, phone_number_id)           REFERENCES phone_numbers (tenant_id, id),
  FOREIGN KEY (tenant_id, agent_user_id)             REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, outcome_logged_by_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, gate_decision_id)          REFERENCES gate_decisions (tenant_id, id),
  FOREIGN KEY (tenant_id, parent_call_id)            REFERENCES calls (tenant_id, id) ON DELETE SET NULL (parent_call_id),
  FOREIGN KEY (tenant_id, import_record_id)          REFERENCES import_records (tenant_id, id),
  CHECK (imported = (initiator = 'import')),
  CHECK (direction = 'inbound' OR imported OR gate_decision_id IS NOT NULL),
  CHECK (direction <> 'outbound' OR imported OR initiator = 'human'),
  CHECK (direction <> 'inbound' OR initiator IN ('client','import')),
  CHECK (recording_mode <> 'announced_all_parties' OR imported OR answered_at IS NULL
         OR status NOT IN ('in_progress','completed') OR recording_announced_at IS NOT NULL),
  CHECK ((outcome IS NULL) = (outcome_logged_at IS NULL))
);
CREATE UNIQUE INDEX calls_provider_ref_uq ON calls (tenant_id, provider_call_ref) WHERE provider_call_ref IS NOT NULL;
CREATE INDEX calls_contact_idx ON calls (tenant_id, contact_id, started_at DESC);
CREATE INDEX calls_agent_idx   ON calls (tenant_id, agent_user_id, started_at DESC);

CREATE TABLE recordings (
  tenant_id                uuid NOT NULL,
  id                       uuid NOT NULL,
  call_id                  uuid NOT NULL,
  contact_id               uuid NOT NULL,          -- denormalized for the restrictive scope policy
  agent_user_id            uuid,                   -- who was on the call
  object_id                uuid,
  duration_s               integer CHECK (duration_s >= 0),
  source                   text NOT NULL CHECK (source IN ('provider','import_fub')),
  consent_basis            text NOT NULL CHECK (consent_basis IN ('announced_all_parties','one_party_policy','unknown_imported')),
  status                   text NOT NULL DEFAULT 'pending_copy' CHECK (status IN ('pending_copy','stored','quarantined','shredded')),
  is_partial               boolean NOT NULL DEFAULT false,
  retain_until             timestamptz NOT NULL,
  legal_hold               boolean NOT NULL DEFAULT false,
  provider_recording_ref   text,
  provider_copy_deleted_at timestamptz,
  created_at               timestamptz NOT NULL DEFAULT now(),
  updated_at               timestamptz NOT NULL DEFAULT now(),
  shredded_at              timestamptz,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, call_id)       REFERENCES calls (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, contact_id)    REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, agent_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, object_id)     REFERENCES stored_objects (tenant_id, id),
  CHECK (status NOT IN ('stored','quarantined') OR object_id IS NOT NULL),
  CHECK ((status = 'shredded') = (shredded_at IS NOT NULL)),
  CHECK ((source = 'import_fub') = (consent_basis = 'unknown_imported'))
);
CREATE UNIQUE INDEX recordings_provider_ref_uq ON recordings (tenant_id, provider_recording_ref) WHERE provider_recording_ref IS NOT NULL;
CREATE INDEX recordings_retention_idx ON recordings (retain_until) WHERE status IN ('stored','quarantined') AND NOT legal_hold;

CREATE TABLE transcripts (
  tenant_id    uuid NOT NULL,
  id           uuid NOT NULL,
  recording_id uuid NOT NULL,
  contact_id   uuid NOT NULL,
  status       text NOT NULL CHECK (status IN ('pending','ready','failed','shredded')),
  language     text,
  segments_enc bytea,                    -- AES-256-GCM JSON [{start_ms,end_ms,speaker,text}]; NOT searchable
  key_version  integer,
  provider     text NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, recording_id),
  FOREIGN KEY (tenant_id, recording_id) REFERENCES recordings (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, contact_id)   REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  CHECK (status <> 'ready' OR (segments_enc IS NOT NULL AND key_version IS NOT NULL)),
  CHECK (status <> 'shredded' OR segments_enc IS NULL)
);

-- -----------------------------------------------------------------------------
-- 8. Assistant (evidence-first) and playbooks (approve rules, not every message)
-- -----------------------------------------------------------------------------
CREATE TABLE ai_runs (
  tenant_id             uuid NOT NULL REFERENCES tenants(id),
  id                    uuid NOT NULL,
  purpose               text NOT NULL CHECK (purpose IN ('draft','call_summary','claims_extraction','handback_enrichment',
                        'lead_summary','first_response','search_proposal','pond_summary','opt_out_review')),
  model                 text NOT NULL,
  prompt_template_key   text NOT NULL,
  prompt_version        text NOT NULL,
  input_refs            jsonb NOT NULL CHECK (jsonb_typeof(input_refs) = 'object'),   -- ids only
  output_enc            bytea,                        -- purged after 30 days
  key_version           integer,
  internal_signals      jsonb NOT NULL DEFAULT '{}',  -- NEVER serialized to agent-facing APIs (A2)
  input_tokens          integer CHECK (input_tokens >= 0),
  output_tokens         integer CHECK (output_tokens >= 0),
  latency_ms            integer CHECK (latency_ms >= 0),
  status                text NOT NULL CHECK (status IN ('succeeded','failed','refused')),
  requested_for_user_id uuid,
  created_at            timestamptz NOT NULL DEFAULT now(),
  output_purged_at      timestamptz,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, requested_for_user_id) REFERENCES memberships (tenant_id, user_id)
);

CREATE TABLE playbooks (
  tenant_id     uuid NOT NULL REFERENCES tenants(id),
  id            uuid NOT NULL,
  kind          text NOT NULL CHECK (kind IN ('new_lead_response','nurture','post_closing','booking_confirmation',
                'reminder','document_chase')),
  scope         text NOT NULL CHECK (scope IN ('team','agent')),
  owner_user_id uuid,
  name          text NOT NULL,
  template_key  text,
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active','retired')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, owner_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK ((scope = 'agent') = (owner_user_id IS NOT NULL)),
  CHECK (kind <> 'new_lead_response' OR scope = 'team')
);

CREATE TABLE playbook_versions (
  tenant_id          uuid NOT NULL,
  id                 uuid NOT NULL,
  playbook_id        uuid NOT NULL,
  version_no         integer NOT NULL CHECK (version_no >= 1),
  steps              jsonb NOT NULL CHECK (jsonb_typeof(steps) = 'array'),   -- core PlaybookStep[] (Zod)
  tone               jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(tone) = 'object'),
  content_sha256     text NOT NULL CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),  -- sha256(canonical(steps, tone))
  status             text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','superseded','revoked')),
  created_by_user_id uuid NOT NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, playbook_id, version_no),
  FOREIGN KEY (tenant_id, playbook_id)        REFERENCES playbooks (tenant_id, id),
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id)
);
CREATE UNIQUE INDEX playbook_one_approved ON playbook_versions (tenant_id, playbook_id) WHERE status = 'approved';

CREATE TABLE playbook_approvals (     -- append-only; revocation is its own row
  tenant_id           uuid NOT NULL,
  id                  uuid NOT NULL,
  playbook_version_id uuid NOT NULL,
  decision            text NOT NULL CHECK (decision IN ('approve','revoke')),
  decided_by_user_id  uuid NOT NULL,
  decided_by_role     text NOT NULL CHECK (decided_by_role IN ('owner','admin','team_lead','agent','isa','tc')),
  content_sha256      text NOT NULL CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
  attestation         text NOT NULL CHECK (length(btrim(attestation)) > 0),
  decided_at          timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, playbook_version_id) REFERENCES playbook_versions (tenant_id, id),
  FOREIGN KEY (tenant_id, decided_by_user_id)  REFERENCES memberships (tenant_id, user_id)
);
CREATE INDEX playbook_approvals_version_idx ON playbook_approvals (tenant_id, playbook_version_id, decided_at DESC, id DESC);

CREATE TABLE playbook_enrollments (
  tenant_id            uuid NOT NULL,
  id                   uuid NOT NULL,
  playbook_id          uuid NOT NULL,
  playbook_version_id  uuid NOT NULL,
  contact_id           uuid NOT NULL,
  enrolled_by          text NOT NULL CHECK (enrolled_by IN ('user','new_lead','deal_closed')),
  enrolled_by_user_id  uuid,
  state                text NOT NULL CHECK (state IN ('active','paused','completed','stopped')),
  pause_reason         text CHECK (pause_reason IN ('client_reply','opt_out','owner_change','manual','approval_revoked',
                       'ineligible','wrong_number')),
  stop_reason          text,
  current_step         integer NOT NULL DEFAULT 0 CHECK (current_step >= 0),
  next_step_due_at     timestamptz,
  paused_at            timestamptz,
  paused_by_message_id uuid,
  resumed_by_user_id   uuid,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  ended_at             timestamptz,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, playbook_id)         REFERENCES playbooks (tenant_id, id),
  FOREIGN KEY (tenant_id, playbook_version_id) REFERENCES playbook_versions (tenant_id, id),
  FOREIGN KEY (tenant_id, contact_id)          REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, enrolled_by_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, resumed_by_user_id)  REFERENCES memberships (tenant_id, user_id),
  CHECK ((state = 'paused') = (pause_reason IS NOT NULL)),
  CHECK ((state = 'paused') = (paused_at IS NOT NULL)),
  CHECK ((state IN ('completed','stopped')) = (ended_at IS NOT NULL)),
  CHECK (enrolled_by <> 'user' OR enrolled_by_user_id IS NOT NULL)
);
-- R-AST-8: at most one live enrollment per contact (no double-dripping)
CREATE UNIQUE INDEX enrollment_one_live ON playbook_enrollments (tenant_id, contact_id) WHERE state IN ('active','paused');
CREATE INDEX enrollment_due_idx ON playbook_enrollments (next_step_due_at) WHERE state = 'active';

CREATE TABLE assistant_actions (
  tenant_id           uuid NOT NULL,
  id                  uuid NOT NULL,
  contact_id          uuid,
  kind                text NOT NULL CHECK (kind IN ('message_draft','autonomous_message','call_summary','handback',
                      'promise_extraction','saved_search_proposal','next_step','lead_summary','seller_update_draft',
                      'weekly_plan')),
  action_category     text NOT NULL CHECK (action_category IN ('speed_to_lead_reply','reminder','booking_confirmation',
                      'document_chase','nurture_step','search_alert','money','contract','novel_message',
                      'seller_update','internal')),
  autonomy            text NOT NULL CHECK (autonomy IN ('requires_approval','within_playbook','internal')),
  playbook_version_id uuid,
  status              text NOT NULL CHECK (status IN ('proposed','approved','rejected','executed','blocked','expired',
                      'superseded','invalidated')),
  owner_user_id       uuid,                       -- who must act on it
  explanation         text NOT NULL CHECK (length(explanation) BETWEEN 1 AND 300),   -- the one-line "why", verbatim
  payload             jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
  edited_payload      jsonb,
  pinned_inbound_seq  bigint,                     -- stale-draft check (R-AST-6)
  bound_ownership_seq bigint,                     -- contacts.ownership_period_seq when drafted; invalidated when it or the owner changes (R-AST-7)
  decided_by_user_id  uuid,
  decided_at          timestamptz,
  ai_run_id           uuid,
  trigger_ref         jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(trigger_ref) = 'object'),
  dedupe_key          text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, contact_id)          REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, playbook_version_id) REFERENCES playbook_versions (tenant_id, id),
  FOREIGN KEY (tenant_id, owner_user_id)       REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, decided_by_user_id)  REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, ai_run_id)           REFERENCES ai_runs (tenant_id, id),
  -- R-AST-3: money / contract / novel messages / seller updates are NEVER autonomous
  CHECK (NOT (autonomy = 'within_playbook' AND action_category IN ('money','contract','novel_message','seller_update','internal'))),
  CHECK (kind <> 'seller_update_draft' OR (action_category = 'seller_update' AND autonomy = 'requires_approval')),
  CHECK ((autonomy = 'within_playbook') = (playbook_version_id IS NOT NULL AND kind = 'autonomous_message')),
  CHECK (status NOT IN ('approved','rejected') OR (decided_by_user_id IS NOT NULL AND decided_at IS NOT NULL)),
  CHECK (autonomy <> 'internal' OR action_category = 'internal')
);
CREATE INDEX assistant_actions_inbox_idx ON assistant_actions (tenant_id, owner_user_id, created_at DESC) WHERE status = 'proposed';
CREATE INDEX assistant_actions_contact_idx ON assistant_actions (tenant_id, contact_id, created_at DESC);
CREATE UNIQUE INDEX assistant_actions_dedupe_uq ON assistant_actions (tenant_id, dedupe_key) WHERE dedupe_key IS NOT NULL;

CREATE TABLE assistant_claims (
  tenant_id           uuid NOT NULL,
  id                  uuid NOT NULL,
  action_id           uuid NOT NULL,
  ordinal             integer NOT NULL CHECK (ordinal >= 0),
  claim_kind          text NOT NULL CHECK (claim_kind IN ('commitment','preference','date_time','fact','qualification',
                      'client_statement','sent_summary','suggestion')),
  text                text NOT NULL CHECK (length(text) BETWEEN 1 AND 300),
  structured          jsonb,
  needs_review        boolean NOT NULL,
  review_status       text NOT NULL DEFAULT 'unreviewed' CHECK (review_status IN ('unreviewed','confirmed','corrected','rejected')),
  reviewed_by_user_id uuid,
  reviewed_at         timestamptz,
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, action_id, ordinal),
  FOREIGN KEY (tenant_id, action_id)           REFERENCES assistant_actions (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, reviewed_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK ((review_status = 'unreviewed') = (reviewed_at IS NULL)),
  CHECK (reviewed_at IS NULL OR reviewed_by_user_id IS NOT NULL)
);

CREATE TABLE evidence_refs (
  tenant_id         uuid NOT NULL,
  id                uuid NOT NULL,
  claim_id          uuid NOT NULL,
  source_type       text NOT NULL CHECK (source_type IN ('call','message','email','note','listing','import',
                    'behavior_event','deal','task','appointment')),
  source_id         uuid NOT NULL,
  locator           jsonb NOT NULL CHECK (jsonb_typeof(locator) = 'object' AND locator ? 'kind'),
  snippet           text CHECK (snippet IS NULL OR length(snippet) <= 500),   -- plaintext sources (sms, note)
  snippet_enc       bytea,                                                   -- transcript-sourced snippets
  verbatim_verified boolean NOT NULL,                                        -- core.verifyQuote() matched
  source_available  boolean NOT NULL DEFAULT true,                           -- false after retention shred
  created_at        timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, claim_id) REFERENCES assistant_claims (tenant_id, id) ON DELETE CASCADE,
  CHECK (snippet IS NULL OR snippet_enc IS NULL),
  CHECK (NOT verbatim_verified OR NOT source_available OR snippet IS NOT NULL OR snippet_enc IS NOT NULL)
);
CREATE INDEX evidence_by_source_idx ON evidence_refs (tenant_id, source_type, source_id);
CREATE INDEX evidence_by_claim_idx  ON evidence_refs (tenant_id, claim_id);

CREATE TABLE playbook_step_runs (
  tenant_id             uuid NOT NULL,
  id                    uuid NOT NULL,
  enrollment_id         uuid NOT NULL,
  playbook_version_id   uuid NOT NULL,
  step_key              text NOT NULL,
  status                text NOT NULL CHECK (status IN ('scheduled','sent','deferred','converted_to_draft',
                        'skipped_ineligible','canceled_paused','failed')),
  scheduled_for         timestamptz NOT NULL,
  deferrals             integer NOT NULL DEFAULT 0 CHECK (deferrals >= 0),
  last_gate_decision_id uuid,
  message_id            uuid,
  assistant_action_id   uuid,
  updated_at            timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, enrollment_id, step_key),
  FOREIGN KEY (tenant_id, enrollment_id)         REFERENCES playbook_enrollments (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, playbook_version_id)   REFERENCES playbook_versions (tenant_id, id),
  FOREIGN KEY (tenant_id, last_gate_decision_id) REFERENCES gate_decisions (tenant_id, id),
  FOREIGN KEY (tenant_id, message_id)            REFERENCES messages (tenant_id, id) ON DELETE SET NULL (message_id),
  FOREIGN KEY (tenant_id, assistant_action_id)   REFERENCES assistant_actions (tenant_id, id) ON DELETE SET NULL (assistant_action_id)
);

-- cyclic FKs, added after both sides exist
ALTER TABLE messages ADD FOREIGN KEY (tenant_id, assistant_action_id) REFERENCES assistant_actions (tenant_id, id);
ALTER TABLE messages ADD FOREIGN KEY (tenant_id, playbook_step_run_id) REFERENCES playbook_step_runs (tenant_id, id)
  ON DELETE SET NULL (playbook_step_run_id);
ALTER TABLE contact_attributes ADD FOREIGN KEY (tenant_id, evidence_claim_id) REFERENCES assistant_claims (tenant_id, id)
  ON DELETE SET NULL (evidence_claim_id);

-- -----------------------------------------------------------------------------
-- 9. Listings, buyer searches, seller-update shaping (data model only where noted)
-- -----------------------------------------------------------------------------
CREATE TABLE listings (
  tenant_id             uuid NOT NULL REFERENCES tenants(id),
  id                    uuid NOT NULL,
  source                text NOT NULL DEFAULT 'team' CHECK (source IN ('team','mls')),   -- 'mls' = competing (Phase 2 feed)
  mls_number            text,
  status                text NOT NULL CHECK (status IN ('coming_soon','active','pending','sold','withdrawn','expired')),
  address_line1         text NOT NULL,
  address_line2         text,
  city                  text NOT NULL,
  region                text NOT NULL,
  postal_code           text NOT NULL,
  list_price_cents      bigint CHECK (list_price_cents >= 0),
  beds                  smallint CHECK (beds >= 0),
  baths_x10             smallint CHECK (baths_x10 >= 0),
  sqft                  integer CHECK (sqft >= 0),
  property_type         text CHECK (property_type IN ('single_family','condo','townhouse','multi_family','land','manufactured','other')),
  listing_agent_user_id uuid,
  description           text,
  list_date             date,
  attributes            jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(attributes) = 'object'),
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  search_tsv            tsvector GENERATED ALWAYS AS (
                          to_tsvector('simple'::regconfig, coalesce(address_line1, '') || ' ' || coalesce(city, '') || ' ' ||
                            coalesce(postal_code, '') || ' ' || coalesce(mls_number, '') || ' ' || coalesce(description, ''))) STORED,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, listing_agent_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (source = 'mls' OR listing_agent_user_id IS NOT NULL)
);
CREATE UNIQUE INDEX listings_mls_uq ON listings (tenant_id, source, mls_number) WHERE mls_number IS NOT NULL;
CREATE INDEX listings_search_idx ON listings USING gin (search_tsv);
CREATE INDEX listings_address_trgm ON listings USING gin (address_line1 gin_trgm_ops);
CREATE INDEX listings_match_idx ON listings (tenant_id, status, postal_code, list_price_cents);

ALTER TABLE lead_inquiries ADD FOREIGN KEY (tenant_id, listing_id) REFERENCES listings (tenant_id, id) ON DELETE SET NULL (listing_id);
ALTER TABLE behavior_events ADD FOREIGN KEY (tenant_id, listing_id) REFERENCES listings (tenant_id, id);

CREATE TABLE listing_contacts (
  tenant_id  uuid NOT NULL,
  listing_id uuid NOT NULL,
  contact_id uuid NOT NULL,
  role       text NOT NULL CHECK (role IN ('seller','co_seller','interested')),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, listing_id, contact_id),
  FOREIGN KEY (tenant_id, listing_id) REFERENCES listings (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, contact_id) REFERENCES contacts (tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE listing_price_history (   -- append-only; written by trigger on listings
  tenant_id   uuid NOT NULL,
  id          uuid NOT NULL DEFAULT gen_random_uuid(),
  listing_id  uuid NOT NULL,
  price_cents bigint NOT NULL CHECK (price_cents >= 0),
  changed_at  timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, listing_id) REFERENCES listings (tenant_id, id)
);
CREATE INDEX listing_price_history_idx ON listing_price_history (tenant_id, listing_id, changed_at DESC);

CREATE TABLE saved_searches (
  tenant_id             uuid NOT NULL,
  id                    uuid NOT NULL,
  contact_id            uuid NOT NULL,
  name                  text NOT NULL,
  status                text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','approved','active','paused','archived')),
  criteria              jsonb NOT NULL CHECK (jsonb_typeof(criteria) = 'object'),            -- core SearchCriteria
  criterion_evidence    jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(criterion_evidence) = 'object'),  -- criterion -> claim id
  proposed_by_action_id uuid,
  approved_by_user_id   uuid,
  approved_at           timestamptz,
  activated_at          timestamptz,
  alert_channel         text NOT NULL DEFAULT 'email' CHECK (alert_channel IN ('email','sms')),
  alert_frequency       text NOT NULL DEFAULT 'daily' CHECK (alert_frequency IN ('instant','daily','weekly')),
  last_alerted_at       timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, contact_id)            REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, proposed_by_action_id) REFERENCES assistant_actions (tenant_id, id) ON DELETE SET NULL (proposed_by_action_id),
  FOREIGN KEY (tenant_id, approved_by_user_id)   REFERENCES memberships (tenant_id, user_id),
  -- R-AST-10: only an agent's approval makes criteria live
  CHECK (status NOT IN ('approved','active','paused') OR (approved_by_user_id IS NOT NULL AND approved_at IS NOT NULL)),
  CHECK (status <> 'active' OR activated_at IS NOT NULL)
);
CREATE INDEX saved_searches_active_idx ON saved_searches (tenant_id, status) WHERE status = 'active';

CREATE TABLE saved_search_matches (
  tenant_id          uuid NOT NULL,
  search_id          uuid NOT NULL,
  listing_id         uuid NOT NULL,
  matched_at         timestamptz NOT NULL,
  alerted_message_id uuid,
  PRIMARY KEY (tenant_id, search_id, listing_id),
  FOREIGN KEY (tenant_id, search_id)          REFERENCES saved_searches (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, listing_id)         REFERENCES listings (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, alerted_message_id) REFERENCES messages (tenant_id, id) ON DELETE SET NULL (alerted_message_id)
);

CREATE TABLE showings (               -- agents may log in Phase 1; seller-update assembly is Phase 2
  tenant_id             uuid NOT NULL,
  id                    uuid NOT NULL,
  listing_id            uuid NOT NULL,
  starts_at             timestamptz NOT NULL,
  ends_at               timestamptz,
  buyer_agent_name      text,
  buyer_agent_brokerage text,
  buyer_contact_id      uuid,
  status                text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','completed','canceled','no_show')),
  source                text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual','showing_service','import')),
  created_by_user_id    uuid,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, listing_id)         REFERENCES listings (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, buyer_contact_id)   REFERENCES contacts (tenant_id, id) ON DELETE SET NULL (buyer_contact_id),
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (ends_at IS NULL OR ends_at > starts_at)
);

CREATE TABLE showing_feedback (
  tenant_id   uuid NOT NULL,
  id          uuid NOT NULL,
  showing_id  uuid NOT NULL,
  rating      smallint CHECK (rating BETWEEN 1 AND 5),
  comments    text,
  source      text NOT NULL CHECK (source IN ('manual','showing_service','email')),
  received_at timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, showing_id) REFERENCES showings (tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE marketing_activity (     -- data model only in Phase 1
  tenant_id          uuid NOT NULL,
  id                 uuid NOT NULL,
  listing_id         uuid NOT NULL,
  kind               text NOT NULL CHECK (kind IN ('social_post','email_blast','open_house','flyer','website','portal','other')),
  channel            text,
  occurred_at        timestamptz NOT NULL,
  metrics            jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(metrics) = 'object'),
  created_by_user_id uuid,
  created_at         timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, listing_id)         REFERENCES listings (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id)
);

CREATE TABLE home_valuations (        -- data model only (AVM provider is Phase 2)
  tenant_id          uuid NOT NULL,
  id                 uuid NOT NULL,
  contact_id         uuid NOT NULL,
  contact_address_id uuid,
  provider           text NOT NULL,
  value_cents        bigint NOT NULL CHECK (value_cents >= 0),
  low_cents          bigint CHECK (low_cents >= 0),
  high_cents         bigint CHECK (high_cents >= 0),
  valued_at          timestamptz NOT NULL,
  provider_ref       text,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, contact_id)         REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, contact_address_id) REFERENCES contact_addresses (tenant_id, id) ON DELETE SET NULL (contact_address_id)
);

-- -----------------------------------------------------------------------------
-- 10. Deals (basic pipeline) with attribution + restricted financials
-- -----------------------------------------------------------------------------
CREATE TABLE deals (
  tenant_id           uuid NOT NULL REFERENCES tenants(id),
  id                  uuid NOT NULL,
  name                text NOT NULL,
  side                text NOT NULL CHECK (side IN ('buy','sell','dual','lease')),
  stage               text NOT NULL DEFAULT 'prospect'
                      CHECK (stage IN ('prospect','agreement_signed','active','under_contract','closed','lost')),
  stage_entered_at    timestamptz NOT NULL,
  primary_contact_id  uuid NOT NULL,
  owner_user_id       uuid NOT NULL,
  listing_id          uuid,
  price_cents         bigint CHECK (price_cents >= 0),
  expected_close_date date,
  agreement_signed_at timestamptz,
  under_contract_at   timestamptz,
  closed_at           timestamptz,
  lost_reason         text,
  -- closed-loop attribution, copied at creation and immutable (A7d)
  lead_source_id      uuid,
  campaign_ref        text,
  ad_ref              text,
  source_inquiry_id   uuid,
  row_version         integer NOT NULL DEFAULT 1,
  created_by_user_id  uuid,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, primary_contact_id) REFERENCES contacts (tenant_id, id),       -- RESTRICT: no purge under a deal
  FOREIGN KEY (tenant_id, owner_user_id)      REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, listing_id)         REFERENCES listings (tenant_id, id),
  FOREIGN KEY (tenant_id, lead_source_id)     REFERENCES lead_sources (tenant_id, id),
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK ((stage = 'closed') = (closed_at IS NOT NULL)),
  CHECK (stage <> 'lost' OR lost_reason IS NOT NULL)
);
CREATE INDEX deals_owner_idx ON deals (tenant_id, owner_user_id, stage);
CREATE INDEX deals_contact_idx ON deals (tenant_id, primary_contact_id);

CREATE TABLE deal_members (           -- users on a deal (TC, co-agent, ISA)
  tenant_id uuid NOT NULL,
  deal_id   uuid NOT NULL,
  user_id   uuid NOT NULL,
  role      text NOT NULL CHECK (role IN ('co_agent','tc','isa')),
  PRIMARY KEY (tenant_id, deal_id, user_id),
  FOREIGN KEY (tenant_id, deal_id) REFERENCES deals (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, user_id) REFERENCES memberships (tenant_id, user_id)
);
CREATE INDEX deal_members_user_idx ON deal_members (tenant_id, user_id);

CREATE TABLE deal_contacts (
  tenant_id  uuid NOT NULL,
  deal_id    uuid NOT NULL,
  contact_id uuid NOT NULL,
  role       text NOT NULL CHECK (role IN ('buyer','seller','co_buyer','co_seller','other')),
  PRIMARY KEY (tenant_id, deal_id, contact_id),
  FOREIGN KEY (tenant_id, deal_id)    REFERENCES deals (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, contact_id) REFERENCES contacts (tenant_id, id)            -- RESTRICT
);
CREATE INDEX deal_contacts_contact_idx ON deal_contacts (tenant_id, contact_id);

CREATE TABLE deal_dates (
  tenant_id    uuid NOT NULL,
  id           uuid NOT NULL,
  deal_id      uuid NOT NULL,
  kind         text NOT NULL CHECK (kind IN ('acceptance','inspection','appraisal','financing','closing','possession','custom')),
  label        text,
  due_on       date NOT NULL,
  completed_at timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, deal_id) REFERENCES deals (tenant_id, id) ON DELETE CASCADE,
  CHECK (kind <> 'custom' OR label IS NOT NULL)
);
CREATE INDEX deal_dates_due_idx ON deal_dates (tenant_id, due_on) WHERE completed_at IS NULL;

CREATE TABLE deal_stage_history (     -- append-only; written by trigger; drives momentum metrics
  tenant_id          uuid NOT NULL,
  id                 uuid NOT NULL DEFAULT gen_random_uuid(),
  deal_id            uuid NOT NULL,
  from_stage         text,
  to_stage           text NOT NULL,
  changed_by_user_id uuid,
  actor_kind         text NOT NULL CHECK (actor_kind IN ('user','system')),
  changed_at         timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, deal_id) REFERENCES deals (tenant_id, id)
);
CREATE INDEX deal_stage_history_idx ON deal_stage_history (tenant_id, deal_id, changed_at);

CREATE TABLE deal_financials (        -- commission capture (A7d); separate table => separate RLS
  tenant_id              uuid NOT NULL,
  deal_id                uuid NOT NULL,
  gross_commission_cents bigint CHECK (gross_commission_cents >= 0),
  commission_rate_bps    integer CHECK (commission_rate_bps BETWEEN 0 AND 10000),
  team_split_bps         integer CHECK (team_split_bps BETWEEN 0 AND 10000),
  agent_split_bps        integer CHECK (agent_split_bps BETWEEN 0 AND 10000),
  referral_fee_cents     bigint CHECK (referral_fee_cents >= 0),
  commission_status      text NOT NULL DEFAULT 'estimated' CHECK (commission_status IN ('estimated','confirmed','paid')),
  updated_by_user_id     uuid NOT NULL,
  updated_at             timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, deal_id),
  FOREIGN KEY (tenant_id, deal_id)            REFERENCES deals (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, updated_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (coalesce(team_split_bps, 0) + coalesce(agent_split_bps, 0) <= 10000)
);

CREATE TABLE agent_goals (            -- data model only (goals are Phase 2)
  tenant_id          uuid NOT NULL,
  id                 uuid NOT NULL,
  user_id            uuid NOT NULL,
  period_kind        text NOT NULL CHECK (period_kind IN ('week','month','quarter','year')),
  period_start       date NOT NULL,
  metric             text NOT NULL CHECK (metric IN ('appointments_set','appointments_held','agreements_signed','closings','touches')),
  target             integer NOT NULL CHECK (target >= 0),
  created_by_user_id uuid NOT NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, user_id, period_kind, period_start, metric),
  FOREIGN KEY (tenant_id, user_id)            REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES memberships (tenant_id, user_id)
);

-- -----------------------------------------------------------------------------
-- 11. Notes, tasks, appointments, feed, accountability
-- -----------------------------------------------------------------------------
CREATE TABLE notes (
  tenant_id        uuid NOT NULL,
  id               uuid NOT NULL,
  contact_id       uuid,
  deal_id          uuid,
  author_user_id   uuid,
  body             text NOT NULL CHECK (length(body) BETWEEN 1 AND 20000),
  pinned           boolean NOT NULL DEFAULT false,
  source           text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual','call_summary','import')),
  imported         boolean NOT NULL DEFAULT false,
  import_record_id uuid,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  search_tsv       tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, body)) STORED,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, contact_id)       REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, deal_id)          REFERENCES deals (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, author_user_id)   REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, import_record_id) REFERENCES import_records (tenant_id, id),
  CHECK (num_nonnulls(contact_id, deal_id) >= 1),
  CHECK (imported = (source = 'import')),
  CHECK (imported OR author_user_id IS NOT NULL)
);
CREATE INDEX notes_contact_idx ON notes (tenant_id, contact_id, created_at DESC);
CREATE INDEX notes_tsv_idx ON notes USING gin (search_tsv);

CREATE TABLE tasks (
  tenant_id            uuid NOT NULL,
  id                   uuid NOT NULL,
  assignee_user_id     uuid NOT NULL,
  contact_id           uuid,
  deal_id              uuid,
  listing_id           uuid,
  kind                 text NOT NULL CHECK (kind IN ('todo','callback','promise','follow_up','document')),
  title                text NOT NULL CHECK (length(title) BETWEEN 1 AND 300),
  notes                text,
  due_at               timestamptz,
  due_all_day          boolean NOT NULL DEFAULT false,
  due_tz               text,
  status               text NOT NULL DEFAULT 'open' CHECK (status IN ('open','done','canceled')),
  completed_at         timestamptz,
  completed_by_user_id uuid,
  created_by_kind      text NOT NULL CHECK (created_by_kind IN ('user','assistant','system','import')),
  created_by_user_id   uuid,
  source_action_id     uuid,
  source_claim_id      uuid,
  needs_review         boolean NOT NULL DEFAULT false,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, assignee_user_id)     REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, contact_id)           REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, deal_id)              REFERENCES deals (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, listing_id)           REFERENCES listings (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, completed_by_user_id) REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, created_by_user_id)   REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, source_action_id)     REFERENCES assistant_actions (tenant_id, id) ON DELETE SET NULL (source_action_id),
  FOREIGN KEY (tenant_id, source_claim_id)      REFERENCES assistant_claims (tenant_id, id) ON DELETE SET NULL (source_claim_id),
  CHECK ((status = 'done') = (completed_at IS NOT NULL)),
  CHECK (created_by_kind <> 'user' OR created_by_user_id IS NOT NULL),
  -- R-AST-5: an unpinned promise date is never asserted; it waits for review
  CHECK (NOT needs_review OR status <> 'open' OR due_at IS NULL OR kind <> 'promise')
);
CREATE INDEX tasks_assignee_idx ON tasks (tenant_id, assignee_user_id, status, due_at);
CREATE INDEX tasks_contact_idx  ON tasks (tenant_id, contact_id) WHERE contact_id IS NOT NULL;
CREATE INDEX tasks_promise_due_idx ON tasks (tenant_id, due_at) WHERE kind = 'promise' AND status = 'open';

CREATE TABLE appointments (
  tenant_id            uuid NOT NULL,
  id                   uuid NOT NULL,
  contact_id           uuid,
  deal_id              uuid,
  user_id              uuid NOT NULL,              -- organizer / responsible agent
  set_by_user_id       uuid,
  kind                 text NOT NULL CHECK (kind IN ('buyer_consult','listing_appointment','consult','other')),
  starts_at            timestamptz NOT NULL,
  ends_at              timestamptz NOT NULL,
  location             text,
  status               text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','held','no_show','canceled','rescheduled')),
  outcome              text CHECK (outcome IN ('agreement_signed','follow_up','not_a_fit','no_decision')),
  outcome_note         text,
  outcome_logged_at    timestamptz,
  outcome_logged_by_user_id uuid,
  created_by_kind      text NOT NULL CHECK (created_by_kind IN ('user','assistant','system','import')),
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, contact_id)                REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, deal_id)                   REFERENCES deals (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, user_id)                   REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, set_by_user_id)            REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, outcome_logged_by_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (ends_at > starts_at),
  CHECK ((outcome_logged_at IS NULL) = (outcome_logged_by_user_id IS NULL)),
  CHECK (outcome IS NULL OR outcome_logged_at IS NOT NULL)
);
CREATE INDEX appointments_user_idx ON appointments (tenant_id, user_id, starts_at);
CREATE INDEX appointments_missing_outcome_idx ON appointments (ends_at) WHERE outcome_logged_at IS NULL AND status IN ('scheduled','held');

CREATE TABLE priority_feed_items (
  tenant_id           uuid NOT NULL,
  id                  uuid NOT NULL,
  user_id             uuid NOT NULL,
  item_type           text NOT NULL CHECK (item_type IN ('lead_offer','first_touch_due','unanswered_inbound','handback',
                      'assistant_draft','task_due','promise_due','deal_date','appointment_outcome','reinquiry',
                      'inactivity_warning','pond_new','saved_search_review','missed_call')),
  band                text NOT NULL CHECK (band IN ('pinned','scored')),
  contact_id          uuid,
  subject_type        text NOT NULL,
  subject_id          uuid NOT NULL,
  assistant_action_id uuid,
  due_at              timestamptz,
  score               smallint NOT NULL DEFAULT 0 CHECK (score BETWEEN 0 AND 100),
  score_version       smallint NOT NULL DEFAULT 1,
  reasons             jsonb NOT NULL CHECK (jsonb_typeof(reasons) = 'array' AND jsonb_array_length(reasons) >= 1),
  state               text NOT NULL DEFAULT 'open' CHECK (state IN ('open','done','snoozed','dismissed')),
  snoozed_until       timestamptz,
  dedupe_key          text NOT NULL,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  resolved_at         timestamptz,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, user_id)             REFERENCES memberships (tenant_id, user_id),
  FOREIGN KEY (tenant_id, contact_id)          REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, assistant_action_id) REFERENCES assistant_actions (tenant_id, id) ON DELETE CASCADE,
  CHECK ((state = 'snoozed') = (snoozed_until IS NOT NULL)),
  CHECK ((state IN ('done','dismissed')) = (resolved_at IS NOT NULL))
);
CREATE UNIQUE INDEX feed_items_open_uq ON priority_feed_items (tenant_id, user_id, dedupe_key) WHERE state IN ('open','snoozed');
CREATE INDEX feed_items_user_idx ON priority_feed_items (tenant_id, user_id, band, due_at) WHERE state = 'open';

CREATE TABLE exception_items (        -- DERIVED cache, recomputable by core.deriveExceptions()
  tenant_id            uuid NOT NULL,
  id                   uuid NOT NULL,
  item_type            text NOT NULL CHECK (item_type IN ('untouched_lead','overdue_promise','failed_send','missing_outcome')),
  subject_type         text NOT NULL CHECK (subject_type IN ('contact','task','message','appointment','call')),
  subject_id           uuid NOT NULL,
  contact_id           uuid,
  owner_user_id        uuid,
  detected_at          timestamptz NOT NULL,
  due_at               timestamptz,
  evidence             jsonb NOT NULL CHECK (jsonb_typeof(evidence) = 'array' AND jsonb_array_length(evidence) >= 1),
  condition_cleared_at timestamptz,
  rule_version         smallint NOT NULL DEFAULT 1,
  dedupe_key           text NOT NULL,
  computed_at          timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, dedupe_key),
  FOREIGN KEY (tenant_id, contact_id)    REFERENCES contacts (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, owner_user_id) REFERENCES memberships (tenant_id, user_id)
);
CREATE INDEX exception_items_open_idx ON exception_items (tenant_id, owner_user_id, detected_at DESC) WHERE condition_cleared_at IS NULL;

CREATE TABLE exception_events (       -- human actions on exceptions; append-only, survives recompute
  tenant_id            uuid NOT NULL,
  id                   uuid NOT NULL,
  exception_dedupe_key text NOT NULL,
  action               text NOT NULL CHECK (action IN ('resolved','reassigned','verified','reopened')),
  note                 text,
  actor_user_id        uuid NOT NULL,
  actor_role           text NOT NULL CHECK (actor_role IN ('owner','admin','team_lead','agent','isa','tc')),
  ownership_command_id uuid,
  occurred_at          timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, actor_user_id) REFERENCES memberships (tenant_id, user_id),
  CHECK (action <> 'resolved' OR length(btrim(coalesce(note, ''))) > 0),
  CHECK (action <> 'reassigned' OR ownership_command_id IS NOT NULL),
  CHECK (action <> 'reassigned' OR actor_role IN ('owner','admin','team_lead')),   -- matrix: agents/ISAs cannot reassign
  CHECK (action <> 'verified' OR actor_role IN ('owner','admin','team_lead'))
);
CREATE INDEX exception_events_key_idx ON exception_events (tenant_id, exception_dedupe_key, occurred_at);

-- -----------------------------------------------------------------------------
-- 12. Notifications
-- -----------------------------------------------------------------------------
CREATE TABLE notifications (
  tenant_id    uuid NOT NULL,
  id           uuid NOT NULL,
  user_id      uuid NOT NULL,
  kind         text NOT NULL CHECK (kind IN ('lead_offer','first_touch_due','first_touch_escalation','handback',
               'handback_hot','inbound_message','missed_call','pond_new','task_due','promise_due','exception',
               'reassigned_to_you','reassigned_away','inactivity_warning','opt_out','import_ready','system')),
  priority     text NOT NULL CHECK (priority IN ('critical','high','normal','low')),
  title        text NOT NULL CHECK (length(title) <= 120),   -- PII-minimized (first name + initial at most)
  body         text CHECK (length(body) <= 240),
  subject_type text,
  subject_id   uuid,
  dedupe_key   text NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  read_at      timestamptz,
  expires_at   timestamptz,
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, user_id, dedupe_key),
  FOREIGN KEY (tenant_id, user_id) REFERENCES memberships (tenant_id, user_id)
);
CREATE INDEX notifications_user_idx ON notifications (tenant_id, user_id, read_at NULLS FIRST, created_at DESC);

CREATE TABLE push_subscriptions (
  tenant_id    uuid NOT NULL,
  id           uuid NOT NULL,
  user_id      uuid NOT NULL,
  kind         text NOT NULL DEFAULT 'web_push' CHECK (kind IN ('web_push')),
  endpoint_enc bytea NOT NULL,
  keys_enc     bytea NOT NULL,
  key_version  integer NOT NULL,
  endpoint_hash bytea NOT NULL CHECK (octet_length(endpoint_hash) = 32),
  created_at   timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz,
  revoked_at   timestamptz,
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, user_id, endpoint_hash),
  FOREIGN KEY (tenant_id, user_id) REFERENCES memberships (tenant_id, user_id)
);

CREATE TABLE notification_deliveries (
  tenant_id        uuid NOT NULL,
  id               uuid NOT NULL,
  notification_id  uuid NOT NULL,
  channel          text NOT NULL CHECK (channel IN ('in_app','web_push','sms','email')),
  target_ref       text NOT NULL,              -- push subscription id / 'alert_phone' / 'account_email' / 'in_app'
  status           text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sending','sent','delivered','failed',
                   'suppressed','dead')),
  attempts         integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  next_attempt_at  timestamptz,
  provider_ref     text,
  last_error       text,
  gate_decision_id uuid,                       -- SMS-to-agent passes canContact(recipient=user)
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, notification_id, channel, target_ref),
  FOREIGN KEY (tenant_id, notification_id)  REFERENCES notifications (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, gate_decision_id) REFERENCES gate_decisions (tenant_id, id),
  CHECK (channel <> 'sms' OR status IN ('pending','suppressed','dead','failed') OR gate_decision_id IS NOT NULL),
  CHECK (status <> 'pending' OR next_attempt_at IS NOT NULL)
);
CREATE INDEX notification_deliveries_due_idx ON notification_deliveries (next_attempt_at) WHERE status = 'pending';

CREATE TABLE notification_preferences (
  tenant_id   uuid NOT NULL,
  user_id     uuid NOT NULL,
  kind        text NOT NULL,
  channels    text[] NOT NULL CHECK (channels <@ ARRAY['in_app','web_push','sms','email']::text[]),
  muted_until timestamptz,
  quiet_start time,
  quiet_end   time,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, user_id, kind),
  FOREIGN KEY (tenant_id, user_id) REFERENCES memberships (tenant_id, user_id),
  -- critical kinds can never be muted and always keep a channel beyond in-app
  CHECK (kind NOT IN ('lead_offer','first_touch_due','handback_hot')
         OR (muted_until IS NULL AND channels && ARRAY['web_push','sms']::text[])),
  CHECK ((quiet_start IS NULL) = (quiet_end IS NULL))
);

-- -----------------------------------------------------------------------------
-- 13. Audit log and job queue
-- -----------------------------------------------------------------------------
CREATE TABLE audit_log (
  tenant_id        uuid NOT NULL REFERENCES tenants(id),
  id               uuid NOT NULL,
  seq              bigint GENERATED ALWAYS AS IDENTITY UNIQUE,   -- gap-detectable order
  occurred_at      timestamptz NOT NULL,
  recorded_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
  actor_kind       text NOT NULL CHECK (actor_kind IN ('user','system','support')),
  actor_via        text CHECK (actor_via IN ('api','assistant','timer','provider','import','worker','retention')),
  actor_user_id    uuid,
  actor_role       text,
  support_grant_id uuid,
  action           text NOT NULL CHECK (action ~ '^[a-z_]+\.[a-z_.]+$'),
  entity_type      text NOT NULL,
  entity_id        uuid,                                         -- no FK: the log outlives the entity
  changes          jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(changes) = 'object'),  -- redacted diff
  reason           text,
  request_id       text,
  ip               inet,
  user_agent       text,
  PRIMARY KEY (tenant_id, id),
  CHECK (actor_kind NOT IN ('user','support') OR actor_user_id IS NOT NULL),
  CHECK (actor_kind <> 'support' OR support_grant_id IS NOT NULL)
);
CREATE INDEX audit_log_entity_idx ON audit_log (tenant_id, entity_type, entity_id, occurred_at DESC);
CREATE INDEX audit_log_actor_idx  ON audit_log (tenant_id, actor_user_id, occurred_at DESC);
CREATE INDEX audit_log_action_idx ON audit_log (tenant_id, action, occurred_at DESC);

CREATE TABLE jobs (
  id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id    uuid REFERENCES tenants(id),            -- NULL only for platform maintenance jobs
  queue        text NOT NULL CHECK (queue IN ('realtime','default','bulk','maintenance')),
  kind         text NOT NULL CHECK (kind ~ '^[a-z_]+\.[a-z_]+$'),
  payload      jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(payload) = 'object'),   -- ids + fences only, never PII
  priority     smallint NOT NULL DEFAULT 100 CHECK (priority BETWEEN 0 AND 1000),      -- lower runs first
  run_at       timestamptz NOT NULL,
  status       text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','running','succeeded','failed','dead','cancelled')),
  attempts     integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  max_attempts integer NOT NULL DEFAULT 10 CHECK (max_attempts BETWEEN 1 AND 50),
  locked_by    text,
  locked_until timestamptz,
  dedupe_key   text,
  last_error   text CHECK (last_error IS NULL OR length(last_error) <= 500),            -- scrubbed code + message
  created_at   timestamptz NOT NULL DEFAULT now(),
  finished_at  timestamptz,
  CHECK ((status = 'running') = (locked_until IS NOT NULL AND locked_by IS NOT NULL)),
  CHECK ((status IN ('succeeded','dead','cancelled')) = (finished_at IS NOT NULL)),
  CHECK (tenant_id IS NOT NULL OR queue = 'maintenance')
);
CREATE INDEX jobs_ready_idx ON jobs (queue, priority, run_at) WHERE status = 'pending';
CREATE INDEX jobs_lease_idx ON jobs (locked_until) WHERE status = 'running';
CREATE UNIQUE INDEX jobs_dedupe_uq ON jobs (tenant_id, dedupe_key) NULLS NOT DISTINCT
  WHERE dedupe_key IS NOT NULL AND status IN ('pending','running');

-- -----------------------------------------------------------------------------
-- 14. Visibility helpers. SECURITY DEFINER helpers are owned by app_definer
--     (BYPASSRLS) so policies can read membership tables without recursion.
--     EVERY definer helper filters tenant_id = app.tenant_id() explicitly.
-- -----------------------------------------------------------------------------
CREATE FUNCTION app.my_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT m.role FROM public.memberships m
   WHERE m.tenant_id = app.tenant_id() AND m.user_id = app.user_id()
     AND m.status = 'active' AND app.actor_kind() = 'user'
     AND app.principal_type() = 'staff'
$$;

CREATE FUNCTION app.is_tenant_wide() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT COALESCE(
    app.principal_type() = 'staff' AND app.tenant_id() IS NOT NULL AND (
         app.actor_kind() = 'system'
      OR app.my_role() IN ('owner','admin')
      OR (app.actor_kind() = 'support' AND EXISTS (
            SELECT 1 FROM public.support_access_grants g
             WHERE g.tenant_id = app.tenant_id() AND g.support_user_id = app.user_id()
               AND g.revoked_at IS NULL AND g.expires_at > now()))),
    false)
$$;

CREATE FUNCTION app.is_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT app.my_role() IS NOT NULL OR app.is_tenant_wide()
$$;

CREATE FUNCTION app.sees_all_detail() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT app.is_tenant_wide() OR COALESCE(app.my_role() = 'team_lead', false)
$$;

CREATE FUNCTION app.my_team_member_ids() RETURNS uuid[] LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT COALESCE(array_agg(DISTINCT tm.user_id), '{}')
    FROM public.team_members lead
    JOIN public.team_members tm ON tm.tenant_id = lead.tenant_id AND tm.team_id = lead.team_id
   WHERE lead.tenant_id = app.tenant_id() AND lead.user_id = app.user_id() AND lead.is_lead
     AND app.my_role() = 'team_lead'
$$;

CREATE FUNCTION app.my_pond_ids() RETURNS uuid[] LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT COALESCE(array_agg(p.id), '{}') FROM public.ponds p
   WHERE p.tenant_id = app.tenant_id() AND p.archived_at IS NULL
     AND app.my_role() = ANY (p.eligible_roles)
     AND (p.open_to_all OR EXISTS (SELECT 1 FROM public.pond_members pm
           WHERE pm.tenant_id = p.tenant_id AND pm.pond_id = p.id AND pm.user_id = app.user_id()))
$$;

CREATE FUNCTION app.my_deal_ids() RETURNS uuid[] LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT COALESCE(array_agg(dm.deal_id), '{}') FROM public.deal_members dm
   WHERE dm.tenant_id = app.tenant_id() AND dm.user_id = app.user_id() AND app.my_role() IS NOT NULL
$$;

CREATE FUNCTION app.my_deal_contact_ids() RETURNS uuid[] LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT COALESCE(array_agg(DISTINCT x.contact_id), '{}') FROM (
    SELECT dc.contact_id FROM public.deal_contacts dc
      JOIN public.deal_members dm ON dm.tenant_id = dc.tenant_id AND dm.deal_id = dc.deal_id
     WHERE dc.tenant_id = app.tenant_id() AND dm.user_id = app.user_id()
    UNION ALL
    SELECT d.primary_contact_id FROM public.deals d
      JOIN public.deal_members dm ON dm.tenant_id = d.tenant_id AND dm.deal_id = d.id
     WHERE d.tenant_id = app.tenant_id() AND dm.user_id = app.user_id()) x
   WHERE app.my_role() IS NOT NULL
$$;

CREATE FUNCTION app.my_collab_contact_ids() RETURNS uuid[] LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT COALESCE(array_agg(k.contact_id), '{}') FROM public.contact_collaborators k
   WHERE k.tenant_id = app.tenant_id() AND k.user_id = app.user_id()
     AND k.removed_at IS NULL AND (k.expires_at IS NULL OR k.expires_at > now())
     AND app.my_role() IS NOT NULL
$$;

CREATE FUNCTION app.recording_scope() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT CASE
    WHEN app.is_tenant_wide() THEN 'all'
    WHEN app.my_role() = 'team_lead' AND s.team_lead_recording_access THEN 'team'
    WHEN app.my_role() = 'tc' AND s.tc_recording_access THEN 'deal'
    ELSE 'own' END
  FROM public.tenant_settings s WHERE s.tenant_id = app.tenant_id()
$$;

CREATE FUNCTION app.contact_exists(p_tenant uuid, p_contact uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
  SELECT EXISTS (SELECT 1 FROM public.contacts c
                  WHERE c.tenant_id = p_tenant AND c.id = p_contact AND p_tenant = app.tenant_id())
$$;

-- Invoker helpers (RLS of the caller applies inside them).
CREATE FUNCTION app.contact_visible(p_tenant uuid, p_contact uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS (SELECT 1 FROM public.contacts c WHERE c.tenant_id = p_tenant AND c.id = p_contact)
$$;

-- "Detail" = phones, emails, timeline, recordings, history. Hidden when the caller sees the
-- contact ONLY as a pond card or an offer card (R-PERM-6).
CREATE FUNCTION app.contact_detail_visible(p_tenant uuid, p_contact uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.contacts c
     WHERE c.tenant_id = p_tenant AND c.id = p_contact
       AND (app.sees_all_detail()
            OR c.ownership_state NOT IN ('in_pond','offered')
            OR c.id = ANY (app.my_collab_contact_ids())
            OR c.id = ANY (app.my_deal_contact_ids())))
$$;

CREATE FUNCTION app.deal_visible(p_tenant uuid, p_deal uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS (SELECT 1 FROM public.deals d WHERE d.tenant_id = p_tenant AND d.id = p_deal)
$$;

CREATE FUNCTION app.deal_writable(p_tenant uuid, p_deal uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS (SELECT 1 FROM public.deals d WHERE d.tenant_id = p_tenant AND d.id = p_deal
                    AND (app.is_tenant_wide() OR d.owner_user_id = app.user_id()
                         OR d.owner_user_id = ANY (app.my_team_member_ids())))
$$;

CREATE FUNCTION app.listing_writable(p_tenant uuid, p_listing uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS (SELECT 1 FROM public.listings l WHERE l.tenant_id = p_tenant AND l.id = p_listing
                    AND (app.is_tenant_wide() OR l.listing_agent_user_id = app.user_id()
                         OR COALESCE(app.my_role() = 'team_lead', false)))
$$;

-- -----------------------------------------------------------------------------
-- 15. Guard triggers (database-enforced business rules)
-- -----------------------------------------------------------------------------

-- R-OWN-2/3: the ownership projection changes only through a ledgered ownership command.
CREATE FUNCTION app.contacts_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE
  cmd uuid := app.ownership_command();
  changed boolean;
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN
    RETURN NEW;                       -- foreign tenant: RLS WITH CHECK rejects the row
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.original_lead_source_id IS NOT NULL AND NEW.original_lead_source_id IS DISTINCT FROM OLD.original_lead_source_id
       OR OLD.original_campaign_ref IS NOT NULL AND NEW.original_campaign_ref IS DISTINCT FROM OLD.original_campaign_ref
       OR OLD.original_ad_ref IS NOT NULL AND NEW.original_ad_ref IS DISTINCT FROM OLD.original_ad_ref
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'ATTRIBUTION_IMMUTABLE: first-touch attribution and creator cannot change'
        USING ERRCODE = 'check_violation';
    END IF;
    changed := (NEW.ownership_state, NEW.owner_user_id, NEW.pond_id, NEW.offer_id, NEW.offered_to_user_id,
                NEW.offer_expires_at, NEW.offer_round, NEW.routing_rule_id, NEW.owned_at, NEW.first_touch_due_at,
                NEW.first_touch_at, NEW.first_touch_breached_at, NEW.release_due_at, NEW.closed_reason,
                NEW.ownership_period_seq, NEW.route_due_at,
                NEW.ownership_command_id, NEW.ownership_actor_user_id, NEW.deleted_at)
           IS DISTINCT FROM
               (OLD.ownership_state, OLD.owner_user_id, OLD.pond_id, OLD.offer_id, OLD.offered_to_user_id,
                OLD.offer_expires_at, OLD.offer_round, OLD.routing_rule_id, OLD.owned_at, OLD.first_touch_due_at,
                OLD.first_touch_at, OLD.first_touch_breached_at, OLD.release_due_at, OLD.closed_reason,
                OLD.ownership_period_seq, OLD.route_due_at,
                OLD.ownership_command_id, OLD.ownership_actor_user_id, OLD.deleted_at);
    IF NOT changed THEN
      IF NEW.ownership_seq <> OLD.ownership_seq THEN
        RAISE EXCEPTION 'OWNERSHIP_SEQ: seq changed without an ownership change' USING ERRCODE = 'check_violation';
      END IF;
      RETURN NEW;
    END IF;
  END IF;
  IF cmd IS NULL OR NEW.ownership_command_id IS DISTINCT FROM cmd THEN
    RAISE EXCEPTION 'OWNERSHIP_UNAUDITED: ownership may only change inside an ownership command'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.ownership_seq <= OLD.ownership_seq THEN
    RAISE EXCEPTION 'OWNERSHIP_SEQ: ownership change must advance seq' USING ERRCODE = 'serialization_failure';
  END IF;
  IF NOT EXISTS (
       SELECT 1 FROM public.lead_ownership_events e
        WHERE e.tenant_id = NEW.tenant_id AND e.contact_id = NEW.id AND e.seq = NEW.ownership_seq
          AND e.command_id = cmd
          AND e.to_state = NEW.ownership_state
          AND e.owner_user_id IS NOT DISTINCT FROM NEW.owner_user_id
          AND e.pond_id IS NOT DISTINCT FROM NEW.pond_id
          AND e.offered_to_user_id IS NOT DISTINCT FROM NEW.offered_to_user_id
          AND (e.actor_kind = 'user') = (NEW.ownership_actor_user_id IS NOT NULL)
          AND e.actor_user_id IS NOT DISTINCT FROM NEW.ownership_actor_user_id) THEN
    RAISE EXCEPTION 'OWNERSHIP_UNAUDITED: contact % seq % has no matching ledger event', NEW.id, NEW.ownership_seq
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  -- F3: the projection always points at the ledger HEAD, so prev+1 computed from it is always the next seq.
  IF EXISTS (SELECT 1 FROM public.lead_ownership_events e
              WHERE e.tenant_id = NEW.tenant_id AND e.contact_id = NEW.id AND e.seq > NEW.ownership_seq) THEN
    RAISE EXCEPTION 'OWNERSHIP_SEQ_HEAD: projection seq % is behind the ledger head', NEW.ownership_seq
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER contacts_guard BEFORE INSERT OR UPDATE ON contacts
  FOR EACH ROW EXECUTE FUNCTION app.contacts_guard();

-- Ledger: gapless seq, written only inside the ownership command named by app.ownership_command.
CREATE FUNCTION app.lead_ownership_events_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE expected bigint;
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN
    RETURN NEW;
  END IF;
  IF app.ownership_command() IS NULL OR NEW.command_id <> app.ownership_command() THEN
    RAISE EXCEPTION 'OWNERSHIP_UNAUDITED: ledger rows are written only by the ownership command path'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT COALESCE(max(e.seq), 0) + 1 INTO expected FROM public.lead_ownership_events e
   WHERE e.tenant_id = NEW.tenant_id AND e.contact_id = NEW.contact_id;
  IF NEW.seq <> expected THEN
    RAISE EXCEPTION 'OWNERSHIP_SEQ_GAP: expected seq %, got %', expected, NEW.seq USING ERRCODE = 'serialization_failure';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER lead_ownership_events_guard BEFORE INSERT ON lead_ownership_events
  FOR EACH ROW EXECUTE FUNCTION app.lead_ownership_events_guard();

-- R-PERM-2: role and status changes need Owner/Admin; Owner roles need an Owner;
-- a tenant always keeps one active Owner.
CREATE FUNCTION app.memberships_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF current_user IN ('app_definer','app_retention') THEN
    NULL;   -- reviewed definer paths (provisioning, invite acceptance)
  ELSIF (NEW.role, NEW.status) IS DISTINCT FROM (OLD.role, OLD.status) THEN
    IF NOT app.is_tenant_wide() THEN
      RAISE EXCEPTION 'ROLE_CHANGE_FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF (OLD.role = 'owner' OR NEW.role = 'owner') AND app.actor_kind() <> 'system'
       AND COALESCE(app.my_role(), '') <> 'owner' THEN
      RAISE EXCEPTION 'OWNER_ROLE_REQUIRES_OWNER' USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  IF OLD.role = 'owner' AND OLD.status = 'active' AND (NEW.role <> 'owner' OR NEW.status <> 'active')
     AND NOT EXISTS (SELECT 1 FROM public.memberships m
                      WHERE m.tenant_id = OLD.tenant_id AND m.user_id <> OLD.user_id
                        AND m.role = 'owner' AND m.status = 'active') THEN
    RAISE EXCEPTION 'LAST_OWNER: tenant must keep an active owner' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER memberships_guard BEFORE UPDATE ON memberships
  FOR EACH ROW EXECUTE FUNCTION app.memberships_guard();

-- R-PERM-3: Owner-only settings: brokerage identity, recording retention/access, MFA roles,
-- and activating a loosened compliance policy. Timezone must be a valid IANA zone.
CREATE FUNCTION app.tenant_settings_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM now() AT TIME ZONE NEW.default_timezone;     -- raises on an unknown zone
  IF TG_OP = 'UPDATE' AND current_user NOT IN ('app_definer','app_retention') THEN
    IF ((NEW.brokerage_legal_name, NEW.team_name, NEW.brokerage_license_number, NEW.brokerage_postal_address,
         NEW.operating_jurisdictions, NEW.recording_retention_days, NEW.team_lead_recording_access,
         NEW.tc_recording_access, NEW.mfa_required_roles)
        IS DISTINCT FROM
        (OLD.brokerage_legal_name, OLD.team_name, OLD.brokerage_license_number, OLD.brokerage_postal_address,
         OLD.operating_jurisdictions, OLD.recording_retention_days, OLD.team_lead_recording_access,
         OLD.tc_recording_access, OLD.mfa_required_roles)
        OR (NEW.active_policy_id IS DISTINCT FROM OLD.active_policy_id AND EXISTS (
              SELECT 1 FROM public.compliance_policy_versions p
               WHERE p.tenant_id = NEW.tenant_id AND p.id = NEW.active_policy_id
                 AND p.loosening_attestation IS NOT NULL)))
       AND COALESCE(app.my_role(), '') <> 'owner' THEN
      RAISE EXCEPTION 'OWNER_ONLY_SETTING' USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER tenant_settings_guard BEFORE INSERT OR UPDATE ON tenant_settings
  FOR EACH ROW EXECUTE FUNCTION app.tenant_settings_guard();

CREATE FUNCTION app.compliance_policy_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.loosening_attestation IS NOT NULL AND current_user NOT IN ('app_definer','app_retention')
     AND COALESCE(app.my_role(), '') <> 'owner' THEN
    RAISE EXCEPTION 'OWNER_ONLY_LOOSENING' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER compliance_policy_guard BEFORE INSERT ON compliance_policy_versions
  FOR EACH ROW EXECUTE FUNCTION app.compliance_policy_guard();

-- R-CONSENT-9: suppressions are never deleted; lifted once, by Owner/Admin, with a reason.
CREATE FUNCTION app.suppressions_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF current_user = 'app_retention' THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'SUPPRESSION_DELETE_FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF OLD.lifted_at IS NOT NULL OR NEW.lifted_at IS NULL
     OR (NEW.tenant_id, NEW.address_kind, NEW.address_hmac, NEW.channel, NEW.reason, NEW.created_at, NEW.imported)
        IS DISTINCT FROM (OLD.tenant_id, OLD.address_kind, OLD.address_hmac, OLD.channel, OLD.reason, OLD.created_at, OLD.imported) THEN
    RAISE EXCEPTION 'SUPPRESSION_IMMUTABLE: may only be lifted once' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF app.actor_kind() <> 'user' OR COALESCE(app.my_role(), '') NOT IN ('owner','admin')
     OR NEW.lifted_by_user_id IS DISTINCT FROM app.user_id() THEN
    RAISE EXCEPTION 'SUPPRESSION_LIFT_FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER suppressions_guard BEFORE UPDATE OR DELETE ON suppressions
  FOR EACH ROW EXECUTE FUNCTION app.suppressions_guard();

-- R-CONSENT-6: the projection is written in the same tx as its ledger events and must be
-- current with respect to the ledger (event count for the key, including purpose='all').
CREATE FUNCTION app.consent_state_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE n integer;
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN RETURN NEW; END IF;
  SELECT count(*) INTO n FROM public.consent_events e
   WHERE e.tenant_id = NEW.tenant_id AND e.channel = NEW.channel AND e.address_hmac = NEW.address_hmac
     AND e.purpose IN (NEW.purpose, 'all');
  IF n <> NEW.ledger_event_count THEN
    RAISE EXCEPTION 'CONSENT_PROJECTION_STALE: ledger has % events, projection claims %', n, NEW.ledger_event_count
      USING ERRCODE = 'serialization_failure';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER consent_state_guard BEFORE INSERT OR UPDATE ON consent_state
  FOR EACH ROW EXECUTE FUNCTION app.consent_state_guard();

-- R-GATE-1..4: an outbound message reaches dispatch only with a FRESH send-time 'allow'
-- decision; assistant messages additionally need an approval or an approved playbook and an
-- un-paused conversation (A3 in-flight re-check, enforced in the same tx as dispatch).
CREATE FUNCTION app.messages_dispatch_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE g record; a record; paused timestamptz;
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN RETURN NEW; END IF;
  IF NEW.direction <> 'outbound' OR NEW.imported
     OR NEW.status NOT IN ('dispatching','sent','delivered','failed','undelivered','bounced','dispatch_unknown')
     OR (TG_OP = 'UPDATE' AND OLD.status NOT IN ('scheduled','queued')) THEN
    RETURN NEW;
  END IF;
  SELECT gd.outcome, gd.phase, gd.evaluated_at, gd.channel INTO g FROM public.gate_decisions gd
   WHERE gd.tenant_id = NEW.tenant_id AND gd.id = NEW.gate_decision_id;
  IF NOT FOUND OR g.outcome <> 'allow' OR g.phase NOT IN ('send','confirm') THEN
    RAISE EXCEPTION 'GATE_NOT_ALLOWED: dispatch requires a send-time allow decision' USING ERRCODE = 'check_violation';
  END IF;
  IF g.evaluated_at < now() - interval '10 minutes' THEN
    RAISE EXCEPTION 'GATE_DECISION_STALE: canContact must be re-run at send time' USING ERRCODE = 'check_violation';
  END IF;
  IF g.channel <> (CASE WHEN NEW.channel = 'mms' THEN 'sms' ELSE NEW.channel END) THEN
    RAISE EXCEPTION 'GATE_CHANNEL_MISMATCH' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.initiator = 'assistant' THEN
    SELECT aa.autonomy, aa.status, aa.decided_by_user_id, aa.playbook_version_id INTO a
      FROM public.assistant_actions aa WHERE aa.tenant_id = NEW.tenant_id AND aa.id = NEW.assistant_action_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'ASSISTANT_ACTION_MISSING' USING ERRCODE = 'check_violation';
    ELSIF a.autonomy = 'within_playbook' THEN
      IF NOT EXISTS (SELECT 1 FROM public.playbook_versions v
                      WHERE v.tenant_id = NEW.tenant_id AND v.id = a.playbook_version_id AND v.status = 'approved') THEN
        RAISE EXCEPTION 'PLAYBOOK_NOT_APPROVED' USING ERRCODE = 'check_violation';
      END IF;
      SELECT c.automation_paused_at INTO paused FROM public.conversations c
       WHERE c.tenant_id = NEW.tenant_id AND c.id = NEW.conversation_id;
      IF paused IS NOT NULL THEN
        RAISE EXCEPTION 'AUTOMATION_PAUSED: the client replied; hand back instead' USING ERRCODE = 'check_violation';
      END IF;
    ELSIF a.autonomy = 'requires_approval' THEN
      IF a.status NOT IN ('approved','executed') OR a.decided_by_user_id IS NULL THEN
        RAISE EXCEPTION 'ASSISTANT_ACTION_NOT_APPROVED' USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      RAISE EXCEPTION 'ASSISTANT_ACTION_NOT_SENDABLE' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER messages_dispatch_guard BEFORE INSERT OR UPDATE OF status ON messages
  FOR EACH ROW EXECUTE FUNCTION app.messages_dispatch_guard();

CREATE FUNCTION app.calls_dispatch_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE g record;
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN RETURN NEW; END IF;
  IF NEW.direction <> 'outbound' OR NEW.imported THEN RETURN NEW; END IF;
  SELECT gd.outcome, gd.phase, gd.evaluated_at, gd.channel INTO g FROM public.gate_decisions gd
   WHERE gd.tenant_id = NEW.tenant_id AND gd.id = NEW.gate_decision_id;
  IF NOT FOUND OR g.outcome <> 'allow' OR g.phase NOT IN ('send','confirm') OR g.channel <> 'voice' THEN
    RAISE EXCEPTION 'GATE_NOT_ALLOWED: dial requires a dial-time allow decision' USING ERRCODE = 'check_violation';
  END IF;
  IF g.evaluated_at < now() - interval '10 minutes' THEN
    RAISE EXCEPTION 'GATE_DECISION_STALE' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER calls_dispatch_guard BEFORE INSERT ON calls
  FOR EACH ROW EXECUTE FUNCTION app.calls_dispatch_guard();

-- R-AST-1: a claim not flagged needs_review must have >= 1 verbatim-verified evidence ref
-- (checked at COMMIT so the claim and its refs can be inserted in any order).
CREATE FUNCTION app.claim_evidence_check() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE c record;
BEGIN
  SELECT cl.id, cl.needs_review INTO c FROM public.assistant_claims cl
   WHERE cl.tenant_id = NEW.tenant_id AND cl.id = NEW.id;
  IF FOUND AND NOT c.needs_review AND NOT EXISTS (
       SELECT 1 FROM public.evidence_refs e
        WHERE e.tenant_id = NEW.tenant_id AND e.claim_id = c.id AND e.verbatim_verified) THEN
    RAISE EXCEPTION 'CLAIM_WITHOUT_EVIDENCE: claim % asserted without verified evidence (set needs_review)', c.id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER claim_evidence_required AFTER INSERT OR UPDATE ON assistant_claims
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.claim_evidence_check();

-- R-AST-4: playbook versions are born as drafts, frozen once they leave draft, and become
-- 'approved' only right after a matching approval row (or 'revoked' after a revoke row).
CREATE FUNCTION app.playbook_versions_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE last record;
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'PLAYBOOK_VERSION_MUST_START_AS_DRAFT' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status <> 'draft' AND (NEW.steps, NEW.tone, NEW.content_sha256, NEW.playbook_id, NEW.version_no)
       IS DISTINCT FROM (OLD.steps, OLD.tone, OLD.content_sha256, OLD.playbook_id, OLD.version_no) THEN
    RAISE EXCEPTION 'PLAYBOOK_VERSION_FROZEN: create a new version' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status IN ('superseded','revoked') AND NEW.status <> OLD.status THEN
    RAISE EXCEPTION 'PLAYBOOK_VERSION_TERMINAL' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('approved','revoked') AND NEW.status <> OLD.status THEN
    SELECT pa.decision, pa.content_sha256 INTO last FROM public.playbook_approvals pa
     WHERE pa.tenant_id = NEW.tenant_id AND pa.playbook_version_id = NEW.id
     ORDER BY pa.decided_at DESC, pa.id DESC LIMIT 1;
    IF NOT FOUND OR last.content_sha256 <> NEW.content_sha256
       OR last.decision <> (CASE NEW.status WHEN 'approved' THEN 'approve' ELSE 'revoke' END) THEN
      RAISE EXCEPTION 'PLAYBOOK_APPROVAL_REQUIRED: status % needs a matching approval row', NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER playbook_versions_guard BEFORE INSERT OR UPDATE ON playbook_versions
  FOR EACH ROW EXECUTE FUNCTION app.playbook_versions_guard();

CREATE FUNCTION app.playbook_approvals_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE v record;
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN RETURN NEW; END IF;
  SELECT pv.content_sha256, p.scope, p.owner_user_id INTO v
    FROM public.playbook_versions pv JOIN public.playbooks p ON p.tenant_id = pv.tenant_id AND p.id = pv.playbook_id
   WHERE pv.tenant_id = NEW.tenant_id AND pv.id = NEW.playbook_version_id;
  IF NOT FOUND OR v.content_sha256 <> NEW.content_sha256 THEN
    RAISE EXCEPTION 'PLAYBOOK_APPROVAL_HASH_MISMATCH' USING ERRCODE = 'check_violation';
  END IF;
  IF app.actor_kind() <> 'user' OR NEW.decided_by_user_id IS DISTINCT FROM app.user_id()
     OR NEW.decided_by_role IS DISTINCT FROM app.my_role() THEN
    RAISE EXCEPTION 'PLAYBOOK_APPROVAL_ACTOR' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- R-AST-4: agent playbooks are approved by their agent; team playbooks by Owner/Admin
  IF NEW.decision = 'approve' AND NOT (
       (v.scope = 'agent' AND v.owner_user_id = NEW.decided_by_user_id)
    OR (v.scope = 'team' AND NEW.decided_by_role IN ('owner','admin'))) THEN
    RAISE EXCEPTION 'PLAYBOOK_APPROVER_NOT_ALLOWED' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW.decision = 'revoke' AND NOT (
       (v.scope = 'agent' AND v.owner_user_id = NEW.decided_by_user_id)
    OR NEW.decided_by_role IN ('owner','admin')) THEN
    RAISE EXCEPTION 'PLAYBOOK_REVOKER_NOT_ALLOWED' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER playbook_approvals_guard BEFORE INSERT ON playbook_approvals
  FOR EACH ROW EXECUTE FUNCTION app.playbook_approvals_guard();

-- Only approved versions run: enrollment (and migration to a new version) requires approval.
CREATE FUNCTION app.playbook_enrollments_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN RETURN NEW; END IF;
  IF (TG_OP = 'INSERT' OR NEW.playbook_version_id IS DISTINCT FROM OLD.playbook_version_id
      OR (NEW.state = 'active' AND OLD.state <> 'active'))
     AND NOT EXISTS (SELECT 1 FROM public.playbook_versions v
                      WHERE v.tenant_id = NEW.tenant_id AND v.id = NEW.playbook_version_id
                        AND v.playbook_id = NEW.playbook_id AND v.status = 'approved') THEN
    RAISE EXCEPTION 'PLAYBOOK_NOT_APPROVED: enrollments run only on an approved version' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.state = 'active' AND OLD.state = 'paused'
     AND (app.actor_kind() <> 'user' OR NEW.resumed_by_user_id IS DISTINCT FROM app.user_id()) THEN
    RAISE EXCEPTION 'RESUME_REQUIRES_HUMAN' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER playbook_enrollments_guard BEFORE INSERT OR UPDATE ON playbook_enrollments
  FOR EACH ROW EXECUTE FUNCTION app.playbook_enrollments_guard();

-- Saved-search criteria changes after approval require re-approval in the same update.
CREATE FUNCTION app.saved_searches_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.criteria IS DISTINCT FROM OLD.criteria AND OLD.status IN ('approved','active','paused')
     AND NOT (NEW.status = 'proposed' OR NEW.approved_at > OLD.approved_at) THEN
    RAISE EXCEPTION 'SAVED_SEARCH_REAPPROVAL_REQUIRED' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('approved','active') AND NEW.approved_by_user_id IS DISTINCT FROM OLD.approved_by_user_id
     AND (app.actor_kind() <> 'user' OR NEW.approved_by_user_id IS DISTINCT FROM app.user_id()) THEN
    RAISE EXCEPTION 'SAVED_SEARCH_APPROVAL_REQUIRES_HUMAN' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER saved_searches_guard BEFORE UPDATE ON saved_searches
  FOR EACH ROW EXECUTE FUNCTION app.saved_searches_guard();

-- Deals: attribution immutable; every stage change appends deal_stage_history.
CREATE FUNCTION app.deals_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.lead_source_id, NEW.campaign_ref, NEW.ad_ref, NEW.source_inquiry_id, NEW.created_at)
       IS DISTINCT FROM (OLD.lead_source_id, OLD.campaign_ref, OLD.ad_ref, OLD.source_inquiry_id, OLD.created_at) THEN
      RAISE EXCEPTION 'ATTRIBUTION_IMMUTABLE' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.stage IS DISTINCT FROM OLD.stage THEN
      NEW.stage_entered_at := now();
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER deals_guard BEFORE INSERT OR UPDATE ON deals
  FOR EACH ROW EXECUTE FUNCTION app.deals_guard();

CREATE FUNCTION app.deals_stage_history() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.stage IS DISTINCT FROM OLD.stage THEN
    INSERT INTO public.deal_stage_history (tenant_id, deal_id, from_stage, to_stage, changed_by_user_id, actor_kind, changed_at)
    VALUES (NEW.tenant_id, NEW.id, CASE WHEN TG_OP = 'UPDATE' THEN OLD.stage END, NEW.stage,
            CASE WHEN app.actor_kind() = 'user' THEN app.user_id() END,
            CASE WHEN app.actor_kind() = 'user' THEN 'user' ELSE 'system' END, now());
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER deals_stage_history AFTER INSERT OR UPDATE OF stage ON deals
  FOR EACH ROW EXECUTE FUNCTION app.deals_stage_history();

CREATE FUNCTION app.listings_price_history() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.list_price_cents IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.list_price_cents IS DISTINCT FROM OLD.list_price_cents) THEN
    INSERT INTO public.listing_price_history (tenant_id, listing_id, price_cents, changed_at)
    VALUES (NEW.tenant_id, NEW.id, NEW.list_price_cents, now());
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER listings_price_history AFTER INSERT OR UPDATE OF list_price_cents ON listings
  FOR EACH ROW EXECUTE FUNCTION app.listings_price_history();

-- R-IMPORT-3: stages commit in dependency order; each earlier stage verified or skipped first.
CREATE FUNCTION app.import_stages_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN RETURN NEW; END IF;
  IF NEW.status IN ('committing','committed') AND NEW.status IS DISTINCT FROM OLD.status
     AND EXISTS (SELECT 1 FROM public.import_stages s
                  WHERE s.tenant_id = NEW.tenant_id AND s.batch_id = NEW.batch_id AND s.seq < NEW.seq
                    AND s.status NOT IN ('verified','skipped')) THEN
    RAISE EXCEPTION 'IMPORT_STAGE_ORDER: earlier stages must be verified or skipped first' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER import_stages_guard BEFORE UPDATE ON import_stages
  FOR EACH ROW EXECUTE FUNCTION app.import_stages_guard();

-- R-TEN-8: a number released by one tenant is quarantined from other tenants for 90 days.
CREATE FUNCTION app.phone_numbers_quarantine() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.phone_numbers n
              WHERE n.e164 = NEW.e164 AND n.tenant_id <> NEW.tenant_id
                AND n.released_at IS NOT NULL AND n.quarantine_until > now()) THEN
    RAISE EXCEPTION 'NUMBER_QUARANTINED' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER phone_numbers_quarantine BEFORE INSERT ON phone_numbers
  FOR EACH ROW EXECUTE FUNCTION app.phone_numbers_quarantine();

-- R-ACC-3 (F7): a 'reassigned' exception event must cite a real ownership command by the same actor that
-- moved THIS item's contact after the item was detected. Rejected commands never reach the ledger, so they
-- cannot be cited.
CREATE FUNCTION app.exception_events_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE item record;
BEGIN
  IF app.tenant_id() IS NOT NULL AND NEW.tenant_id <> app.tenant_id() THEN RETURN NEW; END IF;
  IF NEW.action <> 'reassigned' THEN RETURN NEW; END IF;
  SELECT e.contact_id, e.detected_at INTO item FROM public.exception_items e
   WHERE e.tenant_id = NEW.tenant_id AND e.dedupe_key = NEW.exception_dedupe_key;
  IF NOT FOUND OR item.contact_id IS NULL OR NOT EXISTS (
       SELECT 1 FROM public.lead_ownership_events l
        WHERE l.tenant_id = NEW.tenant_id AND l.contact_id = item.contact_id
          AND l.command_id = NEW.ownership_command_id AND l.type IN ('reassigned','assigned')
          AND l.actor_kind = 'user' AND l.actor_user_id = NEW.actor_user_id
          AND l.occurred_at >= item.detected_at) THEN
    RAISE EXCEPTION 'EXCEPTION_REASSIGN_UNPROVEN: no matching reassignment of this contact by this actor'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER exception_events_guard BEFORE INSERT ON exception_events
  FOR EACH ROW EXECUTE FUNCTION app.exception_events_guard();

-- Append-only tables.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['auth_events','lead_ownership_events','consent_disclosures','consent_events','dnc_checks',
     'gate_decisions','message_status_events','behavior_events','playbook_approvals','listing_price_history',
     'deal_stage_history','exception_events','audit_log','compliance_policy_versions','ownership_command_rejections'] LOOP
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION app.reject_mutation()',
                   t || '_append_only', t);
    EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION app.reject_mutation()',
                   t || '_no_truncate', t);
  END LOOP;
END $$;

-- updated_at maintenance on every table that has the column.
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.table_name FROM information_schema.columns c
            JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name
           WHERE c.table_schema = 'public' AND c.column_name = 'updated_at' AND t.table_type = 'BASE TABLE' LOOP
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at()',
                   r.table_name || '_touch_updated_at', r.table_name);
  END LOOP;
END $$;

-- -----------------------------------------------------------------------------
-- 16. Row-level security
-- -----------------------------------------------------------------------------
-- Layer 1: every table with a tenant_id column (except the two global platform logs) gets
-- ENABLE + FORCE RLS, one RESTRICTIVE tenant_isolation policy (staff principals only), and
-- RESTRICTIVE read-only policies for support actors.
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.relname FROM pg_class c
             JOIN pg_namespace n ON n.oid = c.relnamespace
             JOIN pg_attribute a ON a.attrelid = c.oid AND a.attname = 'tenant_id' AND NOT a.attisdropped
            WHERE n.nspname = 'public' AND c.relkind = 'r'
              AND c.relname NOT IN ('auth_events','webhook_events') LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.relname);
    EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', r.relname);
    EXECUTE format('CREATE POLICY tenant_isolation ON public.%I AS RESTRICTIVE FOR ALL '
                   'USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.principal_type()) = ''staff'') '
                   'WITH CHECK (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.principal_type()) = ''staff'')', r.relname);
    EXECUTE format('CREATE POLICY support_read_only_ins ON public.%I AS RESTRICTIVE FOR INSERT '
                   'WITH CHECK ((SELECT app.actor_kind()) <> ''support'')', r.relname);
    EXECUTE format('CREATE POLICY support_read_only_upd ON public.%I AS RESTRICTIVE FOR UPDATE '
                   'USING ((SELECT app.actor_kind()) <> ''support'')', r.relname);
    EXECUTE format('CREATE POLICY support_read_only_del ON public.%I AS RESTRICTIVE FOR DELETE '
                   'USING ((SELECT app.actor_kind()) <> ''support'')', r.relname);
  END LOOP;
END $$;

-- Global tables: RLS on everywhere.
ALTER TABLE tenants            ENABLE ROW LEVEL SECURITY; ALTER TABLE tenants            FORCE ROW LEVEL SECURITY;
ALTER TABLE users              ENABLE ROW LEVEL SECURITY; ALTER TABLE users              FORCE ROW LEVEL SECURITY;
ALTER TABLE sessions           ENABLE ROW LEVEL SECURITY; ALTER TABLE sessions           FORCE ROW LEVEL SECURITY;
ALTER TABLE auth_tokens        ENABLE ROW LEVEL SECURITY; ALTER TABLE auth_tokens        FORCE ROW LEVEL SECURITY;
ALTER TABLE auth_events        ENABLE ROW LEVEL SECURITY; ALTER TABLE auth_events        FORCE ROW LEVEL SECURITY;
ALTER TABLE auth_attempts      ENABLE ROW LEVEL SECURITY; ALTER TABLE auth_attempts      FORCE ROW LEVEL SECURITY;
ALTER TABLE mfa_recovery_codes ENABLE ROW LEVEL SECURITY; ALTER TABLE mfa_recovery_codes FORCE ROW LEVEL SECURITY;
ALTER TABLE jurisdiction_packs ENABLE ROW LEVEL SECURITY; ALTER TABLE jurisdiction_packs FORCE ROW LEVEL SECURITY;
ALTER TABLE webhook_events     ENABLE ROW LEVEL SECURITY; ALTER TABLE webhook_events     FORCE ROW LEVEL SECURITY;

CREATE POLICY tenant_self ON tenants FOR SELECT
  USING (id = (SELECT app.tenant_id()) AND (SELECT app.principal_type()) = 'staff');
CREATE POLICY users_select ON users FOR SELECT USING (
  id = (SELECT app.user_id())
  OR EXISTS (SELECT 1 FROM memberships m WHERE m.user_id = users.id));   -- memberships RLS => co-members only
CREATE POLICY users_insert_self ON users FOR INSERT WITH CHECK (id = (SELECT app.user_id()));
CREATE POLICY users_update_self ON users FOR UPDATE USING (id = (SELECT app.user_id())) WITH CHECK (id = (SELECT app.user_id()));
CREATE POLICY sessions_own ON sessions FOR ALL
  USING (user_id = (SELECT app.user_id())) WITH CHECK (user_id = (SELECT app.user_id()));
CREATE POLICY mfa_codes_own ON mfa_recovery_codes FOR ALL
  USING (user_id = (SELECT app.user_id())) WITH CHECK (user_id = (SELECT app.user_id()));
CREATE POLICY auth_events_insert ON auth_events FOR INSERT WITH CHECK (true);
CREATE POLICY packs_read ON jurisdiction_packs FOR SELECT USING (true);
-- auth_tokens, auth_attempts, webhook_events: no policy => definer functions only.

-- Layer 2 (a): reference/config tables: every member reads, Owner/Admin/system write.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['tenant_settings','teams','team_members','ponds','pond_members','routing_rules',
     'routing_rule_members','routing_rotation_state','lead_sources','phone_numbers','sender_registrations',
     'sending_domains','email_identities','consent_disclosures','dnc_checks','compliance_policy_versions'] LOOP
    EXECUTE format('CREATE POLICY member_read ON public.%I FOR SELECT USING ((SELECT app.is_member()))', t);
    EXECUTE format('CREATE POLICY admin_insert ON public.%I FOR INSERT WITH CHECK ((SELECT app.is_tenant_wide()))', t);
    EXECUTE format('CREATE POLICY admin_update ON public.%I FOR UPDATE USING ((SELECT app.is_tenant_wide())) '
                   'WITH CHECK ((SELECT app.is_tenant_wide()))', t);
    EXECUTE format('CREATE POLICY admin_delete ON public.%I FOR DELETE USING ((SELECT app.is_tenant_wide()))', t);
  END LOOP;
END $$;

-- Layer 2 (b): Owner/Admin/system only.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['invites','tenant_keys','provider_credentials','import_batches','import_stages',
     'import_records','import_user_mappings','external_refs'] LOOP
    EXECUTE format('CREATE POLICY admin_all ON public.%I FOR ALL USING ((SELECT app.is_tenant_wide())) '
                   'WITH CHECK ((SELECT app.is_tenant_wide()))', t);
  END LOOP;
END $$;

-- Layer 2 (c): contact children: visible/writable iff the parent contact's DETAIL is visible.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['contact_points','contact_addresses','contact_attributes','lead_inquiries',
     'conversations','behavior_events','saved_searches','playbook_enrollments','home_valuations','listing_contacts'] LOOP
    EXECUTE format('CREATE POLICY contact_detail ON public.%I FOR ALL '
                   'USING (app.contact_detail_visible(tenant_id, contact_id)) '
                   'WITH CHECK (app.contact_detail_visible(tenant_id, contact_id))', t);
  END LOOP;
END $$;

CREATE POLICY members_read ON memberships FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY memberships_insert ON memberships FOR INSERT WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY memberships_update ON memberships FOR UPDATE USING (
  (SELECT app.is_tenant_wide()) OR user_id = (SELECT app.user_id())
  OR user_id = ANY ((SELECT app.my_team_member_ids())::uuid[]))
  WITH CHECK ((SELECT app.is_member()));                  -- role/status changes: memberships_guard

CREATE POLICY grants_read ON support_access_grants FOR SELECT USING ((SELECT app.my_role()) IN ('owner','admin'));
CREATE POLICY grants_write ON support_access_grants FOR ALL
  USING ((SELECT app.my_role()) = 'owner') WITH CHECK ((SELECT app.my_role()) = 'owner');

CREATE POLICY objects_select ON stored_objects FOR SELECT USING (
  (SELECT app.is_tenant_wide()) OR created_by_user_id = (SELECT app.user_id())
  OR EXISTS (SELECT 1 FROM recordings r WHERE r.tenant_id = stored_objects.tenant_id AND r.object_id = stored_objects.id)
  OR EXISTS (SELECT 1 FROM message_media mm WHERE mm.tenant_id = stored_objects.tenant_id AND mm.object_id = stored_objects.id));
CREATE POLICY objects_insert ON stored_objects FOR INSERT WITH CHECK (
  (SELECT app.is_tenant_wide()) OR (created_by_user_id = (SELECT app.user_id()) AND (SELECT app.is_member())));
CREATE POLICY objects_update ON stored_objects FOR UPDATE USING ((SELECT app.is_tenant_wide())) WITH CHECK ((SELECT app.is_tenant_wide()));

-- contacts: the central visibility rule (R-PERM-4..7)
CREATE POLICY contacts_select ON contacts FOR SELECT USING (
  (SELECT app.is_tenant_wide())
  -- the actor of the current ownership command keeps sight of the row it just moved away
  OR (ownership_actor_user_id = (SELECT app.user_id()) AND ownership_command_id = (SELECT app.ownership_command()))
  OR (deleted_at IS NULL AND (SELECT app.my_role()) IS NOT NULL AND (
         owner_user_id = (SELECT app.user_id())
      OR offered_to_user_id = (SELECT app.user_id())
      OR id = ANY ((SELECT app.my_collab_contact_ids())::uuid[])
      OR (ownership_state = 'in_pond' AND pond_id = ANY ((SELECT app.my_pond_ids())::uuid[]))
      OR owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[])
      OR offered_to_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[])
      OR (ownership_state = 'in_pond' AND (SELECT app.my_role()) = 'team_lead')
      OR id = ANY ((SELECT app.my_deal_contact_ids())::uuid[]))));
CREATE POLICY contacts_insert ON contacts FOR INSERT WITH CHECK (
  (SELECT app.is_tenant_wide())
  OR ((SELECT app.my_role()) IN ('team_lead','agent','isa')
      AND ownership_state = 'owned' AND owner_user_id = (SELECT app.user_id())));
CREATE POLICY contacts_update ON contacts FOR UPDATE USING (
  (SELECT app.is_tenant_wide())
  OR (deleted_at IS NULL AND (SELECT app.my_role()) IN ('team_lead','agent','isa') AND (
         owner_user_id = (SELECT app.user_id())
      OR offered_to_user_id = (SELECT app.user_id())
      OR id = ANY ((SELECT app.my_collab_contact_ids())::uuid[])
      OR (ownership_state = 'in_pond' AND pond_id = ANY ((SELECT app.my_pond_ids())::uuid[]))
      OR owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[])
      OR offered_to_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[])
      OR (ownership_state = 'in_pond' AND (SELECT app.my_role()) = 'team_lead'))))
  WITH CHECK ((SELECT app.is_member()));
-- no DELETE policy: contacts are soft-deleted; hard delete only via app.erase_contact / retention.

CREATE POLICY loe_select ON lead_ownership_events FOR SELECT USING (
  (SELECT app.sees_all_detail()) OR app.contact_detail_visible(tenant_id, contact_id));
CREATE POLICY loe_insert ON lead_ownership_events FOR INSERT WITH CHECK (
  ((actor_kind = 'user' AND actor_user_id = (SELECT app.user_id()) AND (SELECT app.my_role()) IS NOT NULL)
   OR (actor_kind <> 'user' AND (SELECT app.actor_kind()) = 'system'))
  AND (NOT app.contact_exists(tenant_id, contact_id) OR app.contact_visible(tenant_id, contact_id)));
-- Rejections: written as self (user) or system, only inside the ownership command named by the GUC.
-- No contact-visibility requirement: the loser of a claim race can no longer see the contact.
CREATE POLICY ocr_select ON ownership_command_rejections FOR SELECT USING (
  (SELECT app.sees_all_detail()) OR actor_user_id = (SELECT app.user_id()));
CREATE POLICY ocr_insert ON ownership_command_rejections FOR INSERT WITH CHECK (
  command_id = (SELECT app.ownership_command())
  AND ((actor_kind = 'user' AND actor_user_id = (SELECT app.user_id()) AND (SELECT app.my_role()) IS NOT NULL
        AND (SELECT app.actor_kind()) = 'user')
       OR (actor_kind <> 'user' AND (SELECT app.actor_kind()) = 'system')));

CREATE POLICY collaborators_read ON contact_collaborators FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY collaborators_write ON contact_collaborators FOR ALL USING (
  (SELECT app.is_tenant_wide()) OR (SELECT app.my_role()) = 'team_lead'
  OR EXISTS (SELECT 1 FROM contacts c WHERE c.tenant_id = contact_collaborators.tenant_id
               AND c.id = contact_collaborators.contact_id AND c.owner_user_id = (SELECT app.user_id())))
  WITH CHECK (
  (SELECT app.is_tenant_wide()) OR (SELECT app.my_role()) = 'team_lead'
  OR EXISTS (SELECT 1 FROM contacts c WHERE c.tenant_id = contact_collaborators.tenant_id
               AND c.id = contact_collaborators.contact_id AND c.owner_user_id = (SELECT app.user_id())));

CREATE POLICY dup_candidates ON contact_duplicate_candidates FOR ALL
  USING ((SELECT app.sees_all_detail())
         OR (app.contact_detail_visible(tenant_id, contact_a_id) AND app.contact_detail_visible(tenant_id, contact_b_id)))
  WITH CHECK ((SELECT app.is_member()));

-- consent + compliance (no plaintext addresses anywhere in these tables)
CREATE POLICY consent_events_select ON consent_events FOR SELECT USING (
  (SELECT app.is_tenant_wide())
  OR EXISTS (SELECT 1 FROM contact_points p WHERE p.tenant_id = consent_events.tenant_id
               AND p.address_hmac = consent_events.address_hmac));
CREATE POLICY consent_events_insert ON consent_events FOR INSERT WITH CHECK (
  (actor_kind = 'user' AND actor_user_id = (SELECT app.user_id()) AND (SELECT app.my_role()) IS NOT NULL)
  OR (actor_kind = 'system' AND (SELECT app.actor_kind()) = 'system'));
CREATE POLICY consent_state_read ON consent_state FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY consent_state_insert ON consent_state FOR INSERT WITH CHECK ((SELECT app.is_member()));
CREATE POLICY consent_state_update ON consent_state FOR UPDATE USING ((SELECT app.is_member())) WITH CHECK ((SELECT app.is_member()));
CREATE POLICY suppressions_read ON suppressions FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY suppressions_insert ON suppressions FOR INSERT WITH CHECK ((SELECT app.is_member()));
CREATE POLICY suppressions_lift ON suppressions FOR UPDATE
  USING ((SELECT app.my_role()) IN ('owner','admin')) WITH CHECK ((SELECT app.my_role()) IN ('owner','admin'));
CREATE POLICY gate_decisions_select ON gate_decisions FOR SELECT USING (
  (SELECT app.is_tenant_wide()) OR actor_user_id = (SELECT app.user_id())
  OR (contact_id IS NOT NULL AND app.contact_detail_visible(tenant_id, contact_id)));
CREATE POLICY gate_decisions_insert ON gate_decisions FOR INSERT WITH CHECK (
  (SELECT app.is_tenant_wide()) OR (actor_user_id = (SELECT app.user_id()) AND (SELECT app.is_member())));

-- messages / calls / recordings / transcripts
CREATE POLICY messages_select ON messages FOR SELECT USING (app.contact_detail_visible(tenant_id, contact_id));
CREATE POLICY messages_insert ON messages FOR INSERT WITH CHECK (
  app.contact_detail_visible(tenant_id, contact_id)
  AND ((SELECT app.is_tenant_wide()) OR (initiator = 'human' AND initiated_by_user_id = (SELECT app.user_id()))));
CREATE POLICY messages_update ON messages FOR UPDATE
  USING (app.contact_detail_visible(tenant_id, contact_id)
         AND ((SELECT app.is_tenant_wide()) OR initiated_by_user_id = (SELECT app.user_id())))
  WITH CHECK (app.contact_detail_visible(tenant_id, contact_id));
CREATE POLICY media_select ON message_media FOR SELECT USING (EXISTS (
  SELECT 1 FROM messages m WHERE m.tenant_id = message_media.tenant_id AND m.id = message_media.message_id));
CREATE POLICY media_write ON message_media FOR INSERT WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY mse_select ON message_status_events FOR SELECT USING (EXISTS (
  SELECT 1 FROM messages m WHERE m.tenant_id = message_status_events.tenant_id AND m.id = message_status_events.message_id));
CREATE POLICY mse_insert ON message_status_events FOR INSERT WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY calls_select ON calls FOR SELECT USING (app.contact_detail_visible(tenant_id, contact_id));
CREATE POLICY calls_insert ON calls FOR INSERT WITH CHECK (
  app.contact_detail_visible(tenant_id, contact_id)
  AND ((SELECT app.is_tenant_wide()) OR (initiator = 'human' AND agent_user_id = (SELECT app.user_id()))));
CREATE POLICY calls_update ON calls FOR UPDATE
  USING (app.contact_detail_visible(tenant_id, contact_id)
         AND ((SELECT app.is_tenant_wide()) OR agent_user_id = (SELECT app.user_id())))
  WITH CHECK (app.contact_detail_visible(tenant_id, contact_id));
CREATE POLICY recordings_select ON recordings FOR SELECT USING (app.contact_detail_visible(tenant_id, contact_id));
CREATE POLICY recordings_write ON recordings FOR ALL
  USING ((SELECT app.actor_kind()) = 'system' AND (SELECT app.is_tenant_wide()))
  WITH CHECK ((SELECT app.actor_kind()) = 'system' AND (SELECT app.is_tenant_wide()));
CREATE POLICY transcripts_select ON transcripts FOR SELECT USING (app.contact_detail_visible(tenant_id, contact_id));
CREATE POLICY transcripts_write ON transcripts FOR ALL
  USING ((SELECT app.actor_kind()) = 'system' AND (SELECT app.is_tenant_wide()))
  WITH CHECK ((SELECT app.actor_kind()) = 'system' AND (SELECT app.is_tenant_wide()));
-- R-PERM-8: recording scope is a RESTRICTIVE second gate on recordings and transcripts.
CREATE POLICY recording_scope ON recordings AS RESTRICTIVE FOR SELECT USING (
  CASE (SELECT app.recording_scope())
    WHEN 'all'  THEN true
    WHEN 'team' THEN agent_user_id = (SELECT app.user_id()) OR EXISTS (
                       SELECT 1 FROM contacts c WHERE c.tenant_id = recordings.tenant_id AND c.id = recordings.contact_id
                          AND (c.owner_user_id = (SELECT app.user_id())
                               OR c.owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[])))
    WHEN 'deal' THEN agent_user_id = (SELECT app.user_id())
                     OR contact_id = ANY ((SELECT app.my_deal_contact_ids())::uuid[])
    ELSE agent_user_id = (SELECT app.user_id()) OR EXISTS (
           SELECT 1 FROM contacts c WHERE c.tenant_id = recordings.tenant_id AND c.id = recordings.contact_id
              AND c.owner_user_id = (SELECT app.user_id()))
  END);
CREATE POLICY transcript_scope ON transcripts AS RESTRICTIVE FOR SELECT USING (EXISTS (
  SELECT 1 FROM recordings r WHERE r.tenant_id = transcripts.tenant_id AND r.id = transcripts.recording_id));

-- notes, tasks, appointments
CREATE POLICY notes_select ON notes FOR SELECT USING (
  (contact_id IS NOT NULL AND app.contact_detail_visible(tenant_id, contact_id))
  OR (contact_id IS NULL AND deal_id IS NOT NULL AND app.deal_visible(tenant_id, deal_id)));
CREATE POLICY notes_insert ON notes FOR INSERT WITH CHECK (
  ((SELECT app.is_tenant_wide()) OR author_user_id = (SELECT app.user_id()))
  AND ((contact_id IS NOT NULL AND app.contact_detail_visible(tenant_id, contact_id))
       OR (contact_id IS NULL AND app.deal_visible(tenant_id, deal_id))));
CREATE POLICY notes_update ON notes FOR UPDATE
  USING ((SELECT app.is_tenant_wide()) OR author_user_id = (SELECT app.user_id()))
  WITH CHECK ((SELECT app.is_tenant_wide()) OR author_user_id = (SELECT app.user_id()));
CREATE POLICY tasks_all ON tasks FOR ALL USING (
  (SELECT app.is_tenant_wide()) OR assignee_user_id = (SELECT app.user_id())
  OR (contact_id IS NOT NULL AND app.contact_detail_visible(tenant_id, contact_id))
  OR (deal_id IS NOT NULL AND app.deal_visible(tenant_id, deal_id)))
  WITH CHECK (
  (SELECT app.is_tenant_wide()) OR assignee_user_id = (SELECT app.user_id())
  OR (contact_id IS NOT NULL AND app.contact_detail_visible(tenant_id, contact_id))
  OR (deal_id IS NOT NULL AND app.deal_visible(tenant_id, deal_id)));
CREATE POLICY appointments_all ON appointments FOR ALL USING (
  (SELECT app.is_tenant_wide()) OR user_id = (SELECT app.user_id())
  OR (contact_id IS NOT NULL AND app.contact_detail_visible(tenant_id, contact_id))
  OR (deal_id IS NOT NULL AND app.deal_visible(tenant_id, deal_id)))
  WITH CHECK (
  (SELECT app.is_tenant_wide()) OR user_id = (SELECT app.user_id())
  OR (contact_id IS NOT NULL AND app.contact_detail_visible(tenant_id, contact_id))
  OR (deal_id IS NOT NULL AND app.deal_visible(tenant_id, deal_id)));

-- assistant + playbooks
CREATE POLICY ai_runs_select ON ai_runs FOR SELECT USING (
  (SELECT app.is_tenant_wide()) OR requested_for_user_id = (SELECT app.user_id()));
CREATE POLICY ai_runs_write ON ai_runs FOR INSERT WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY ai_runs_update ON ai_runs FOR UPDATE USING ((SELECT app.is_tenant_wide())) WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY actions_select ON assistant_actions FOR SELECT USING (
  (SELECT app.is_tenant_wide())
  OR (contact_id IS NULL AND owner_user_id = (SELECT app.user_id()))
  OR (contact_id IS NOT NULL AND app.contact_detail_visible(tenant_id, contact_id)
      AND (owner_user_id = (SELECT app.user_id()) OR (SELECT app.my_role()) = 'team_lead')));
CREATE POLICY actions_insert ON assistant_actions FOR INSERT WITH CHECK (
  (SELECT app.is_tenant_wide())
  OR (owner_user_id = (SELECT app.user_id()) AND (contact_id IS NULL OR app.contact_detail_visible(tenant_id, contact_id))));
CREATE POLICY actions_update ON assistant_actions FOR UPDATE USING (
  (SELECT app.is_tenant_wide())
  OR (owner_user_id = (SELECT app.user_id()) AND (contact_id IS NULL OR app.contact_detail_visible(tenant_id, contact_id))))
  WITH CHECK ((SELECT app.is_member()));
CREATE POLICY claims_all ON assistant_claims FOR ALL USING (EXISTS (
  SELECT 1 FROM assistant_actions a WHERE a.tenant_id = assistant_claims.tenant_id AND a.id = assistant_claims.action_id))
  WITH CHECK (EXISTS (
  SELECT 1 FROM assistant_actions a WHERE a.tenant_id = assistant_claims.tenant_id AND a.id = assistant_claims.action_id));
CREATE POLICY evidence_all ON evidence_refs FOR ALL USING (EXISTS (
  SELECT 1 FROM assistant_claims c WHERE c.tenant_id = evidence_refs.tenant_id AND c.id = evidence_refs.claim_id))
  WITH CHECK (EXISTS (
  SELECT 1 FROM assistant_claims c WHERE c.tenant_id = evidence_refs.tenant_id AND c.id = evidence_refs.claim_id));
CREATE POLICY playbooks_select ON playbooks FOR SELECT USING (
  (SELECT app.is_member()) AND (scope = 'team' OR owner_user_id = (SELECT app.user_id()) OR (SELECT app.sees_all_detail())));
CREATE POLICY playbooks_write ON playbooks FOR INSERT WITH CHECK (
  (SELECT app.is_tenant_wide()) OR (scope = 'agent' AND owner_user_id = (SELECT app.user_id()) AND (SELECT app.is_member())));
CREATE POLICY playbooks_update ON playbooks FOR UPDATE USING (
  (SELECT app.is_tenant_wide()) OR (scope = 'agent' AND owner_user_id = (SELECT app.user_id())))
  WITH CHECK ((SELECT app.is_tenant_wide()) OR (scope = 'agent' AND owner_user_id = (SELECT app.user_id())));
CREATE POLICY pv_select ON playbook_versions FOR SELECT USING (EXISTS (
  SELECT 1 FROM playbooks p WHERE p.tenant_id = playbook_versions.tenant_id AND p.id = playbook_versions.playbook_id));
CREATE POLICY pv_insert ON playbook_versions FOR INSERT WITH CHECK (EXISTS (
  SELECT 1 FROM playbooks p WHERE p.tenant_id = playbook_versions.tenant_id AND p.id = playbook_versions.playbook_id
     AND ((SELECT app.is_tenant_wide()) OR (p.scope = 'agent' AND p.owner_user_id = (SELECT app.user_id())))));
CREATE POLICY pv_update ON playbook_versions FOR UPDATE USING (EXISTS (
  SELECT 1 FROM playbooks p WHERE p.tenant_id = playbook_versions.tenant_id AND p.id = playbook_versions.playbook_id
     AND ((SELECT app.is_tenant_wide()) OR (p.scope = 'agent' AND p.owner_user_id = (SELECT app.user_id())))))
  WITH CHECK (true);
CREATE POLICY pa_select ON playbook_approvals FOR SELECT USING (EXISTS (
  SELECT 1 FROM playbook_versions v WHERE v.tenant_id = playbook_approvals.tenant_id AND v.id = playbook_approvals.playbook_version_id));
CREATE POLICY pa_insert ON playbook_approvals FOR INSERT WITH CHECK (
  decided_by_user_id = (SELECT app.user_id()) AND (SELECT app.my_role()) IS NOT NULL);   -- approver rules: playbook_approvals_guard
CREATE POLICY step_runs_all ON playbook_step_runs FOR ALL USING (EXISTS (
  SELECT 1 FROM playbook_enrollments e WHERE e.tenant_id = playbook_step_runs.tenant_id AND e.id = playbook_step_runs.enrollment_id))
  WITH CHECK ((SELECT app.is_tenant_wide()));

-- listings, searches, showings (inventory is readable by every member)
CREATE POLICY listings_read ON listings FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY listings_insert ON listings FOR INSERT WITH CHECK (
  ((SELECT app.is_tenant_wide()) OR listing_agent_user_id = (SELECT app.user_id()) OR (SELECT app.my_role()) = 'team_lead')
  AND (source = 'team' OR (SELECT app.actor_kind()) = 'system'));
CREATE POLICY listings_update ON listings FOR UPDATE
  USING ((SELECT app.is_tenant_wide()) OR listing_agent_user_id = (SELECT app.user_id()) OR (SELECT app.my_role()) = 'team_lead')
  WITH CHECK (source = 'team' OR (SELECT app.actor_kind()) = 'system');
CREATE POLICY lph_read ON listing_price_history FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY lph_insert ON listing_price_history FOR INSERT WITH CHECK (app.listing_writable(tenant_id, listing_id));
CREATE POLICY ssm_all ON saved_search_matches FOR ALL USING (EXISTS (
  SELECT 1 FROM saved_searches s WHERE s.tenant_id = saved_search_matches.tenant_id AND s.id = saved_search_matches.search_id))
  WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY showings_read ON showings FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY showings_write ON showings FOR INSERT WITH CHECK (app.listing_writable(tenant_id, listing_id));
CREATE POLICY showings_update ON showings FOR UPDATE USING (app.listing_writable(tenant_id, listing_id))
  WITH CHECK (app.listing_writable(tenant_id, listing_id));
CREATE POLICY feedback_read ON showing_feedback FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY feedback_write ON showing_feedback FOR INSERT WITH CHECK (EXISTS (
  SELECT 1 FROM showings s WHERE s.tenant_id = showing_feedback.tenant_id AND s.id = showing_feedback.showing_id
     AND app.listing_writable(s.tenant_id, s.listing_id)));
CREATE POLICY marketing_read ON marketing_activity FOR SELECT USING ((SELECT app.is_member()));
CREATE POLICY marketing_write ON marketing_activity FOR INSERT WITH CHECK (app.listing_writable(tenant_id, listing_id));

-- deals
CREATE POLICY deals_select ON deals FOR SELECT USING (
  (SELECT app.is_tenant_wide()) OR owner_user_id = (SELECT app.user_id())
  OR id = ANY ((SELECT app.my_deal_ids())::uuid[])
  OR owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[]));
CREATE POLICY deals_insert ON deals FOR INSERT WITH CHECK (
  ((SELECT app.is_tenant_wide()) OR owner_user_id = (SELECT app.user_id())
   OR owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[]))
  AND app.contact_detail_visible(tenant_id, primary_contact_id));
CREATE POLICY deals_update ON deals FOR UPDATE USING (
  (SELECT app.is_tenant_wide()) OR owner_user_id = (SELECT app.user_id())
  OR owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[]))
  WITH CHECK ((SELECT app.is_member()));
CREATE POLICY deal_members_read ON deal_members FOR SELECT USING (app.deal_visible(tenant_id, deal_id));
CREATE POLICY deal_members_write ON deal_members FOR ALL USING (app.deal_writable(tenant_id, deal_id))
  WITH CHECK (app.deal_writable(tenant_id, deal_id));
CREATE POLICY deal_contacts_read ON deal_contacts FOR SELECT USING (app.deal_visible(tenant_id, deal_id));
CREATE POLICY deal_contacts_write ON deal_contacts FOR ALL USING (app.deal_writable(tenant_id, deal_id))
  WITH CHECK (app.deal_writable(tenant_id, deal_id) AND app.contact_detail_visible(tenant_id, contact_id));
CREATE POLICY deal_dates_all ON deal_dates FOR ALL USING (app.deal_visible(tenant_id, deal_id))
  WITH CHECK (app.deal_visible(tenant_id, deal_id));
CREATE POLICY dsh_read ON deal_stage_history FOR SELECT USING (app.deal_visible(tenant_id, deal_id));
CREATE POLICY dsh_insert ON deal_stage_history FOR INSERT WITH CHECK (app.deal_visible(tenant_id, deal_id));
-- R-PERM-10: commission is visible/writable to HUMAN Owner/Admin, the deal owner, or their Team Lead only.
CREATE POLICY financials_all ON deal_financials FOR ALL USING (
  (SELECT app.actor_kind()) = 'user' AND EXISTS (
    SELECT 1 FROM deals d WHERE d.tenant_id = deal_financials.tenant_id AND d.id = deal_financials.deal_id
       AND ((SELECT app.my_role()) IN ('owner','admin') OR d.owner_user_id = (SELECT app.user_id())
            OR ((SELECT app.my_role()) = 'team_lead' AND d.owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[])))))
  WITH CHECK (
  (SELECT app.actor_kind()) = 'user' AND updated_by_user_id = (SELECT app.user_id()) AND EXISTS (
    SELECT 1 FROM deals d WHERE d.tenant_id = deal_financials.tenant_id AND d.id = deal_financials.deal_id
       AND ((SELECT app.my_role()) IN ('owner','admin') OR d.owner_user_id = (SELECT app.user_id())
            OR ((SELECT app.my_role()) = 'team_lead' AND d.owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[])))));
CREATE POLICY goals_select ON agent_goals FOR SELECT USING (
  (SELECT app.is_tenant_wide()) OR user_id = (SELECT app.user_id())
  OR user_id = ANY ((SELECT app.my_team_member_ids())::uuid[]));
CREATE POLICY goals_write ON agent_goals FOR ALL
  USING ((SELECT app.is_tenant_wide()) OR user_id = ANY ((SELECT app.my_team_member_ids())::uuid[]))
  WITH CHECK ((SELECT app.is_tenant_wide()) OR user_id = ANY ((SELECT app.my_team_member_ids())::uuid[]));

-- feed, exceptions, notifications
CREATE POLICY feed_select ON priority_feed_items FOR SELECT USING (
  (SELECT app.is_tenant_wide())
  OR (user_id = (SELECT app.user_id()) AND (contact_id IS NULL OR app.contact_visible(tenant_id, contact_id))));
CREATE POLICY feed_insert ON priority_feed_items FOR INSERT WITH CHECK (
  (SELECT app.is_tenant_wide()) OR (user_id = (SELECT app.user_id()) AND (SELECT app.is_member())));
CREATE POLICY feed_update ON priority_feed_items FOR UPDATE USING (
  (SELECT app.is_tenant_wide()) OR user_id = (SELECT app.user_id()))
  WITH CHECK ((SELECT app.is_tenant_wide()) OR user_id = (SELECT app.user_id()));
CREATE POLICY exceptions_select ON exception_items FOR SELECT USING (
  (SELECT app.is_tenant_wide()) OR owner_user_id = (SELECT app.user_id())
  OR ((SELECT app.my_role()) = 'team_lead' AND owner_user_id = ANY ((SELECT app.my_team_member_ids())::uuid[])));
CREATE POLICY exceptions_write ON exception_items FOR INSERT WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY exceptions_update ON exception_items FOR UPDATE USING ((SELECT app.is_tenant_wide())) WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY exception_events_select ON exception_events FOR SELECT USING (EXISTS (
  SELECT 1 FROM exception_items e WHERE e.tenant_id = exception_events.tenant_id AND e.dedupe_key = exception_events.exception_dedupe_key));
CREATE POLICY exception_events_insert ON exception_events FOR INSERT WITH CHECK (
  actor_user_id = (SELECT app.user_id()) AND actor_role = (SELECT app.my_role())
  AND EXISTS (SELECT 1 FROM exception_items e WHERE e.tenant_id = exception_events.tenant_id
                AND e.dedupe_key = exception_events.exception_dedupe_key));
CREATE POLICY notifications_select ON notifications FOR SELECT USING (
  user_id = (SELECT app.user_id()) OR (SELECT app.is_tenant_wide()));
CREATE POLICY notifications_insert ON notifications FOR INSERT WITH CHECK ((SELECT app.is_member()));
CREATE POLICY notifications_update ON notifications FOR UPDATE USING (
  user_id = (SELECT app.user_id()) OR (SELECT app.is_tenant_wide()))
  WITH CHECK (user_id = (SELECT app.user_id()) OR (SELECT app.is_tenant_wide()));
CREATE POLICY deliveries_select ON notification_deliveries FOR SELECT USING (EXISTS (
  SELECT 1 FROM notifications n WHERE n.tenant_id = notification_deliveries.tenant_id AND n.id = notification_deliveries.notification_id));
CREATE POLICY deliveries_write ON notification_deliveries FOR INSERT WITH CHECK ((SELECT app.is_member()));
CREATE POLICY deliveries_update ON notification_deliveries FOR UPDATE USING ((SELECT app.is_tenant_wide())) WITH CHECK ((SELECT app.is_tenant_wide()));
CREATE POLICY prefs_own ON notification_preferences FOR ALL
  USING (user_id = (SELECT app.user_id()) OR (SELECT app.is_tenant_wide()))
  WITH CHECK (user_id = (SELECT app.user_id()));
CREATE POLICY push_own ON push_subscriptions FOR ALL
  USING (user_id = (SELECT app.user_id()) OR (SELECT app.is_tenant_wide()))
  WITH CHECK (user_id = (SELECT app.user_id()) OR (SELECT app.is_tenant_wide()));

-- audit + jobs
CREATE POLICY audit_insert ON audit_log FOR INSERT WITH CHECK (
  (actor_kind = 'user' AND actor_user_id = (SELECT app.user_id()) AND (SELECT app.actor_kind()) = 'user')
  OR (actor_kind = 'system' AND (SELECT app.actor_kind()) = 'system'));
CREATE POLICY audit_read ON audit_log FOR SELECT USING ((SELECT app.my_role()) IN ('owner','admin'));
CREATE POLICY jobs_enqueue ON jobs FOR INSERT WITH CHECK ((SELECT app.is_member()));

-- -----------------------------------------------------------------------------
-- 17. Cross-tenant / pre-tenant entry points (the ONLY code that runs before a tenant
--     is known), job queue, provisioning. Owned by app_definer; minimal outputs.
-- -----------------------------------------------------------------------------
CREATE FUNCTION auth.login_lookup(p_email citext)
RETURNS TABLE (user_id uuid, password_hash text, locked_until timestamptz, disabled_at timestamptz, mfa_enabled boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT u.id, u.password_hash, u.locked_until, u.disabled_at, u.mfa_enabled_at IS NOT NULL
    FROM public.users u WHERE u.email = p_email
$$;

CREATE FUNCTION auth.record_login_result(p_user_id uuid, p_success boolean, p_now timestamptz)
RETURNS void LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  UPDATE public.users SET
    failed_login_count = CASE WHEN p_success THEN 0 ELSE failed_login_count + 1 END,
    locked_until = CASE WHEN p_success THEN NULL
                        WHEN failed_login_count + 1 >= 10 THEN p_now + interval '15 minutes'
                        ELSE locked_until END
   WHERE id = p_user_id
$$;

CREATE FUNCTION auth.rate_limit_hit(p_key text, p_window_start timestamptz, p_max integer)
RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  INSERT INTO public.auth_attempts AS a (key, window_start, count) VALUES (p_key, p_window_start, 1)
  ON CONFLICT (key, window_start) DO UPDATE SET count = a.count + 1
  RETURNING a.count <= p_max
$$;

CREATE FUNCTION auth.resolve_session(p_token_hash bytea, p_now timestamptz)
RETURNS TABLE (session_id uuid, user_id uuid, tenant_id uuid, role text, mfa_verified_at timestamptz,
               reauthenticated_at timestamptz, idle_expires_at timestamptz, last_seen_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT s.id, s.user_id, s.active_tenant_id, m.role, s.mfa_verified_at, s.reauthenticated_at, s.idle_expires_at, s.last_seen_at
    FROM public.sessions s
    JOIN public.users u ON u.id = s.user_id AND u.disabled_at IS NULL
    LEFT JOIN public.memberships m ON m.tenant_id = s.active_tenant_id AND m.user_id = s.user_id AND m.status = 'active'
    LEFT JOIN public.tenants t ON t.id = s.active_tenant_id
   WHERE s.token_hash = p_token_hash AND s.revoked_at IS NULL
     AND s.idle_expires_at > p_now AND s.absolute_expires_at > p_now
     AND (s.active_tenant_id IS NULL OR (m.user_id IS NOT NULL AND t.status = 'active'))
$$;

CREATE FUNCTION auth.user_tenants()
RETURNS TABLE (tenant_id uuid, slug citext, name text, role text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT t.id, t.slug, t.name, m.role FROM public.memberships m JOIN public.tenants t ON t.id = m.tenant_id
   WHERE m.user_id = app.user_id() AND m.status = 'active' AND t.status = 'active'
   ORDER BY t.name
$$;

CREATE FUNCTION auth.mfa_secret()
RETURNS bytea LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT u.mfa_totp_secret_enc FROM public.users u WHERE u.id = app.user_id()
$$;

CREATE FUNCTION auth.issue_password_reset(p_email citext, p_token_hash bytea, p_now timestamptz)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE uid uuid;
BEGIN
  SELECT u.id INTO uid FROM public.users u WHERE u.email = p_email AND u.disabled_at IS NULL;
  IF uid IS NULL THEN RETURN; END IF;                 -- uniform response; no enumeration
  UPDATE public.auth_tokens SET superseded_at = p_now
   WHERE user_id = uid AND purpose = 'password_reset' AND used_at IS NULL AND superseded_at IS NULL;
  INSERT INTO public.auth_tokens (token_hash, purpose, user_id, created_at, expires_at)
  VALUES (p_token_hash, 'password_reset', uid, p_now, p_now + interval '30 minutes');
END $$;

CREATE FUNCTION auth.consume_password_reset(p_token_hash bytea, p_password_hash text, p_now timestamptz)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE uid uuid;
BEGIN
  UPDATE public.auth_tokens SET used_at = p_now
   WHERE token_hash = p_token_hash AND purpose = 'password_reset' AND used_at IS NULL
     AND superseded_at IS NULL AND expires_at > p_now
  RETURNING user_id INTO uid;
  IF uid IS NULL THEN RETURN NULL; END IF;
  UPDATE public.users SET password_hash = p_password_hash, password_changed_at = p_now,
         failed_login_count = 0, locked_until = NULL WHERE id = uid;
  UPDATE public.sessions SET revoked_at = p_now, revoked_reason = 'password_change'
   WHERE user_id = uid AND revoked_at IS NULL;
  RETURN uid;
END $$;

CREATE FUNCTION auth.accept_invite(p_token_hash bytea, p_new_user_id uuid, p_display_name text,
                                   p_password_hash text, p_now timestamptz)
RETURNS TABLE (o_tenant_id uuid, o_user_id uuid, o_created_user boolean)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE inv record; uid uuid; created boolean := false;
BEGIN
  SELECT i.* INTO inv FROM public.invites i
   WHERE i.token_hash = p_token_hash AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > p_now
   FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT u.id INTO uid FROM public.users u WHERE u.email = inv.email;
  IF uid IS NULL THEN
    IF p_password_hash IS NULL OR p_new_user_id IS NULL THEN
      RAISE EXCEPTION 'PASSWORD_REQUIRED' USING ERRCODE = 'check_violation';
    END IF;
    INSERT INTO public.users (id, email, email_verified_at, display_name, password_hash, password_changed_at)
    VALUES (p_new_user_id, inv.email, p_now, p_display_name, p_password_hash, p_now);
    uid := p_new_user_id; created := true;
  ELSIF app.user_id() IS DISTINCT FROM uid THEN
    RAISE EXCEPTION 'LOGIN_REQUIRED: existing users accept while signed in' USING ERRCODE = 'insufficient_privilege';
  END IF;
  INSERT INTO public.memberships AS m (tenant_id, user_id, role, status, accepting_leads, invited_by_user_id, joined_at)
  VALUES (inv.tenant_id, uid, inv.role, 'active', inv.role <> 'tc', inv.invited_by_user_id, p_now)
  ON CONFLICT (tenant_id, user_id) DO UPDATE
    SET role = EXCLUDED.role, status = 'active', removed_at = NULL, joined_at = EXCLUDED.joined_at,
        accepting_leads = EXCLUDED.accepting_leads;
  UPDATE public.invites SET accepted_at = p_now WHERE tenant_id = inv.tenant_id AND id = inv.id;
  RETURN QUERY SELECT inv.tenant_id, uid, created;
END $$;

CREATE FUNCTION app.resolve_inbound_number(p_e164 text)
RETURNS TABLE (tenant_id uuid, phone_number_id uuid, assigned_user_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT n.tenant_id, n.id, n.assigned_user_id FROM public.phone_numbers n
    JOIN public.tenants t ON t.id = n.tenant_id AND t.status = 'active'
   WHERE n.e164 = p_e164 AND n.released_at IS NULL
$$;

CREATE FUNCTION app.resolve_inbound_email_token(p_token_hash bytea)
RETURNS TABLE (tenant_id uuid, conversation_id uuid, contact_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT c.tenant_id, c.id, c.contact_id FROM public.conversations c
    JOIN public.tenants t ON t.id = c.tenant_id AND t.status = 'active'
   WHERE c.reply_token_hash = p_token_hash
$$;

CREATE FUNCTION app.resolve_lead_source(p_token_hash bytea)
RETURNS TABLE (tenant_id uuid, lead_source_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT s.tenant_id, s.id FROM public.lead_sources s
    JOIN public.tenants t ON t.id = s.tenant_id AND t.status = 'active'
   WHERE s.ingest_token_hash = p_token_hash AND s.active
$$;

CREATE FUNCTION app.record_webhook_event(p_id uuid, p_provider text, p_provider_event_id text, p_tenant_id uuid,
                                         p_signature_valid boolean, p_payload_enc bytea, p_now timestamptz)
RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  WITH ins AS (
    INSERT INTO public.webhook_events (id, provider, provider_event_id, tenant_id, received_at, signature_valid, status, payload_enc)
    VALUES (p_id, p_provider, p_provider_event_id, p_tenant_id, p_now, p_signature_valid,
            CASE WHEN NOT p_signature_valid THEN 'rejected' WHEN p_tenant_id IS NULL THEN 'unrouted' ELSE 'received' END,
            CASE WHEN p_signature_valid THEN p_payload_enc END)
    ON CONFLICT (provider, provider_event_id) DO NOTHING
    RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM ins)
$$;

CREATE FUNCTION app.finish_webhook_event(p_id uuid, p_status text, p_error_code text, p_now timestamptz)
RETURNS void LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  UPDATE public.webhook_events SET status = p_status, error_code = left(p_error_code, 100), processed_at = p_now
   WHERE id = p_id AND status = 'received' AND p_status IN ('processed','failed')
$$;

-- Worker claim: the one place that reads jobs across tenants. Returns ids + tenant only;
-- the worker opens a NEW transaction per job with SET LOCAL app.tenant_id = job.tenant_id.
CREATE FUNCTION app.claim_jobs(p_queues text[], p_worker text, p_limit integer, p_lease interval)
RETURNS TABLE (id bigint, tenant_id uuid, queue text, kind text, payload jsonb, attempts integer)
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  WITH c AS (
    SELECT j.id FROM public.jobs j
     WHERE j.queue = ANY (p_queues) AND j.status = 'pending' AND j.run_at <= now()
     ORDER BY j.priority, j.run_at, j.id
     LIMIT LEAST(GREATEST(p_limit, 1), 100)
     FOR UPDATE SKIP LOCKED)
  UPDATE public.jobs j SET status = 'running', locked_by = p_worker,
         locked_until = now() + LEAST(p_lease, interval '15 minutes'), attempts = j.attempts + 1
    FROM c WHERE j.id = c.id
  RETURNING j.id, j.tenant_id, j.queue, j.kind, j.payload, j.attempts
$$;

CREATE FUNCTION app.finish_job(p_id bigint, p_worker text, p_ok boolean, p_error text, p_retry_at timestamptz)
RETURNS void LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  UPDATE public.jobs j SET
    status = CASE WHEN p_ok THEN 'succeeded'
                  WHEN j.attempts >= j.max_attempts OR p_retry_at IS NULL THEN 'dead'
                  ELSE 'pending' END,
    run_at = CASE WHEN NOT p_ok AND p_retry_at IS NOT NULL THEN p_retry_at ELSE j.run_at END,
    locked_by = NULL, locked_until = NULL,
    last_error = left(p_error, 500),
    finished_at = CASE WHEN p_ok OR j.attempts >= j.max_attempts OR p_retry_at IS NULL THEN now() END
   WHERE j.id = p_id AND j.locked_by = p_worker AND j.status = 'running'
$$;

-- Leases that expired (crashed worker): back to pending, or dead when attempts are exhausted.
-- Re-running a dispatch job never re-sends: TX1 only claims scheduled/queued messages. A message left in
-- 'dispatching' by a crash is NOT recovered here; app.due_work's 'dispatch_stale' branch moves it to
-- dispatch_unknown for provider reconciliation (F2).
CREATE FUNCTION app.reap_stuck_jobs()
RETURNS integer LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  WITH r AS (
    UPDATE public.jobs j SET
      status = CASE WHEN j.attempts >= j.max_attempts THEN 'dead' ELSE 'pending' END,
      finished_at = CASE WHEN j.attempts >= j.max_attempts THEN now() END,
      locked_by = NULL, locked_until = NULL, last_error = 'LEASE_EXPIRED'
     WHERE j.status = 'running' AND j.locked_until < now()
    RETURNING 1)
  SELECT count(*)::int FROM r
$$;

-- Tenant-scoped cancellation (e.g. superseded timers). Never crosses tenants.
CREATE FUNCTION app.cancel_jobs(p_dedupe_keys text[])
RETURNS integer LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  WITH r AS (
    UPDATE public.jobs j SET status = 'cancelled', finished_at = now()
     WHERE j.tenant_id = app.tenant_id() AND app.is_member()
       AND j.dedupe_key = ANY (p_dedupe_keys) AND j.status = 'pending'
    RETURNING 1)
  SELECT count(*)::int FROM r
$$;

-- Deadline sweeper: deadlines live in data; jobs only wake the system. Identifiers only.
CREATE FUNCTION app.due_work(p_now timestamptz, p_limit integer)
RETURNS TABLE (tenant_id uuid, work_kind text, ref_id uuid, due_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  (SELECT c.tenant_id, 'offer_expiry', c.id, c.offer_expires_at FROM public.contacts c
    WHERE c.ownership_state = 'offered' AND c.offer_expires_at <= p_now ORDER BY c.offer_expires_at LIMIT p_limit)
  UNION ALL
  (SELECT c.tenant_id, 'first_touch_breach', c.id, c.first_touch_due_at FROM public.contacts c
    WHERE c.ownership_state = 'owned' AND c.first_touch_at IS NULL AND c.first_touch_breached_at IS NULL
      AND c.first_touch_due_at <= p_now ORDER BY c.first_touch_due_at LIMIT p_limit)
  UNION ALL
  (SELECT c.tenant_id, 'auto_release', c.id, c.release_due_at FROM public.contacts c
    WHERE c.ownership_state = 'owned' AND c.first_touch_at IS NULL AND c.release_due_at <= p_now
    ORDER BY c.release_due_at LIMIT p_limit)
  UNION ALL
  (SELECT c.tenant_id, 'inactivity', c.id, LEAST(c.inactivity_warn_at, c.inactivity_release_at)
     FROM public.contacts c
    WHERE c.ownership_state = 'owned' AND c.stage IN ('new','attempting')
      -- F6: stored instants only (computed by core when ownership started / at the last human touch);
      -- a settings change never moves an existing deadline
      AND (c.inactivity_warn_at <= p_now OR c.inactivity_release_at <= p_now)
      AND NOT EXISTS (SELECT 1 FROM public.deals d WHERE d.tenant_id = c.tenant_id AND d.primary_contact_id = c.id
                         AND d.stage NOT IN ('closed','lost'))
      AND NOT EXISTS (SELECT 1 FROM public.deal_contacts dc JOIN public.deals d ON d.tenant_id = dc.tenant_id AND d.id = dc.deal_id
                       WHERE dc.tenant_id = c.tenant_id AND dc.contact_id = c.id AND d.stage NOT IN ('closed','lost'))
    LIMIT p_limit)
  UNION ALL
  (SELECT c.tenant_id, 'route', c.id, c.route_due_at FROM public.contacts c   -- F1: lost ownership.followup backstop
    WHERE c.ownership_state = 'unassigned' AND c.route_due_at <= p_now - interval '15 seconds'
    ORDER BY c.route_due_at LIMIT p_limit)
  UNION ALL
  (SELECT m.tenant_id, 'message_dispatch', m.id, m.scheduled_for FROM public.messages m
    WHERE m.status IN ('scheduled','queued') AND m.scheduled_for <= p_now ORDER BY m.scheduled_for LIMIT p_limit)
  UNION ALL
  (SELECT m.tenant_id, 'dispatch_reconcile', m.id, m.dispatched_at FROM public.messages m
    WHERE m.status = 'dispatch_unknown' AND m.dispatched_at <= p_now - interval '2 minutes' LIMIT p_limit)
  UNION ALL
  -- F2: TX1 committed 'dispatching' but no TX2 followed (worker died around provider.send). Past the
  -- maximum job lease (15 min) + 5 min margin the worker is certainly gone: -> dispatch_unknown, reconcile.
  (SELECT m.tenant_id, 'dispatch_stale', m.id, m.dispatched_at FROM public.messages m
    WHERE m.status = 'dispatching' AND m.dispatched_at <= p_now - interval '20 minutes' LIMIT p_limit)
  UNION ALL
  (SELECT e.tenant_id, 'playbook_step', e.id, e.next_step_due_at FROM public.playbook_enrollments e
    WHERE e.state = 'active' AND e.next_step_due_at <= p_now ORDER BY e.next_step_due_at LIMIT p_limit)
  UNION ALL
  (SELECT d.tenant_id, 'notification_delivery', d.id, d.next_attempt_at FROM public.notification_deliveries d
    WHERE d.status = 'pending' AND d.next_attempt_at <= p_now ORDER BY d.next_attempt_at LIMIT p_limit)
$$;

-- Claim eligibility inputs for core (counts span contacts the caller may not see).
CREATE FUNCTION app.claim_stats(p_user_id uuid, p_contact_id uuid, p_day_start timestamptz, p_cooldown_since timestamptz)
RETURNS TABLE (claims_today integer, in_cooldown boolean, uncontacted_owned integer)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT
    (SELECT count(*)::int FROM public.lead_ownership_events e
      WHERE e.tenant_id = app.tenant_id() AND e.actor_user_id = p_user_id AND e.type = 'claimed'
        AND e.occurred_at >= p_day_start),
    EXISTS (SELECT 1 FROM public.lead_ownership_events e
             WHERE e.tenant_id = app.tenant_id() AND e.contact_id = p_contact_id AND e.prev_owner_user_id = p_user_id
               AND e.type IN ('released','auto_released','inactivity_released','reassigned','sent_to_pond')
               AND e.occurred_at >= p_cooldown_since),
    (SELECT count(*)::int FROM public.contacts c
      WHERE c.tenant_id = app.tenant_id() AND c.owner_user_id = p_user_id AND c.ownership_state = 'owned'
        AND c.first_touch_at IS NULL AND c.first_touch_due_at IS NOT NULL)
  WHERE app.is_member() AND (p_user_id = app.user_id() OR app.is_tenant_wide())
$$;

-- Dedup on create/intake must see contacts the caller cannot (returns no details, R-PERM-12).
CREATE FUNCTION app.find_contacts_by_address(p_address_hmacs bytea[])
RETURNS TABLE (contact_id uuid, owner_user_id uuid, owner_display_name text, ownership_state text, matched_hmac bytea)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT c.id, c.owner_user_id, u.display_name, c.ownership_state, p.address_hmac
    FROM public.contact_points p
    JOIN public.contacts c ON c.tenant_id = p.tenant_id AND c.id = p.contact_id
    LEFT JOIN public.users u ON u.id = c.owner_user_id
   WHERE p.tenant_id = app.tenant_id() AND app.is_member()
     AND p.address_hmac = ANY (p_address_hmacs) AND p.removed_at IS NULL
     AND c.deleted_at IS NULL AND c.merged_into_contact_id IS NULL
   ORDER BY c.created_at, c.id
$$;

-- Tenant-wide stage dwell norms (aggregates only) for the momentum view (A5).
CREATE FUNCTION app.stage_dwell_norms()
RETURNS TABLE (stage text, median_days numeric, sample_size integer)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  WITH h AS (
    SELECT dsh.to_stage,
           EXTRACT(EPOCH FROM (lead(dsh.changed_at) OVER (PARTITION BY dsh.deal_id ORDER BY dsh.changed_at, dsh.id)
                               - dsh.changed_at)) / 86400.0 AS dwell_days,
           dsh.changed_at
      FROM public.deal_stage_history dsh
     WHERE dsh.tenant_id = app.tenant_id() AND app.is_member())
  SELECT h.to_stage, round(percentile_cont(0.5) WITHIN GROUP (ORDER BY h.dwell_days)::numeric, 1), count(*)::int
    FROM h WHERE h.dwell_days IS NOT NULL AND h.changed_at >= now() - interval '180 days'
   GROUP BY h.to_stage
$$;

-- Revoke sessions whose active tenant is the caller's tenant (membership removed/suspended).
CREATE FUNCTION app.revoke_member_sessions(p_user_id uuid, p_now timestamptz)
RETURNS integer LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  WITH r AS (
    UPDATE public.sessions s SET revoked_at = p_now, revoked_reason = 'membership_removed'
     WHERE s.user_id = p_user_id AND s.active_tenant_id = app.tenant_id() AND s.revoked_at IS NULL
       AND app.is_tenant_wide()
    RETURNING 1)
  SELECT count(*)::int FROM r
$$;

-- Tenant provisioning at signup: tenant, Owner membership, policy v1, settings, default team
-- and pond, wrapped tenant keys. Ids come from the core id generator.
CREATE FUNCTION app.provision_tenant(
  p_tenant_id uuid, p_slug citext, p_name text, p_timezone text, p_brokerage_legal_name text,
  p_owner_user_id uuid, p_policy_id uuid, p_team_id uuid, p_pond_id uuid,
  p_wrapped_field_key bytea, p_wrapped_object_key bytea, p_wrapped_hmac_key bytea, p_kek_ref text)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
  IF app.user_id() IS NULL OR app.user_id() <> p_owner_user_id THEN
    RAISE EXCEPTION 'PROVISION_FORBIDDEN: caller must be the owner user' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_owner_user_id AND u.disabled_at IS NULL) THEN
    RAISE EXCEPTION 'PROVISION_FORBIDDEN: unknown user' USING ERRCODE = 'insufficient_privilege';
  END IF;
  INSERT INTO public.tenants (id, slug, name) VALUES (p_tenant_id, p_slug, p_name);
  INSERT INTO public.memberships (tenant_id, user_id, role, status, accepting_leads, joined_at)
  VALUES (p_tenant_id, p_owner_user_id, 'owner', 'active', true, now());
  INSERT INTO public.compliance_policy_versions (tenant_id, id, version_no, created_by_user_id)
  VALUES (p_tenant_id, p_policy_id, 1, p_owner_user_id);
  INSERT INTO public.tenant_settings (tenant_id, brokerage_legal_name, team_name, default_timezone, active_policy_id)
  VALUES (p_tenant_id, p_brokerage_legal_name, p_name, p_timezone, p_policy_id);
  INSERT INTO public.teams (tenant_id, id, name, is_default) VALUES (p_tenant_id, p_team_id, p_name, true);
  INSERT INTO public.team_members (tenant_id, team_id, user_id, is_lead) VALUES (p_tenant_id, p_team_id, p_owner_user_id, true);
  INSERT INTO public.ponds (tenant_id, id, name, is_default) VALUES (p_tenant_id, p_pond_id, 'Team Pond', true);
  INSERT INTO public.tenant_keys (tenant_id, purpose, key_version, wrapped_key, kek_ref) VALUES
    (p_tenant_id, 'field', 1, p_wrapped_field_key, p_kek_ref),
    (p_tenant_id, 'object', 1, p_wrapped_object_key, p_kek_ref),
    (p_tenant_id, 'hmac', 1, p_wrapped_hmac_key, p_kek_ref);
END $$;

-- -----------------------------------------------------------------------------
-- 18. Retention and erasure (owned by app_retention; the only DELETE path on ledgers)
-- -----------------------------------------------------------------------------
CREATE FUNCTION app.purge_contact_internal(p_tenant uuid, p_contact uuid)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
  DELETE FROM public.behavior_events WHERE tenant_id = p_tenant AND contact_id = p_contact;
  DELETE FROM public.message_status_events s USING public.messages m
   WHERE s.tenant_id = p_tenant AND m.tenant_id = p_tenant AND s.message_id = m.id AND m.contact_id = p_contact;
  UPDATE public.stored_objects o SET dek_wrapped = NULL, deleted_at = now()
    FROM public.recordings r
   WHERE r.tenant_id = p_tenant AND r.contact_id = p_contact AND o.tenant_id = p_tenant AND o.id = r.object_id
     AND o.deleted_at IS NULL;
  UPDATE public.stored_objects o SET dek_wrapped = NULL, deleted_at = now()
    FROM public.message_media mm JOIN public.messages m ON m.tenant_id = mm.tenant_id AND m.id = mm.message_id
   WHERE m.tenant_id = p_tenant AND m.contact_id = p_contact AND o.tenant_id = p_tenant AND o.id = mm.object_id
     AND o.deleted_at IS NULL;
  DELETE FROM public.external_refs WHERE tenant_id = p_tenant AND entity_type = 'contact' AND entity_id = p_contact;
  DELETE FROM public.contacts WHERE tenant_id = p_tenant AND id = p_contact;   -- children cascade
END $$;

-- Privacy erasure (Owner/Admin): hard delete now; consent/suppression rows survive by HMAC;
-- ownership ledger and audit hold no PII and are kept. VERIFY WITH COUNSEL (applicability).
CREATE FUNCTION app.erase_contact(p_contact_id uuid, p_audit_id uuid, p_reason text)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE t uuid := app.tenant_id(); r text := app.my_role();
BEGIN
  IF t IS NULL OR r IS NULL OR r NOT IN ('owner','admin') THEN
    RAISE EXCEPTION 'ERASE_FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.tenant_id = t AND c.id = p_contact_id) THEN
    RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE = 'no_data_found';
  END IF;
  IF EXISTS (SELECT 1 FROM public.deals d WHERE d.tenant_id = t AND d.primary_contact_id = p_contact_id)
     OR EXISTS (SELECT 1 FROM public.deal_contacts dc WHERE dc.tenant_id = t AND dc.contact_id = p_contact_id) THEN
    RAISE EXCEPTION 'CONTACT_ON_DEAL: remove from deals first (transaction records)' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app.purge_contact_internal(t, p_contact_id);
  INSERT INTO public.audit_log (tenant_id, id, occurred_at, actor_kind, actor_via, actor_user_id, actor_role,
                                action, entity_type, entity_id, changes, reason)
  VALUES (t, p_audit_id, now(), 'user', 'api', app.user_id(), r, 'contact.erase', 'contact', p_contact_id,
          '{"erased": true}', p_reason);
END $$;

CREATE FUNCTION app.retention_sweep(p_now timestamptz)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  rec record;
  n_contacts integer := 0; n_sessions integer; n_jobs integer; n_auth integer; n_notif integer;
  n_audit integer; n_rec integer; n_raw integer; n_ai integer; n_webhooks integer;
BEGIN
  DELETE FROM public.sessions WHERE COALESCE(revoked_at, absolute_expires_at) < p_now - interval '30 days';
  GET DIAGNOSTICS n_sessions = ROW_COUNT;
  DELETE FROM public.jobs WHERE (status = 'succeeded' AND finished_at < p_now - interval '14 days')
                             OR (status IN ('dead','cancelled') AND finished_at < p_now - interval '90 days');
  GET DIAGNOSTICS n_jobs = ROW_COUNT;
  DELETE FROM public.auth_events WHERE occurred_at < p_now - interval '1 year';
  GET DIAGNOSTICS n_auth = ROW_COUNT;
  DELETE FROM public.auth_attempts WHERE window_start < p_now - interval '1 day';
  DELETE FROM public.auth_tokens WHERE expires_at < p_now - interval '7 days';
  UPDATE public.webhook_events SET payload_enc = NULL WHERE payload_enc IS NOT NULL AND received_at < p_now - interval '30 days';
  GET DIAGNOSTICS n_webhooks = ROW_COUNT;
  DELETE FROM public.notifications WHERE created_at < p_now - interval '90 days';
  GET DIAGNOSTICS n_notif = ROW_COUNT;
  DELETE FROM public.audit_log WHERE occurred_at < p_now - interval '7 years';      -- VERIFY WITH COUNSEL
  GET DIAGNOSTICS n_audit = ROW_COUNT;
  UPDATE public.import_records SET raw_enc = NULL, raw_purged_at = p_now
   WHERE raw_enc IS NOT NULL AND created_at < p_now - interval '30 days';
  GET DIAGNOSTICS n_raw = ROW_COUNT;
  UPDATE public.ai_runs SET output_enc = NULL, output_purged_at = p_now
   WHERE output_enc IS NOT NULL AND created_at < p_now - interval '30 days';
  GET DIAGNOSTICS n_ai = ROW_COUNT;
  UPDATE public.lead_inquiries SET raw_payload_enc = NULL
   WHERE raw_payload_enc IS NOT NULL AND received_at < p_now - interval '90 days';
  UPDATE public.provider_credentials SET secret_enc = NULL, status = 'purged', purged_at = p_now
   WHERE status <> 'purged' AND purge_after IS NOT NULL AND purge_after <= p_now;
  -- recordings past retention (not on legal hold): shred DEK, transcript, transcript snippets
  UPDATE public.recordings SET status = 'shredded', shredded_at = p_now
   WHERE status IN ('stored','quarantined','pending_copy') AND NOT legal_hold AND retain_until <= p_now;
  GET DIAGNOSTICS n_rec = ROW_COUNT;
  UPDATE public.stored_objects o SET dek_wrapped = NULL, deleted_at = p_now
    FROM public.recordings r
   WHERE r.tenant_id = o.tenant_id AND r.object_id = o.id AND r.status = 'shredded' AND o.deleted_at IS NULL;
  UPDATE public.transcripts tr SET status = 'shredded', segments_enc = NULL
    FROM public.recordings r
   WHERE r.tenant_id = tr.tenant_id AND r.id = tr.recording_id AND r.status = 'shredded' AND tr.status <> 'shredded';
  UPDATE public.evidence_refs e SET snippet = NULL, snippet_enc = NULL, source_available = false
   WHERE e.source_type = 'call' AND e.source_available AND EXISTS (
         SELECT 1 FROM public.recordings r WHERE r.tenant_id = e.tenant_id AND r.call_id = e.source_id AND r.status = 'shredded');
  -- soft-deleted contacts past purge_after and not on any deal
  FOR rec IN SELECT c.tenant_id, c.id FROM public.contacts c
              WHERE c.deleted_at IS NOT NULL AND c.purge_after <= p_now
                AND NOT EXISTS (SELECT 1 FROM public.deals d WHERE d.tenant_id = c.tenant_id AND d.primary_contact_id = c.id)
                AND NOT EXISTS (SELECT 1 FROM public.deal_contacts dc WHERE dc.tenant_id = c.tenant_id AND dc.contact_id = c.id)
              ORDER BY c.purge_after LIMIT 500 LOOP
    PERFORM app.purge_contact_internal(rec.tenant_id, rec.id);
    n_contacts := n_contacts + 1;
  END LOOP;
  RETURN jsonb_build_object('sessions', n_sessions, 'jobs', n_jobs, 'auth_events', n_auth, 'notifications', n_notif,
                            'audit_log', n_audit, 'recordings_shredded', n_rec, 'import_raw_purged', n_raw,
                            'ai_outputs_purged', n_ai, 'webhook_payloads_purged', n_webhooks, 'contacts_purged', n_contacts);
END $$;

-- -----------------------------------------------------------------------------
-- 19. Views (security_invoker: the caller's RLS applies to every base table)
-- -----------------------------------------------------------------------------
CREATE VIEW contact_timeline WITH (security_invoker = true) AS
  SELECT m.tenant_id, m.contact_id, m.occurred_at, 'message'::text AS item_type, m.id AS item_id,
         m.initiated_by_user_id AS actor_user_id, m.channel || ':' || m.direction AS detail,
         left(m.body, 280) AS preview, CASE WHEN m.imported THEN 'imported' ELSE 'native' END AS provenance
    FROM messages m
  UNION ALL
  SELECT c.tenant_id, c.contact_id, c.started_at, 'call', c.id, c.agent_user_id, c.direction || ':' || c.status,
         c.outcome, CASE WHEN c.imported THEN 'imported' ELSE 'native' END
    FROM calls c
  UNION ALL
  SELECT n.tenant_id, n.contact_id, n.created_at, 'note', n.id, n.author_user_id, n.source, left(n.body, 280),
         CASE WHEN n.imported THEN 'imported' ELSE 'native' END
    FROM notes n WHERE n.contact_id IS NOT NULL
  UNION ALL
  SELECT e.tenant_id, e.contact_id, e.occurred_at, 'ownership', e.event_id, e.actor_user_id, e.type, e.reason_code,
         CASE WHEN e.actor_kind = 'import' THEN 'imported' ELSE 'native' END
    FROM lead_ownership_events e
  UNION ALL
  SELECT a.tenant_id, a.contact_id, a.starts_at, 'appointment', a.id, a.user_id, a.kind || ':' || a.status, a.outcome, 'native'
    FROM appointments a WHERE a.contact_id IS NOT NULL
  UNION ALL
  SELECT b.tenant_id, b.contact_id, b.occurred_at, 'behavior', b.id, NULL::uuid, b.event_type, b.reliability, 'native'
    FROM behavior_events b;

-- Speed-to-lead per ownership period that started an SLA (A7e). Denominators are explicit.
CREATE VIEW v_speed_to_lead WITH (security_invoker = true) AS
  SELECT e.tenant_id, e.owner_user_id AS user_id, e.contact_id, e.seq AS owned_seq,
         e.occurred_at AS owned_at, e.deadline_at AS first_touch_due_at, ft.occurred_at AS first_touch_at,
         CASE WHEN ft.occurred_at IS NOT NULL THEN EXTRACT(EPOCH FROM (ft.occurred_at - e.occurred_at))::bigint END AS response_seconds,
         (ft.occurred_at IS NOT NULL AND ft.occurred_at <= e.deadline_at) AS within_sla
    FROM lead_ownership_events e
    LEFT JOIN LATERAL (
      SELECT f.occurred_at FROM lead_ownership_events f
       WHERE f.tenant_id = e.tenant_id AND f.contact_id = e.contact_id AND f.seq > e.seq
         AND f.type = 'first_touch_recorded'
         AND NOT EXISTS (SELECT 1 FROM lead_ownership_events x
                          WHERE x.tenant_id = e.tenant_id AND x.contact_id = e.contact_id
                            AND x.seq > e.seq AND x.seq < f.seq
                            AND x.type IN ('reassigned','released','auto_released','inactivity_released','sent_to_pond',
                                           'closed','merged_away','claimed','assigned','offer_accepted'))
       ORDER BY f.seq LIMIT 1) ft ON true
   WHERE e.type IN ('offer_accepted','claimed','assigned','reassigned') AND e.deadline_at IS NOT NULL;

-- Per-agent daily activity (touches = human outbound only; assistant messages never count).
CREATE VIEW v_agent_activity_daily WITH (security_invoker = true) AS
  WITH rows AS (
    SELECT m.tenant_id, m.initiated_by_user_id AS user_id, m.occurred_at AS at, 'text_or_email'::text AS metric
      FROM messages m
     WHERE m.direction = 'outbound' AND m.initiator = 'human'
       AND m.status IN ('sent','delivered','dispatch_unknown')
    UNION ALL
    SELECT c.tenant_id, c.agent_user_id, c.started_at, 'call' FROM calls c
     WHERE c.direction = 'outbound' AND c.initiator = 'human'
    UNION ALL
    SELECT a.tenant_id, COALESCE(a.set_by_user_id, a.user_id), a.created_at, 'appointment_set' FROM appointments a
     WHERE a.created_by_kind = 'user'
    UNION ALL
    SELECT a.tenant_id, a.user_id, a.starts_at, 'appointment_held' FROM appointments a WHERE a.status = 'held'
    UNION ALL
    SELECT h.tenant_id, d.owner_user_id, h.changed_at, 'agreement_signed' FROM deal_stage_history h
      JOIN deals d ON d.tenant_id = h.tenant_id AND d.id = h.deal_id
     WHERE h.to_stage = 'agreement_signed')
  SELECT r.tenant_id, r.user_id, (r.at AT TIME ZONE s.default_timezone)::date AS day,
         count(*) FILTER (WHERE r.metric IN ('text_or_email','call')) AS touches,
         count(*) FILTER (WHERE r.metric = 'call') AS calls,
         count(*) FILTER (WHERE r.metric = 'text_or_email') AS texts_and_emails,
         count(*) FILTER (WHERE r.metric = 'appointment_set') AS appointments_set,
         count(*) FILTER (WHERE r.metric = 'appointment_held') AS appointments_held,
         count(*) FILTER (WHERE r.metric = 'agreement_signed') AS agreements_signed
    FROM rows r JOIN tenant_settings s ON s.tenant_id = r.tenant_id
   WHERE r.user_id IS NOT NULL
   GROUP BY r.tenant_id, r.user_id, (r.at AT TIME ZONE s.default_timezone)::date;

-- Where pipelines lose momentum: current stage dwell vs tenant norm (A5).
CREATE VIEW v_pipeline_momentum WITH (security_invoker = true) AS
  SELECT d.tenant_id, d.id AS deal_id, d.owner_user_id, d.stage, d.stage_entered_at,
         round((EXTRACT(EPOCH FROM (now() - d.stage_entered_at)) / 86400.0)::numeric, 1) AS dwell_days,
         n.median_days AS team_median_days, n.sample_size,
         (n.sample_size >= 5 AND EXTRACT(EPOCH FROM (now() - d.stage_entered_at)) / 86400.0 > 1.5 * n.median_days) AS is_slow
    FROM deals d
    LEFT JOIN app.stage_dwell_norms() n ON n.stage = d.stage
   WHERE d.stage NOT IN ('closed','lost');

-- -----------------------------------------------------------------------------
-- 20. Ownership of definer functions + grants (least privilege)
-- -----------------------------------------------------------------------------
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app, auth FROM PUBLIC;

DO $$
DECLARE f text;
BEGIN
  FOREACH f IN ARRAY ARRAY[
     'app.my_role()','app.is_tenant_wide()','app.is_member()','app.sees_all_detail()','app.my_team_member_ids()',
     'app.my_pond_ids()','app.my_deal_ids()','app.my_deal_contact_ids()','app.my_collab_contact_ids()',
     'app.recording_scope()','app.contact_exists(uuid,uuid)',
     'app.contacts_guard()','app.lead_ownership_events_guard()','app.consent_state_guard()',
     'app.messages_dispatch_guard()','app.calls_dispatch_guard()','app.claim_evidence_check()',
     'app.playbook_versions_guard()','app.playbook_approvals_guard()','app.playbook_enrollments_guard()',
     'app.import_stages_guard()','app.phone_numbers_quarantine()','app.exception_events_guard()',
     'auth.login_lookup(citext)','auth.record_login_result(uuid,boolean,timestamptz)',
     'auth.rate_limit_hit(text,timestamptz,integer)','auth.resolve_session(bytea,timestamptz)','auth.user_tenants()',
     'auth.mfa_secret()','auth.issue_password_reset(citext,bytea,timestamptz)',
     'auth.consume_password_reset(bytea,text,timestamptz)','auth.accept_invite(bytea,uuid,text,text,timestamptz)',
     'app.resolve_inbound_number(text)','app.resolve_inbound_email_token(bytea)','app.resolve_lead_source(bytea)',
     'app.record_webhook_event(uuid,text,text,uuid,boolean,bytea,timestamptz)',
     'app.finish_webhook_event(uuid,text,text,timestamptz)',
     'app.claim_jobs(text[],text,integer,interval)','app.finish_job(bigint,text,boolean,text,timestamptz)',
     'app.reap_stuck_jobs()','app.cancel_jobs(text[])','app.due_work(timestamptz,integer)',
     'app.claim_stats(uuid,uuid,timestamptz,timestamptz)','app.find_contacts_by_address(bytea[])',
     'app.stage_dwell_norms()','app.revoke_member_sessions(uuid,timestamptz)',
     'app.provision_tenant(uuid,citext,text,text,text,uuid,uuid,uuid,uuid,bytea,bytea,bytea,text)'] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO app_definer', f);
  END LOOP;
  FOREACH f IN ARRAY ARRAY['app.purge_contact_internal(uuid,uuid)','app.erase_contact(uuid,uuid,text)',
                           'app.retention_sweep(timestamptz)'] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO app_retention', f);
  END LOOP;
END $$;

-- What the definer/retention roles may touch (they own no tables).
GRANT SELECT ON ALL TABLES IN SCHEMA public TO app_definer;
GRANT INSERT ON tenants, memberships, compliance_policy_versions, tenant_settings, teams, team_members, ponds,
                tenant_keys, users, auth_tokens, auth_attempts, webhook_events TO app_definer;
GRANT UPDATE ON users, sessions, auth_tokens, auth_attempts, invites, memberships, webhook_events, jobs TO app_definer;
GRANT SELECT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_retention;
GRANT INSERT ON audit_log TO app_retention;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO app_definer, app_retention, app_user;

-- Helper functions callable by the app role (policies run as the caller).
GRANT EXECUTE ON FUNCTION app.tenant_id(), app.user_id(), app.actor_kind(), app.principal_type(), app.ownership_command()
  TO app_user, app_definer, app_retention;
GRANT EXECUTE ON FUNCTION app.lock_contact(uuid), app.lock_address(bytea),
  app.contact_visible(uuid,uuid), app.contact_detail_visible(uuid,uuid), app.deal_visible(uuid,uuid),
  app.deal_writable(uuid,uuid), app.listing_writable(uuid,uuid) TO app_user;
GRANT EXECUTE ON FUNCTION app.my_role(), app.is_tenant_wide(), app.is_member(), app.sees_all_detail(),
  app.my_team_member_ids(), app.my_pond_ids(), app.my_deal_ids(), app.my_deal_contact_ids(), app.my_collab_contact_ids(),
  app.recording_scope(), app.contact_exists(uuid,uuid) TO app_user, app_retention;
GRANT EXECUTE ON FUNCTION
  auth.login_lookup(citext), auth.record_login_result(uuid,boolean,timestamptz), auth.rate_limit_hit(text,timestamptz,integer),
  auth.resolve_session(bytea,timestamptz), auth.user_tenants(), auth.mfa_secret(),
  auth.issue_password_reset(citext,bytea,timestamptz), auth.consume_password_reset(bytea,text,timestamptz),
  auth.accept_invite(bytea,uuid,text,text,timestamptz),
  app.resolve_inbound_number(text), app.resolve_inbound_email_token(bytea), app.resolve_lead_source(bytea),
  app.record_webhook_event(uuid,text,text,uuid,boolean,bytea,timestamptz), app.finish_webhook_event(uuid,text,text,timestamptz),
  app.claim_jobs(text[],text,integer,interval), app.finish_job(bigint,text,boolean,text,timestamptz), app.reap_stuck_jobs(),
  app.cancel_jobs(text[]), app.due_work(timestamptz,integer), app.claim_stats(uuid,uuid,timestamptz,timestamptz),
  app.find_contacts_by_address(bytea[]), app.stage_dwell_norms(), app.revoke_member_sessions(uuid,timestamptz),
  app.provision_tenant(uuid,citext,text,text,text,uuid,uuid,uuid,uuid,bytea,bytea,bytea,text),
  app.erase_contact(uuid,uuid,text), app.retention_sweep(timestamptz)
  TO app_user;
GRANT EXECUTE ON FUNCTION app.purge_contact_internal(uuid,uuid) TO app_retention;

-- Table privileges for app_user. Mutable tables: SELECT, INSERT, UPDATE.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['tenant_settings','memberships','invites','teams','team_members','support_access_grants',
     'provider_credentials','stored_objects','tenant_keys','lead_sources','ponds','pond_members','routing_rules',
     'routing_rule_members','routing_rotation_state','import_batches','import_stages','import_records',
     'import_user_mappings','external_refs','contacts','contact_points','contact_addresses','contact_collaborators',
     'contact_attributes','lead_inquiries','contact_duplicate_candidates','consent_state','suppressions',
     'sender_registrations','phone_numbers','sending_domains','email_identities','conversations','messages',
     'message_media','calls','recordings','transcripts','ai_runs','playbooks','playbook_versions','playbook_enrollments',
     'assistant_actions','assistant_claims','evidence_refs','playbook_step_runs','listings','listing_contacts',
     'saved_searches','saved_search_matches','showings','showing_feedback','marketing_activity','home_valuations',
     'deals','deal_members','deal_contacts','deal_dates','deal_financials','agent_goals','notes','tasks','appointments',
     'priority_feed_items','exception_items','notifications','push_subscriptions','notification_deliveries',
     'notification_preferences'] LOOP
    EXECUTE format('GRANT SELECT, INSERT, UPDATE ON public.%I TO app_user', t);
  END LOOP;
  -- Append-only tables: SELECT + INSERT only (defense in depth on top of the triggers).
  FOREACH t IN ARRAY ARRAY['lead_ownership_events','consent_disclosures','consent_events','dnc_checks','gate_decisions',
     'message_status_events','behavior_events','playbook_approvals','listing_price_history','deal_stage_history',
     'exception_events','audit_log','compliance_policy_versions','ownership_command_rejections'] LOOP
    EXECUTE format('GRANT SELECT, INSERT ON public.%I TO app_user', t);
  END LOOP;
  -- Link tables that are genuinely deleted.
  FOREACH t IN ARRAY ARRAY['team_members','pond_members','routing_rule_members','deal_members','deal_contacts',
     'listing_contacts','notification_preferences','saved_search_matches'] LOOP
    EXECUTE format('GRANT DELETE ON public.%I TO app_user', t);
  END LOOP;
END $$;

GRANT SELECT ON tenants, jurisdiction_packs TO app_user;
GRANT SELECT (id, email, email_verified_at, display_name, mfa_enabled_at, disabled_at, created_at, updated_at) ON users TO app_user;
GRANT INSERT (id, email, display_name, password_hash, password_changed_at) ON users TO app_user;
GRANT UPDATE (display_name, password_hash, password_changed_at, mfa_totp_secret_enc, mfa_enabled_at) ON users TO app_user;
GRANT SELECT, INSERT, UPDATE ON sessions, mfa_recovery_codes TO app_user;
GRANT INSERT ON auth_events TO app_user;
GRANT INSERT ON jobs TO app_user;                 -- enqueue only; claim/finish via definer functions
GRANT SELECT ON contact_timeline, v_speed_to_lead, v_agent_activity_daily, v_pipeline_momentum TO app_user;

