-- -----------------------------------------------------------------------------
-- 22. Self-checks: fail the migration if an invariant is missing.
-- -----------------------------------------------------------------------------
DO $$
DECLARE r record; bad text := '';
BEGIN
  -- every public table has RLS enabled AND forced
  FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE n.nspname = 'public' AND c.relkind = 'r' AND NOT (c.relrowsecurity AND c.relforcerowsecurity) LOOP
    bad := bad || ' rls:' || r.relname;
  END LOOP;
  -- every tenant-scoped table has the restrictive tenant_isolation policy
  FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
             JOIN pg_attribute a ON a.attrelid = c.oid AND a.attname = 'tenant_id' AND NOT a.attisdropped
            WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relname NOT IN ('auth_events','webhook_events')
              AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = c.oid AND p.polname = 'tenant_isolation'
                                 AND NOT p.polpermissive) LOOP
    bad := bad || ' tenant_policy:' || r.relname;
  END LOOP;
  -- every tenant table except jobs has tenant_id NOT NULL as the leading primary-key column
  FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
             JOIN pg_attribute a ON a.attrelid = c.oid AND a.attname = 'tenant_id' AND NOT a.attisdropped
             LEFT JOIN pg_constraint pk ON pk.conrelid = c.oid AND pk.contype = 'p'
            WHERE n.nspname = 'public' AND c.relkind = 'r'
              AND c.relname NOT IN ('auth_events','webhook_events','jobs','tenant_settings')
              AND (NOT a.attnotnull OR pk.conkey[1] IS DISTINCT FROM a.attnum) LOOP
    bad := bad || ' pk_tenant_first:' || r.relname;
  END LOOP;
  -- tables with RLS on must have at least one permissive policy, or be definer-only by design
  FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE n.nspname = 'public' AND c.relkind = 'r'
              AND c.relname NOT IN ('auth_tokens','auth_attempts','webhook_events')
              AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = c.oid AND p.polpermissive) LOOP
    bad := bad || ' no_permissive:' || r.relname;
  END LOOP;
  -- app_user can never UPDATE/DELETE an append-only table
  FOR r IN SELECT t FROM unnest(ARRAY['lead_ownership_events','consent_events','gate_decisions','audit_log',
                 'playbook_approvals','behavior_events','exception_events','deal_stage_history','auth_events',
                 'ownership_command_rejections']) t
            WHERE has_table_privilege('app_user', 'public.' || t, 'UPDATE')
               OR has_table_privilege('app_user', 'public.' || t, 'DELETE') LOOP
    bad := bad || ' ao_grant:' || r.t;
  END LOOP;
  -- every SECURITY DEFINER function is owned by a NOLOGIN definer role and pins search_path
  FOR r IN SELECT p.oid::regprocedure::text AS fn FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
            WHERE n.nspname IN ('app','auth') AND p.prosecdef
              AND (pg_get_userbyid(p.proowner) NOT IN ('app_definer','app_retention')
                   OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) cfg WHERE cfg LIKE 'search_path=%')) LOOP
    bad := bad || ' definer:' || r.fn;
  END LOOP;
  IF bad <> '' THEN
    RAISE EXCEPTION 'SCHEMA SELF-CHECK FAILED:%', bad;
  END IF;
END $$;
